        const on_a = try rig.onMount("tail -c +19 own/f | sha256sum && head -c 18 own/f && stat -c %s own/f");
        defer gpa.free(on_a);
        try testing.expectEqualStrings(out, on_a);
    }
    // B creates and renames in A's directory (every step shipped to A).
    {
        const out = try b.onMount("echo b > shared/x && mv shared/x shared/y && ls shared");
        defer gpa.free(out);
        try testing.expectEqualStrings("y\n", out);
        const on_a = try rig.onMount("ls shared && cat shared/y");
        defer gpa.free(on_a);
        try testing.expectEqualStrings("y\nb\n", on_a);
    }
    {
        const tb = try b.stats();
        defer gpa.free(tb);
        try testing.expectEqual(@as(?u64, 1), numberAfter(tb, "\"member_rejoins_in_place\":"));
        try testing.expectEqual(@as(?u64, 1), numberAfter(tb, "\"meta_rejoins_in_place\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(tb, "\"appender_park_expiries\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(tb, "\"invariant_tripwires\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(tb, "\"appender_parked\":"));
        const ta = try rig.stats();
        defer gpa.free(ta);
        try testing.expect((numberAfter(ta, "\"membership_evictions\":") orelse 0) >= 1);
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"xv_cross_owner_steps_rejected\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"invariant_tripwires\":"));
    }
    try b.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try b.waitExit());
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    _ = try fsckClean(rig, "a live member re-joined in place");
}

test "smoke: A LIVE MEMBER EVICTED WITH UN-LANDED STATE FAIL-STOPS (the re-join's negative arm, decision 0003 §BS) — B JOINED under the close write-back posture (SQUEEZEFS_WRITEBACK_POSTURE=close: custody lands at the close) writes 64 KiB into `own/g` through an fd a process holds OPEN (acked, never published: write-side custody) → B's beat is HELD past T_owner ⇒ A evicts B and recovers its region → released: UnknownLease ⇒ B holds acked bytes no layout names ⇒ NO re-join: B fail-stops exactly as before (the park's expiry, POISONED, every volume FAILED) — a fresh op answers EIO within the bound (no fork: the custody is never published under a successor), umount B (exit 1, the crash shape: nothing written), A serves on with no tripwire → fsck --offline --scrub 0 findings" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.env.put("SQUEEZEFS_MW_BIND", "127.0.0.1:0");
    var t_owner_text: [8]u8 = undefined;
    try rig.env.put("SQUEEZEFS_TEST_MEMBERSHIP_T_OWNER_MS", try std.fmt.bufPrint(&t_owner_text, "{d}", .{smoke_t_owner_ms}));
    var fb: [linux.PATH_MAX]u8 = undefined;
    const fifo = try std.fmt.bufPrintSentinel(&fb, "{s}/beat.fifo", .{rig.work}, 0);
    try rig.env.put("SQUEEZEFS_TEST_MEMBERSHIP_BEAT_HOLD", fifo);
    try rig.formatSetWith(false, &.{});
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    const b = try Peer.init(rig, "b");
    defer b.deinit();
    var close_env = try rig.env.clone(gpa);
    defer close_env.deinit();
    try close_env.put("SQUEEZEFS_WRITEBACK_POSTURE", "close");
    b.env = &close_env;
    b.node = kill_peer_node;
    try b.spawn(&.{});
    _ = try b.awaitReady();
    {
        const out = try b.onMount("mkdir own && sync -f .");
        gpa.free(out);
    }
    // The custody: 64 KiB written through an fd held open (never closed,
    // never synced) — acked, its layout never published.
    var hb: [linux.PATH_MAX]u8 = undefined;
    const held = try std.fmt.bufPrint(&hb, "{s}/held", .{rig.work});
    var gb: [linux.PATH_MAX]u8 = undefined;
    const go = try std.fmt.bufPrint(&gb, "{s}/go", .{rig.work});
    var holder = try std.process.spawn(io, .{ .argv = &.{ "sh", "-c", "exec 3>\"$0/own/g\" && head -c 65536 /dev/urandom >&3 && : > \"$1\" && while [ ! -e \"$2\" ]; do sleep 0.05; done", b.mp, held, go }, .environ_map = &rig.env, .stdin = .ignore });
    var holder_done = false;
    defer if (!holder_done) {
        _ = linux.kill(holder.id.?, .KILL);
        _ = holder.wait(io) catch {};
    };
    {
        const deadline = clock.monotonicNs() + kill_row_wait_ns;
        while (true) {
            Io.Dir.cwd().access(io, held, .{}) catch {
                if (clock.monotonicNs() >= deadline) return error.Timeout;
                sleepMs(20);
                continue;
            };
            break;
        }
    }
    var released = false;
    defer if (!released) releaseHold(fifo);
    const mark = try rig.logLen();
    const b_mark = try b.logLen();
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.mknodat(linux.AT.FDCWD, fifo.ptr, linux.S.IFIFO | 0o600, 0)));
    _ = try b.awaitLog("the member's beat holds", b_mark, kill_row_wait_ns);
    try awaitEvictionOf(rig, b, mark);
    releaseHold(fifo);
    released = true;
    const v = try awaitEvictionVerdict(b, b_mark);
    try testing.expectEqual(EvictionVerdict.poisoned, v.verdict);
    {
        const tb = try b.readLog();
        defer gpa.free(tb);
        try testing.expect(std.mem.indexOf(u8, tb[b_mark..], "cannot re-join in place — write-side custody on 1 ino(s)") != null);
        try testing.expect(std.mem.indexOf(u8, tb[b_mark..], "RE-JOINED IN PLACE") == null);
    }
    // The fail-stop: an op answers EIO within the bound.
    {
        var secs: [8]u8 = undefined;
        const r = try std.process.run(gpa, io, .{ .argv = &.{ "timeout", "-s", "KILL", try std.fmt.bufPrint(&secs, "{d}", .{poison_fail_stop_bound_s}), "sh", "-c", "touch \"$0/own/after-poison\"", b.mp }, .environ_map = &rig.env });
        defer rig.freeRun(r);
        if (r.term == .signal) {
            printWedge(io, "b", b.pid, b.log_path, gpa);
            abortFuseConnectionOf(io, b.mp);
            return error.PoisonedMountHeldArrivingOp;
        }
        try testing.expect(!r.term.success());
        try testing.expect(std.mem.indexOf(u8, r.stderr, "Input/output error") != null);
    }
    {
        const f = try Io.Dir.cwd().createFile(io, go, .{ .truncate = true });
        f.close(io);
        _ = try holder.wait(io);
        holder_done = true;
    }
    {
        const ta = try rig.stats();
        defer gpa.free(ta);
        try testing.expect((numberAfter(ta, "\"membership_evictions\":") orelse 0) >= 1);
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"invariant_tripwires\":"));
    }
    try b.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, try b.waitExit());
    {
        const tb = try b.readLog();
        defer gpa.free(tb);
        try testing.expect(std.mem.indexOf(u8, tb[b_mark..], "the leave writes nothing (the crash shape") != null);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    _ = try fsckClean(rig, "a live member evicted with un-landed state");
}

/// The member's renew cadence its mount line names (`renew every N ms`).
fn renewMsOf(text: []const u8) ?u64 {
    return numberAfter(text, "renew every ");
}

test "smoke: A LIVE MEMBER'S SLOW FOLLOW-UP NEVER COSTS ITS LEASE — THE DEAD MANAGER'S DOUBLE PARK UNDER LOAD (the kill matrix's second park, 2026-10-24) — A (the manager) holds `hot` striped over K = 64; B JOINED storms creates into it → kill -9 A ⇒ B PARKS at T_self → remount A (term 2) → B's reclaim lands in the grace window → B's FOLLOW-UP (its wire duties besides the renewal: the census pull, the re-point, the re-publication, the set-config learn) is HELD (SQUEEZEFS_TEST_MEMBERSHIP_FOLLOW_HOLD: a call to the freshly remounted manager slow past T_owner, what the gate's load did) while the storm goes on ⇒ B's renewals go on at their cadence through 2 × T_owner (the beat waits on nothing else): A evicts nobody, B never parks a second time, no UnknownLease, no poison → released: the follow-up completes, the storm ends, `ls` = `find` and the stat digest equal from A and B, no open intent → umount B (exit 0), A → fsck --offline --scrub 0 findings (red: the follow-up ran on the beat — B's committers parked the gate at T_self, A evicted the live B at T_owner, the reclaim met UnknownLease, B POISONED: the double park)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.env.put("SQUEEZEFS_MW_BIND", "127.0.0.1:0");
    var t_owner_text: [8]u8 = undefined;
    try rig.env.put("SQUEEZEFS_TEST_MEMBERSHIP_T_OWNER_MS", try std.fmt.bufPrint(&t_owner_text, "{d}", .{smoke_t_owner_ms}));
    // The hold's FIFO is NAMED now and CREATED when the hold should begin.
    var fb: [linux.PATH_MAX]u8 = undefined;
    const fifo = try std.fmt.bufPrintSentinel(&fb, "{s}/follow.fifo", .{rig.work}, 0);
    try rig.env.put("SQUEEZEFS_TEST_MEMBERSHIP_FOLLOW_HOLD", fifo);
    try rig.formatSetWith(false, &.{});
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    const b = try Peer.init(rig, "b");
    defer b.deinit();
    b.node = kill_peer_node;
    try b.spawn(&.{});
    _ = try b.awaitReady();
    const renew_ms = blk: {
        const tb = try b.readLog();
        defer gpa.free(tb);
        break :blk renewMsOf(tb) orelse return error.RenewCadenceUnlogged;
    };
    {
        const mk = try rig.onMount("mkdir hot");
        gpa.free(mk);
        var sbuf: [256]u8 = undefined;
        const out = try rig.onMount(try setStripesScript(&sbuf, "hot", 64));
        gpa.free(out);
    }
    var storm_b = try Storm.start(rig, b.mp, "b", "b");
    var storm_done = false;
    defer if (!storm_done) storm_b.deinit(rig);
    var released = false;
    defer if (!released) releaseHold(fifo);
    {
        const warm = try awaitAtLeast(b, "\"dir_stripe_routed_mutations\":", stripe_matrix_phase_floor, kill_row_wait_ns);
        gpa.free(warm);
    }
    // The first park and the reclaim: the DEAD MANAGER row's shape.
    try rig.kill();
    _ = try b.awaitLog("appender park: T_self reached with the home volume 0's manager unreachable — parked", 0, kill_row_wait_ns);
    var mark = try rig.logLen();
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(mark);
    {
        const reclaimed = try awaitStats(b, &.{.{ .key = "\"appender_parked\":", .want = 0 }}, kill_row_wait_ns);
        defer gpa.free(reclaimed);
        try testing.expectEqual(@as(?u64, 0), numberAfter(reclaimed, "\"appender_park_expiries\":"));
    }
    const first_park_end = try b.awaitLog("admitted the reclaim", 0, kill_row_wait_ns);
    // The hold: B's follow-up parks at its next duty; the storm goes on.
    mark = try rig.logLen();
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.mknodat(linux.AT.FDCWD, fifo.ptr, linux.S.IFIFO | 0o600, 0)));
    _ = try b.awaitLog("the member's follow-up holds", first_park_end, kill_row_wait_ns);
    const t_hold = clock.monotonicNs();
    // Through 2 × T_owner of the hold B's renewals advance at their
    // cadence: consecutive renewals are at least one renew interval apart,
    // so this many of them span 2 × T_owner of wall time.
    const renewals_want_delta = (2 * smoke_t_owner_ms + renew_ms - 1) / renew_ms + 1;
    const renewals0 = blk: {
        const tb = try b.stats();
        defer gpa.free(tb);
        break :blk numberAfter(tb, "\"member_renewals\":") orelse return error.MemberRenewalsUnread;
    };
    var renewals = renewals0;
    {
        const deadline = clock.monotonicNs() + kill_row_wait_ns;
        // The red path watches the whole chain before it fails: B's second
        // park (its committers at T_self), A's eviction at T_owner, then —
        // the hold released — the reclaim's answer.
        var second_park_ms: ?u64 = null;
        var evicted_ms: ?u64 = null;
        while (renewals < renewals0 + renewals_want_delta) {
            const in_hold_ms = (clock.monotonicNs() - t_hold) / std.time.ns_per_ms;
            if (evicted_ms == null) {
                const ta = try rig.readLog();
                defer gpa.free(ta);
                if (ta.len > mark and evictedAtTOwner(ta[mark..]) >= 1) evicted_ms = in_hold_ms;
            }
            if (second_park_ms == null) {
                const tb = try b.readLog();
                defer gpa.free(tb);
                if (std.mem.indexOf(u8, tb[first_park_end..], "appender park: T_self reached") != null) second_park_ms = in_hold_ms;
            }
            if (evicted_ms != null or (second_park_ms != null and in_hold_ms >= 3 * smoke_t_owner_ms)) {
                releaseHold(fifo);
                released = true;
                const poisoned = if (b.awaitLog("this joined mount is POISONED", first_park_end, 10 * std.time.ns_per_s)) |_| true else |_| false;
                std.debug.print("\nsmoke: the DOUBLE PARK behind B's follow-up: B renewed {d} time(s) through the hold; its committers parked the gate at T_self {?d} ms into it; A evicted the live B at T_owner {?d} ms into it; released, the reclaim {s}\n", .{ renewals - renewals0, second_park_ms, evicted_ms, if (poisoned) "met UnknownLease — B POISONED" else "landed" });
                return error.LiveMemberEvictedBehindItsFollowUp;
            }
            try rig.expectAlive("B's renewals through the follow-up's hold");
            try b.expectAlive("B's renewals through the follow-up's hold");
            if (clock.monotonicNs() >= deadline) return error.Timeout;
            sleepMs(50);
            const tb = try b.stats();
            defer gpa.free(tb);
            renewals = numberAfter(tb, "\"member_renewals\":") orelse renewals;
        }
        try testing.expectEqual(@as(?u64, null), second_park_ms);
    }
    const held_ms = (clock.monotonicNs() - t_hold) / std.time.ns_per_ms;
    try testing.expect(held_ms >= 2 * smoke_t_owner_ms);
    {
        const tb = try b.readLog();
        defer gpa.free(tb);
        try testing.expect(std.mem.indexOf(u8, tb, "FOLLOW_HOLD released") == null);
        try testing.expect(std.mem.indexOf(u8, tb, "POISONED") == null);
        const sb = try b.stats();
        defer gpa.free(sb);
        try testing.expectEqual(@as(?u64, 0), numberAfter(sb, "\"appender_parked\":"));
        const sa = try rig.stats();
        defer gpa.free(sa);
        try testing.expectEqual(@as(?u64, 0), numberAfter(sa, "\"membership_evictions\":"));
    }
    // Released: the follow-up completes, the storm settles.
    releaseHold(fifo);
    released = true;
    _ = try b.awaitLog("FOLLOW_HOLD released", first_park_end, kill_row_wait_ns);
    {
        const now_b = try b.stats();
        defer gpa.free(now_b);
        const settled = try awaitAtLeast(b, "\"dir_stripe_routed_mutations\":", (numberAfter(now_b, "\"dir_stripe_routed_mutations\":") orelse 0) + 50, kill_row_wait_ns);
        gpa.free(settled);
    }
    const nb = try storm_b.finish(rig);
    storm_done = true;
    storm_b.err_file.close(io);
    gpa.free(storm_b.stop);
    gpa.free(storm_b.count);
    {
        const ob = try awaitExactly(b, "\"xv_cross_owner_intents_open\":", 0, 2 * kill_row_wait_ns);
        defer gpa.free(ob);
        try testing.expectEqual(@as(?u64, 0), numberAfter(ob, "\"xv_cross_owner_intents_stuck\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(ob, "\"appender_park_expiries\":"));
        const va = try hotView(rig, "a");
        defer gpa.free(va);
        const vb = try hotView(b, "b");
        defer gpa.free(vb);
        if (!std.mem.eql(u8, va, vb) or !lsEqualsFind(va)) reportHotViews(rig, &.{ .{ .tag = "a", .mp = rig.mp }, .{ .tag = "b", .mp = b.mp } });
        try testing.expectEqualStrings(va, vb);
        var lines = std.mem.splitScalar(u8, va, '\n');
        const listed = try std.fmt.parseInt(u64, std.mem.trim(u8, lines.next().?, " "), 10);
        // Every counted name; at most one more (a create whose reply the
        // death lost, counted only when its retry met it).
        try testing.expect(listed >= nb and listed <= nb + 1);
        const ta = try rig.stats();
        defer gpa.free(ta);
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"membership_evictions\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"xv_cross_owner_steps_rejected\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"invariant_tripwires\":"));
        std.debug.print("\nsmoke: slow follow-up: B's follow-up held {d} ms (2 × T_owner = {d} ms) — B renewed {d} time(s) through it at {d} ms, A evicted nobody, B parked once (A's death); B created {d} across the death; {d} entries listed (ls = find), the digest equal from A and B\n", .{ held_ms, 2 * smoke_t_owner_ms, renewals - renewals0, renew_ms, nb, listed });
    }
    try b.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try b.waitExit());
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    _ = try fsckClean(rig, "a live member's slow follow-up");
}

/// The striped directory's population: 10,000 names over K = 64 stripes
/// (≈ 156 per stripe — the readdir merge reads every stripe's page set
/// several times over; the rename storm's 1,000 moves cross stripes with
/// probability 63/64).
const stripe_row_files: usize = 10_000;
const stripe_row_renames: usize = 1_000;

/// `setfattr -n user.squeezefs.stripes -v K <dir>` without `attr` in the
/// image: python's `os.setxattr` is the handler's own xattr path.
fn setStripesScript(buf: []u8, dir: []const u8, k: u32) ![]const u8 {
    return std.fmt.bufPrint(buf, "python3 -c 'import os,sys; os.setxattr(sys.argv[1], \"user.squeezefs.stripes\", sys.argv[2].encode())' {s} {d}", .{ dir, k });
}

fn getStripesScript(buf: []u8, dir: []const u8) ![]const u8 {
    return std.fmt.bufPrint(buf, "python3 -c 'import os,sys; sys.stdout.write(os.getxattr(sys.argv[1], \"user.squeezefs.stripes\").decode())' {s}", .{dir});
}

test "smoke: A STRIPED DIRECTORY ON ONE DAEMON — mkdir hot → the explicit flip (`user.squeezefs.stripes` = 64 through setxattr; getxattr answers 64, a plain directory ENODATA) → 10,000 creates key their stripes (dir_stripe_routed_mutations ≥ 10,000; D's own tree holds the 66 markers alone) → `ls | wc -l` = 10,000 and `find` = 10,001 (the K-way merge, every name once) → a 1,000-move rename storm across stripes, every target present, every source gone → stat's nlink folds a subdirectory in → rm -rf: the striped rmdir is ONE intent → umount → fsck --offline --scrub 0 findings (C17 clean)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.env.put("SQUEEZEFS_MW_BIND", "127.0.0.1:0");
    try rig.formatSetWith(false, &.{});
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    var sbuf: [512]u8 = undefined;
    // The flip: ENODATA before, 64 after; a second flip refuses EEXIST.
    {
        const out = try rig.onMount("mkdir hot plain && if python3 -c 'import os,sys; os.getxattr(sys.argv[1], \"user.squeezefs.stripes\")' hot 2>/dev/null; then echo had-k; else echo no-k; fi");
        defer gpa.free(out);
        try testing.expectEqualStrings("no-k\n", out);
    }
    {
        const out = try rig.onMount(try setStripesScript(&sbuf, "hot", 64));
        gpa.free(out);
        const k = try rig.onMount(try getStripesScript(&sbuf, "hot"));
        defer gpa.free(k);
        try testing.expectEqualStrings("64\n", k);
        const again = try rig.sh(rig.mp, try setStripesScript(&sbuf, "hot", 8));
        defer rig.freeRun(again);
        try testing.expect(!again.term.success());
        try testing.expect(std.mem.indexOf(u8, again.stderr, "File exists") != null);
        const plain = try rig.sh(rig.mp, try getStripesScript(&sbuf, "plain"));
        defer rig.freeRun(plain);
        try testing.expect(!plain.term.success());
    }
    // 10,000 creates through the shell, then the counts.
    {
        var script: std.Io.Writer.Allocating = .init(gpa);
        defer script.deinit();
        try script.writer.print("cd hot && i=0; while [ $i -lt {d} ]; do : > f$i; i=$((i+1)); done; cd ..; ls hot | wc -l; find hot | wc -l; find hot -name 'f*' | wc -l", .{stripe_row_files});
        const out = try rig.onMountTimed(script.written(), 600);
        defer gpa.free(out);
        var lines = std.mem.splitScalar(u8, std.mem.trimEnd(u8, out, "\n"), '\n');
        try testing.expectEqualStrings(try std.fmt.bufPrint(&sbuf, "{d}", .{stripe_row_files}), std.mem.trim(u8, lines.next().?, " "));
        try testing.expectEqualStrings(try std.fmt.bufPrint(&sbuf, "{d}", .{stripe_row_files + 1}), std.mem.trim(u8, lines.next().?, " "));
        try testing.expectEqualStrings(try std.fmt.bufPrint(&sbuf, "{d}", .{stripe_row_files}), std.mem.trim(u8, lines.next().?, " "));
    }
    {
        const ta = try rig.stats();
        defer gpa.free(ta);
        try testing.expectEqual(@as(?u64, 1), numberAfter(ta, "\"dir_stripe_flips\":"));
        try testing.expectEqual(@as(?u64, 1), numberAfter(ta, "\"dir_striped_dirs\":"));
        try testing.expect((numberAfter(ta, "\"dir_stripe_routed_mutations\":") orelse 0) >= stripe_row_files);
        try testing.expect((numberAfter(ta, "\"dir_stripe_readdir_merges\":") orelse 0) >= 1);
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"dir_stripe_dying_refusals\":"));
    }
    // The rename storm across stripes: every target present, every source
    // gone, the count unchanged.
    {
        var script: std.Io.Writer.Allocating = .init(gpa);
        defer script.deinit();
        try script.writer.print("cd hot && i=0; while [ $i -lt {d} ]; do mv f$i r$i; i=$((i+1)); done; i=0; while [ $i -lt {d} ]; do test -e r$i; test ! -e f$i; i=$((i+1)); done; ls | wc -l", .{ stripe_row_renames, stripe_row_renames });
        const out = try rig.onMountTimed(script.written(), 600);
        defer gpa.free(out);
        try testing.expectEqualStrings(try std.fmt.bufPrint(&sbuf, "{d}\n", .{stripe_row_files}), out);
    }
    // stat: the fold — a subdirectory inside bumps D's nlink.
    {
        const out = try rig.onMount("stat -c %h hot; mkdir hot/sub; stat -c %h hot; rmdir hot/sub; stat -c %h hot");
        defer gpa.free(out);
        try testing.expectEqualStrings("2\n3\n2\n", out);
    }
    // rm -rf: every name through its stripe, then the striped rmdir.
    {
        const out = try rig.onMountTimed("rm -rf hot && test ! -e hot && ls | wc -l", 600);
        defer gpa.free(out);
        try testing.expectEqualStrings("1\n", out);
        const ta = try rig.stats();
        defer gpa.free(ta);
        try testing.expectEqual(@as(?u64, 1), numberAfter(ta, "\"dir_stripe_rmdirs\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"dir_striped_dirs\":"));
        try expectMustStayZero(ta);
        std.debug.print("\nsmoke: striped directory on one daemon — flips {d}, routed lookups {d}, routed mutations {d}, readdir merges {d}, verdict hits {d} / reads {d}, rmdirs {d}\n", .{ numberAfter(ta, "\"dir_stripe_flips\":") orelse 0, numberAfter(ta, "\"dir_stripe_routed_lookups\":") orelse 0, numberAfter(ta, "\"dir_stripe_routed_mutations\":") orelse 0, numberAfter(ta, "\"dir_stripe_readdir_merges\":") orelse 0, numberAfter(ta, "\"dir_stripe_verdict_hits\":") orelse 0, numberAfter(ta, "\"dir_stripe_verdict_reads\":") orelse 0, numberAfter(ta, "\"dir_stripe_rmdirs\":") orelse 0 });
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    _ = try fsckClean(rig, "the striped directory row");
}

/// xfstests' `common/renameat2` matrix under `RENAME_EXCHANGE` (generic/025:
/// every (src kind, dst kind) over none/regu/symb/dire/tree, same directory
/// and across two), with the parents' `st_nlink` judged against the law
/// after the setup, after the swap and after the cleanup — then the
/// surviving shapes `keep/p1..p7` (a dir ↔ file swap across parents, a
/// dir ↔ dir, a same-parent file ↔ dir, a tree ↔ symlink) whose counts the
/// remount must answer unchanged. `renameat2(2)` through glibc's wrapper
/// (no `renameat2` binary in the image).
const exchange_matrix_py =
    \\import ctypes, os, sys
    \\libc = ctypes.CDLL(None, use_errno=True)
    \\libc.renameat2.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
    \\AT_FDCWD, RENAME_EXCHANGE = -100, 2
    \\def xchg(a, b):
    \\    if libc.renameat2(AT_FDCWD, a.encode(), AT_FDCWD, b.encode(), RENAME_EXCHANGE) != 0:
    \\        return ctypes.get_errno()
    \\    return 0
    \\def setup(p, k):
    \\    if k == 'regu': open(p, 'w').write('foo\n')
    \\    elif k == 'symb': os.symlink('foo', p)
    \\    elif k == 'dire': os.mkdir(p)
    \\    elif k == 'tree': os.mkdir(p); open(p + '/bar', 'w').write('foo\n')
    \\def cleanup(p):
    \\    if os.path.isdir(p) and not os.path.islink(p):
    \\        if os.path.exists(p + '/bar'): os.unlink(p + '/bar')
    \\        os.rmdir(p)
    \\    elif os.path.lexists(p): os.unlink(p)
    \\def kind(p):
    \\    if not os.path.lexists(p): return 'none'
    \\    if os.path.islink(p): return 'symb'
    \\    if os.path.isdir(p): return 'tree' if os.path.exists(p + '/bar') else 'dire'
    \\    return 'regu'
    \\isdir = lambda k: k in ('dire', 'tree')
    \\def nl(p): return os.lstat(p).st_nlink
    \\def judge(label, px, py, want_x, want_y):
    \\    got = (nl(px), nl(py))
    \\    if got != (want_x, want_y):
    \\        sys.exit('%s: nlink(%s, %s) = %r, the law says %r' % (label, px, py, got, (want_x, want_y)))
    \\kinds = ['none', 'regu', 'symb', 'dire', 'tree']
    \\def matrix(src, dst, px, py, base_x, base_y, label):
    \\    for s in kinds:
    \\        for d in kinds:
    \\            cell = '%s %s/%s' % (label, s, d)
    \\            setup(src, s); setup(dst, d)
    \\            same = px == py
    \\            x_dirs = isdir(s) + (isdir(d) if same else 0)
    \\            y_dirs = isdir(d) + (isdir(s) if same else 0)
    \\            judge(cell + ' after setup', px, py, base_x + x_dirs, base_y + y_dirs)
    \\            e = xchg(src, dst)
    \\            if s == 'none' or d == 'none':
    \\                if e != 2: sys.exit('%s: exchange with an absent side answered errno %d, not ENOENT' % (cell, e))
    \\            else:
    \\                if e != 0: sys.exit('%s: exchange failed: %s' % (cell, os.strerror(e)))
    \\                if (kind(src), kind(dst)) != (d, s): sys.exit('%s: kinds after the swap %r' % (cell, (kind(src), kind(dst))))
    \\                if not same: x_dirs, y_dirs = isdir(d), isdir(s)
    \\            judge(cell + ' after the swap', px, py, base_x + x_dirs, base_y + y_dirs)
    \\            cleanup(src); cleanup(dst)
    \\            judge(cell + ' after the cleanup', px, py, base_x, base_y)
    \\os.chdir(sys.argv[1])
    \\os.mkdir('t'); os.mkdir('t/x'); os.mkdir('t/y')
    \\matrix('t/src', 't/dst', 't', 't', 4, 4, 'samedir')
    \\matrix('t/x/src', 't/y/dst', 't/x', 't/y', 2, 2, 'crossdir')
    \\os.rmdir('t/x'); os.rmdir('t/y'); os.rmdir('t')
    \\os.mkdir('keep')
    \\for p in 'p1 p2 p3 p4 p5 p6 p7'.split(): os.mkdir('keep/' + p)
    \\setup('keep/p1/d', 'dire'); setup('keep/p2/f', 'regu')
    \\setup('keep/p3/d1', 'dire'); setup('keep/p4/d2', 'dire')
    \\setup('keep/p5/f1', 'regu'); setup('keep/p5/d', 'dire')
    \\setup('keep/p6/a', 'tree'); setup('keep/p7/l', 'symb')
    \\for a, b in (('keep/p1/d', 'keep/p2/f'), ('keep/p3/d1', 'keep/p4/d2'), ('keep/p5/f1', 'keep/p5/d'), ('keep/p6/a', 'keep/p7/l')):
    \\    e = xchg(a, b)
    \\    if e: sys.exit('%s <-> %s: %s' % (a, b, os.strerror(e)))
    \\print('matrix done')
;

/// The surviving shapes' counts, `keep/p1..p7` — the law: 2 + the
/// directories each holds AFTER the swaps (p2 and p7 received a directory,
/// p1 and p6 gave theirs up, p3/p4 traded one for one, p5 swapped in place).
const exchange_keep_nlinks = "2 3 3 3 3 2 3\n";
const exchange_keep_stat = "stat -c %h keep/p1 keep/p2 keep/p3 keep/p4 keep/p5 keep/p6 keep/p7 | tr '\\n' ' ' | sed 's/ $/\\n/'; test -d keep/p2/f; test -f keep/p1/d; test -d keep/p3/d1; test -d keep/p4/d2; test -d keep/p5/f1; test -f keep/p5/d; test -L keep/p6/a; test -f keep/p7/l/bar";

test "smoke: RENAME_EXCHANGE AND THE PARENTS' NLINK (fstests generic/025: the matrix's cross-directory dir ↔ file swaps shifted no parent count — the cleanup's rmdir fired `dir_nlink_underflows` ×4 and the other parent stayed inflated; both tests PASSED their golden output and fsck saw nothing, the parents being gone) — xfstests' renameat2 matrix (5 × 5 kinds, same directory and across two) with every parent's st_nlink judged after the setup, the swap and the cleanup → the surviving shapes keep/p1..p7 at `2 3 3 3 3 2 3` → `dir_nlink_underflows` 0 → umount, remount: the same counts off the records → fsck --offline --scrub 0 findings" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    {
        const py = try std.fmt.allocPrint(gpa, "{s}/exchange_matrix.py", .{rig.work});
        defer gpa.free(py);
        try Io.Dir.cwd().writeFile(io, .{ .sub_path = py, .data = exchange_matrix_py });
        const script = try std.fmt.allocPrint(gpa, "python3 {s} .", .{py});
        defer gpa.free(script);
        const out = try rig.onMountTimed(script, 600);
        defer gpa.free(out);
        try testing.expectEqualStrings("matrix done\n", out);
    }
    {
        const out = try rig.onMount(exchange_keep_stat);
        defer gpa.free(out);
        try testing.expectEqualStrings(exchange_keep_nlinks, out);
    }
    {
        const ta = try rig.stats();
        defer gpa.free(ta);
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"dir_nlink_underflows\":"));
        try expectMustStayZero(ta);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    // The remount answers off the records: the same counts, the same kinds.
    const mark = try rig.logLen();
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(mark);
    {
        const out = try rig.onMount(exchange_keep_stat);
        defer gpa.free(out);
        try testing.expectEqualStrings(exchange_keep_nlinks, out);
        const ta = try rig.stats();
        defer gpa.free(ta);
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"dir_nlink_underflows\":"));
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    _ = try fsckClean(rig, "the rename-exchange nlink row");
    std.debug.print("\nsmoke: rename exchange — the 50-cell matrix judged at every step, keep/p1..p7 at {s}", .{exchange_keep_nlinks});
}

/// The atime row's shell: POSIX sh, `stat -c %.9X` (nanoseconds), every
/// judgement a named line; `access_delay` is generic/003's (1 s; the
/// stamps are nanoseconds, the sleeps keep the row honest about a
/// coarse clock). `$1` = the mountpoint (for the kernel's flag remounts:
/// the classic `mount(2)` — libmount's new-API `fsconfig` reconfigure of
/// a FUSE superblock is refused by `fuse_parse_param`, as xfstests'
/// `LIBMOUNT_FORCE_MOUNT2=always` knows).
const atime_sh_lib =
    \\mp=$1
    \\export LIBMOUNT_FORCE_MOUNT2=always
    \\at() { stat -c %.9X "$1"; }
    \\mt() { stat -c %.9Y "$1"; }
    \\ct() { stat -c %.9Z "$1"; }
    \\same() { [ "$1" = "$2" ] || { echo "FAIL $3: $1 != $2"; exit 1; }; }
    \\moved() { [ "$1" != "$2" ] || { echo "FAIL $3: $1 == $2"; exit 1; }; }
    \\later() { awk -v a="$1" -v b="$2" 'BEGIN { exit !(b > a) }' || { echo "FAIL $3: $2 is not later than $1"; exit 1; }; }
    \\# read FILE (generic/003's `cat`) and judge: Y the atime moved past the sample, N it did not; mtime and ctime never move on a read
    \\readj() { f=$1; want=$2; tag=$3; a0=$(at "$f"); m0=$(mt "$f"); c0=$(ct "$f"); sleep 1.1; cat "$f" > /dev/null; a1=$(at "$f"); if [ "$want" = Y ]; then later "$a0" "$a1" "$tag atime"; else same "$a0" "$a1" "$tag atime"; fi; same "$m0" "$(mt "$f")" "$tag mtime"; same "$c0" "$(ct "$f")" "$tag ctime"; }
    \\listj() { d=$1; want=$2; tag=$3; a0=$(at "$d"); m0=$(mt "$d"); sleep 1.1; ls "$d" > /dev/null; a1=$(at "$d"); if [ "$want" = Y ]; then later "$a0" "$a1" "$tag atime"; else same "$a0" "$a1" "$tag atime"; fi; same "$m0" "$(mt "$d")" "$tag mtime"; }
    \\posture() { awk -v mp="$mp" '$5 == mp { o = $6 } END { print o }' /proc/self/mountinfo; }
    \\
;

/// Phase 1 (the mount is the kernel's default, relatime): generic/003's
/// first arm — the first read after the write moves atime alone, the
/// second does not, a directory's first listing does, its second does
/// not, a symlink's readlink does.
const atime_sh_relatime = atime_sh_lib ++
    \\mkdir dir1; echo aaa > dir1/file1; ln -s file1 dir1/link1
    \\readj dir1/file1 Y "relatime first read"
    \\readj dir1/file1 N "relatime second read"
    \\listj dir1 Y "relatime first listing"
    \\listj dir1 N "relatime second listing"
    \\l0=$(at dir1/link1); sleep 1.1; readlink dir1/link1 > /dev/null; later "$l0" "$(at dir1/link1)" "relatime readlink"
    \\echo "relatime ok $(posture)"
    \\
;

/// Phase 2: `-o remount,relatime,nodiratime` (the kernel's flag remount;
/// the daemon learns it from the mount table) — a directory a file was
/// just made in stays put under its listing, the file's read moves.
/// (mount(8) merges the standing flags into a remount, so every remount
/// below names its whole atime set.)
const atime_sh_nodiratime = atime_sh_lib ++
    \\mount -i -o remount,relatime,nodiratime "$mp"
    \\case ",$(posture)," in *,nodiratime,*) ;; *) echo "FAIL posture: $(posture)"; exit 1 ;; esac
    \\mkdir dir2; echo bbb > dir2/file2
    \\listj dir2 N "nodiratime listing"
    \\readj dir2/file2 Y "nodiratime file read"
    \\echo "nodiratime ok $(posture)"
    \\
;

/// Phase 3: `-o remount,strictatime` — three `cat`s of a file read already
/// (relatime would move none; the second and third are opens the kernel
/// would have served from its page cache under FOPEN_KEEP_CACHE — a
/// strictatime open drops it) all move; `-o remount,noatime` — a new
/// file's first read does not, a write still moves mtime and ctime;
/// `-o remount,ro,strictatime` — nothing moves; back to `rw,relatime`
/// — the written file's first read moves again.
const atime_sh_strict_noatime_ro = atime_sh_lib ++
    \\mount -i -o remount,strictatime,diratime "$mp"
    \\case ",$(posture)," in *,relatime,*|*,noatime,*|*,nodiratime,*) echo "FAIL posture: $(posture)"; exit 1 ;; esac
    \\readj dir1/file1 Y "strictatime first read"
    \\readj dir1/file1 Y "strictatime second read"
    \\readj dir1/file1 Y "strictatime third read"
    \\mount -i -o remount,noatime,diratime "$mp"
    \\case ",$(posture)," in *,noatime,*) ;; *) echo "FAIL posture: $(posture)"; exit 1 ;; esac
    \\echo ccc > dir2/file3
    \\readj dir2/file3 N "noatime first read"
    \\a0=$(at dir1/file1); m0=$(mt dir1/file1); c0=$(ct dir1/file1); sleep 1.1; echo xyz > dir1/file1
    \\same "$a0" "$(at dir1/file1)" "noatime write atime"; later "$m0" "$(mt dir1/file1)" "noatime write mtime"; later "$c0" "$(ct dir1/file1)" "noatime write ctime"
    \\mount -i -o remount,ro,strictatime,diratime "$mp"
    \\readj dir2/file3 N "ro,strictatime read"
    \\listj dir2 N "ro,strictatime listing"
    \\mount -i -o remount,rw,relatime,diratime "$mp"
    \\case ",$(posture)," in *,relatime,*) ;; *) echo "FAIL posture: $(posture)"; exit 1 ;; esac
    \\readj dir1/file1 Y "relatime after the write"
    \\readj dir1/file1 N "relatime after the write, second"
    \\stat -c '%n %.9X %.9Y %.9Z' dir1 dir1/file1 dir1/link1 dir2 dir2/file2 dir2/file3 > "$2/atime-before"
    \\echo "strict/noatime/ro ok"
    \\
;

/// Phase 4 (a fresh mount of the same set): every stamp as the previous
/// mount showed it — the parked stamps were journaled by the drain and the
/// dismount (charter §5.2: acked in RAM, durable at the next commit).
const atime_sh_remounted = atime_sh_lib ++
    \\stat -c '%n %.9X %.9Y %.9Z' dir1 dir1/file1 dir1/link1 dir2 dir2/file2 dir2/file3 > "$2/atime-after"
    \\cmp "$2/atime-before" "$2/atime-after" || { echo "FAIL remount: the stamps moved"; diff "$2/atime-before" "$2/atime-after"; exit 1; }
    \\echo "remount ok"
    \\
;

/// Phase 5: `SQUEEZEFS_ATIME=noatime` over a relatime kernel mount — a
/// written file's first read moves nothing; `=strictatime` — two reads both
/// move (nodiratime stays the mount's: the listing does not).
const atime_sh_knob_noatime = atime_sh_lib ++
    \\case ",$(posture)," in *,relatime,*) ;; *) echo "FAIL posture: $(posture)"; exit 1 ;; esac
    \\echo ddd > dir1/file4
    \\readj dir1/file4 N "knob noatime read"
    \\echo "knob noatime ok"
    \\
;
const atime_sh_knob_strict = atime_sh_lib ++
    \\mount -i -o remount,relatime,nodiratime "$mp"
    \\readj dir1/file4 Y "knob strictatime first read"
    \\readj dir1/file4 Y "knob strictatime second read"
    \\listj dir1 N "knob strictatime under the mount's nodiratime"
    \\echo "knob strictatime ok"
    \\
;

test "smoke: ATIME — RELATIME, STRICTATIME, NOATIME ARE THE KERNEL MOUNT'S (fstests generic/003 and 192; charter §4 'Access time') — format → mount (the kernel's relatime): the first read after a write moves atime alone (mtime, ctime unmoved), the second does not, a directory's first listing does, a readlink does → `mount -o remount,nodiratime` (the daemon learns the flag from the mount table, nothing from the kernel): a fresh directory's listing stays, its file's read moves → `-o remount,strictatime`: three `cat`s of a read file all move (a strictatime open drops the kernel's cached pages: every open-read cycle reaches the daemon) → `-o remount,noatime`: a new file's read moves nothing, a write still moves mtime/ctime → `-o remount,ro,strictatime`: nothing → `rw,relatime` again: the written file's read moves → umount, remount: every stamp as shown (durable at the cadence and the dismount) → SQUEEZEFS_ATIME=noatime over the kernel's relatime: a read moves nothing; =strictatime: two reads move, the mount's nodiratime stands → fsck --offline --scrub 0 findings, the must-stay-0 set clean" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    try rig.spawnMount(&.{});
    var mark = try rig.awaitReady(0);
    const Phase = struct {
        fn run(r: *Rig, script: []const u8, expect_tail: []const u8) !void {
            const argv = [_][]const u8{ "sh", "-e", "-c", script, "atime", r.mp, r.work };
            const out = try r.onMountArgv(script, &argv);
            defer r.gpa.free(out);
            if (!std.mem.endsWith(u8, out, expect_tail)) {
                std.debug.print("\n--- atime phase output ---\n{s}\n", .{out});
                return error.AtimePhaseFailed;
            }
        }
    };
    try Phase.run(rig, atime_sh_relatime, "relatime ok rw,relatime\n");
    // The kernel's flag remount reaches the daemon through the mount table
    // (its watcher's line names the new law) — before the phase judges it.
    try Phase.run(rig, atime_sh_nodiratime, "nodiratime ok rw,nodiratime,relatime\n");
    mark = try rig.awaitLog("atime: relatime,nodiratime (the kernel mount's flags)", mark, 5 * std.time.ns_per_s);
    try Phase.run(rig, atime_sh_strict_noatime_ro, "strict/noatime/ro ok\n");
    mark = try rig.awaitLog("atime: strictatime (the kernel mount's flags)", mark, 5 * std.time.ns_per_s);
    mark = try rig.awaitLog("atime: noatime (the kernel mount's flags)", mark, 5 * std.time.ns_per_s);
    mark = try rig.awaitLog("atime: strictatime,ro (the kernel mount's flags)", mark, 5 * std.time.ns_per_s);
    mark = try rig.awaitLog("atime: relatime (the kernel mount's flags)", mark, 5 * std.time.ns_per_s);
    {
        const ta = try rig.stats();
        defer gpa.free(ta);
        // Every Y above is one touch: 1 + 1 (dir) + 1 (link) + 1 (file2) + 3 (strict) + 1 (after the write) = 8.
        try testing.expectEqual(@as(?u64, 8), numberAfter(ta, "\"fuse_atime_touches\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"fuse_atime_touches_dropped\":"));
        try expectMustStayZero(ta);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    // The remount: every stamp as it was shown (the drain and the dismount
    // journaled the parked stamps).
    mark = try rig.logLen();
    try rig.spawnMount(&.{});
    mark = try rig.awaitReady(mark);
    try Phase.run(rig, atime_sh_remounted, "remount ok\n");
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    // The knob over the kernel's relatime (its line precedes ready).
    try rig.env.put("SQUEEZEFS_ATIME", "noatime");
    mark = try rig.logLen();
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(mark);
    _ = try rig.awaitLog("atime: noatime (SQUEEZEFS_ATIME over the kernel mount's flags)", mark, 5 * std.time.ns_per_s);
    try Phase.run(rig, atime_sh_knob_noatime, "knob noatime ok\n");
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    try rig.env.put("SQUEEZEFS_ATIME", "strictatime");
    mark = try rig.logLen();
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(mark);
    try Phase.run(rig, atime_sh_knob_strict, "knob strictatime ok\n");
    _ = try rig.awaitLog("atime: strictatime,nodiratime (SQUEEZEFS_ATIME over the kernel mount's flags)", mark, 5 * std.time.ns_per_s);
    _ = rig.env.swapRemove("SQUEEZEFS_ATIME");
    {
        const ta = try rig.stats();
        defer gpa.free(ta);
        try testing.expectEqual(@as(?u64, 2), numberAfter(ta, "\"fuse_atime_touches\":"));
        try expectMustStayZero(ta);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    _ = try fsckClean(rig, "the atime row");
    std.debug.print("\nsmoke: atime — relatime/nodiratime/strictatime/noatime/ro as the kernel mount's flags through four flag remounts, the stamps durable across a remount, the knob over the mount", .{});
}

test "smoke: THE `-o ro` READER OF A LIVE SET — C mounts `-o ro` beside A (the manager) and B (joined): no flock, no claim, no region; a member-reader + token client (TTLs 0, reader_staleness_bound_ms 0) reading B's 2,000 files and A's tree under tokens (0 local reads) → B writes ⇒ C's next read is fresh → A and B leave ⇒ C becomes the QUIESCENT reader of their last checkpoint → A mounts again ⇒ C fail-stops ESTALE at its next op (`.stats` still readable) → remount C ⇒ a token reader again — B's membership leave is LOST (`SQUEEZEFS_TEST_MEMBERSHIP_LEAVE_LOST`): its row outlives it, and A's successor must not expect a member whose pid is proven dead (decision 0003 §AG.5), or its grace refuses C's remount" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.env.put("SQUEEZEFS_MW_BIND", "127.0.0.1:0");
    var t_owner_text: [8]u8 = undefined;
    try rig.env.put("SQUEEZEFS_TEST_MEMBERSHIP_T_OWNER_MS", try std.fmt.bufPrint(&t_owner_text, "{d}", .{smoke_t_owner_ms}));
    try rig.formatSet(true);
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    var env_b = try envWith(gpa, &rig.env, &.{.{ "SQUEEZEFS_TEST_MEMBERSHIP_LEAVE_LOST", "1" }});
    defer env_b.deinit();
    const b = try Peer.init(rig, "b");
    defer b.deinit();
    b.env = &env_b;
    try b.spawn(&.{});
    _ = try b.awaitReady();
    {
        const script = try matrixCreateScript(gpa);
        defer gpa.free(script);
        const out = try b.onMount(script);
        defer gpa.free(out);
        try testing.expectEqualStrings("500\n", out);
        const mk = try rig.onMount("mkdir a-tree && for i in 0 1 2 3; do printf 'a%s\\n' $i > a-tree/f$i; done; echo ok");
        gpa.free(mk);
    }
    // C: `-o ro` of the LIVE set — a reader, never a claim.
    const c = try Peer.init(rig, "c");
    defer c.deinit();
    try c.spawn(&.{ "-o", "ro" });
    _ = try c.awaitReady();
    {
        const text = try c.readLog();
        defer gpa.free(text);
        try testing.expect(std.mem.indexOf(u8, text, "mounted as a READER") != null);
        try testing.expect(std.mem.indexOf(u8, text, "`-o ro` of a LIVE set — a member-reader of the home shard") != null);
        try testing.expect(std.mem.indexOf(u8, text, "TTLs attr 0 ms entry 0 ms dir_entry 0 ms negative 0 ms") != null);
        try testing.expect(std.mem.indexOf(u8, text, "writer claim committed") == null);
    }
    {
        const r = try rig.squeezefs(&.{ "appenders", rig.meta_uri });
        defer rig.freeRun(r);
        try testing.expect(r.term.success());
        // A reader holds no region: the directory still lists A and B alone.
        try testing.expect(std.mem.indexOf(u8, r.stdout, "2 appender page(s)") != null);
    }
    // C reads B's 2,000 files and A's tree under tokens.
    {
        const out = try c.onMount("ls b0 b1 b2 b3 | grep -c '^f'; cat b1/f7; cat a-tree/f2; ls a-tree | wc -l; echo x > b0/new 2>&1 || echo refused");
        defer gpa.free(out);
        try testing.expectEqualStrings("2000\nb1-f7\na2\n4\nrefused\n", out);
        const tc = try c.stats();
        defer gpa.free(tc);
        try testing.expect(std.mem.indexOf(u8, tc, "\"mount_posture\":\"reader\"") != null);
        try testing.expect(std.mem.indexOf(u8, tc, "\"reader_arm\":\"tokens\"") != null);
        try testing.expectEqual(@as(?u64, 0), numberAfter(tc, "\"reader_staleness_bound_ms\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(tc, "\"dlm_token_local_reads\":"));
        try testing.expect((numberAfter(tc, "\"dlm_token_grants\":") orelse 0) >= 2000);
        try testing.expectEqual(@as(?u64, 2), numberAfter(tc, "\"dlm_token_reader_holder_planes\":"));
        std.debug.print("\nsmoke: -o ro: C read B's 2,000 files and A's tree under tokens — grants {d}, hits {d}, local reads 0, holder planes 2, staleness bound 0 ms\n", .{ numberAfter(tc, "\"dlm_token_grants\":") orelse 0, numberAfter(tc, "\"dlm_token_hits\":") orelse 0 });
    }
    // B writes: the holder's recall reaches C's listener; C's next read
    // is the fresh content (no TTL, no poll — the recall is the proof).
    {
        const w = try b.onMount("printf 'fresh\\n' > b1/f7");
        gpa.free(w);
        const out = try c.onMount("cat b1/f7");
        defer gpa.free(out);
        try testing.expectEqualStrings("fresh\n", out);
        const tc = try c.stats();
        defer gpa.free(tc);
        try testing.expect((numberAfter(tc, "\"dlm_token_recalls_received\":") orelse 0) >= 1);
        try testing.expectEqual(@as(?u64, 0), numberAfter(tc, "\"dlm_token_recall_timeouts_live\":"));
    }
    // The writers leave cleanly: C's lease lapses, no writer face stands,
    // C becomes the quiescent reader of their last checkpoint. B's lost
    // leave keeps its row at A — until B's T_owner deadline, where a LIVE
    // A evicts it and deletes the row; whether A's own stop came first is
    // real time (B's teardown, two `umount` censuses, A's teardown — under
    // a gate's load they exceeded the row's 3 s T_owner), so the outcome
    // is read from A's log, never assumed.
    const leave_mark = try rig.logLen();
    const leave_t0 = clock.monotonicNs();
    try b.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try b.waitExit());
    const b_gone_ms = (clock.monotonicNs() - leave_t0) / std.time.ns_per_ms;
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    const a_gone_ms = (clock.monotonicNs() - leave_t0) / std.time.ns_per_ms;
    const b_evicted = blk: {
        const text = try rig.readLog();
        defer gpa.free(text);
        break :blk evictedAtTOwner(text[@min(leave_mark, text.len)..]) != 0;
    };
    std.debug.print("smoke: -o ro: B left at {d} ms, A at {d} ms (T_owner {d} ms); A {s} B's row before leaving\n", .{ b_gone_ms, a_gone_ms, smoke_t_owner_ms, if (b_evicted) "EVICTED" else "kept" });
    {
        // The reader's root is its holder's until the lease lapses: the
        // walk to `.stats` may answer EAGAIN in between (the tolerant read).
        const deadline = clock.monotonicNs() + kill_row_wait_ns;
        while (true) {
            if (try c.statsTry()) |tc| {
                defer gpa.free(tc);
                if (std.mem.indexOf(u8, tc, "\"reader_arm\":\"quiescent\"") != null) break;
            }
            if (clock.monotonicNs() >= deadline) return error.ReaderNeverQuiescent;
            sleepMs(200);
        }
        const out = try c.onMount("cat b1/f7; ls b3 | wc -l; cat a-tree/f2");
        defer gpa.free(out);
        try testing.expectEqualStrings("fresh\n500\na2\n", out);
        const tc = try c.stats();
        defer gpa.free(tc);
        try testing.expectEqual(@as(?u64, 1), numberAfter(tc, "\"reader_quiescent_transitions\":"));
        try testing.expect((numberAfter(tc, "\"dlm_token_local_reads\":") orelse 0) >= 1);
        std.debug.print("smoke: -o ro: A and B left — C became the quiescent reader of their last checkpoint; every read local and fresh\n", .{});
    }
    // A mounts again: the quiescent reader's poll sees the writer and
    // fail-stops — every op ESTALE, `.stats` still readable.
    const mark = try rig.logLen();
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(mark);
    {
        const deadline = clock.monotonicNs() + kill_row_wait_ns;
        while (true) {
            const tc = try c.stats();
            defer gpa.free(tc);
            if (std.mem.indexOf(u8, tc, "\"reader_fail_stopped\":true") != null) break;
            if (clock.monotonicNs() >= deadline) return error.ReaderNeverFailStopped;
            sleepMs(100);
        }
        const r = try std.process.run(gpa, io, .{ .argv = &.{ "sh", "-c", "ls b3 2>&1; cat a-tree/f2 2>&1" }, .cwd = .{ .path = c.mp }, .environ_map = &rig.env });
        defer gpa.free(r.stdout);
        defer gpa.free(r.stderr);
        if (std.mem.count(u8, r.stdout, "Stale file handle") != 2) std.debug.print("\nsmoke: -o ro: C after the fail-stop answered:\n{s}\n", .{r.stdout});
        try testing.expectEqual(@as(usize, 2), std.mem.count(u8, r.stdout, "Stale file handle"));
        const text = try c.readLog();
        defer gpa.free(text);
        try testing.expect(std.mem.indexOf(u8, text, "a writer appeared (ledger_advance) under the quiescent reader — every metadata op now answers ESTALE") != null);
        std.debug.print("smoke: -o ro: A mounted again — C fail-stopped (ESTALE on ls and cat; .stats readable)\n", .{});
    }
    // B's row outlived its lost leave: A's successor proved its pid dead
    // and opened no grace for it (the remount below is a fresh join). When
    // the first A evicted B at T_owner instead, its delete left the
    // successor no row to exclude — a dead row counted then would be a
    // row that survived its eviction.
    {
        const ta = try rig.onMount("cat .stats");
        defer gpa.free(ta);
        const dead_rows = numberAfter(ta, "\"membership_grace_dead_rows\":") orelse 0;
        if (b_evicted) try testing.expectEqual(@as(u64, 0), dead_rows) else try testing.expect(dead_rows >= 1);
    }
    // Remount C: a token reader of the live set again.
    try c.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try c.waitExit());
    const mark_c = try c.logLen();
    try c.spawn(&.{ "-o", "ro" });
    _ = try c.awaitLog("ready: ", mark_c, ready_wait_ns);
    {
        const out = try c.onMount("cat b1/f7; cat a-tree/f2");
        defer gpa.free(out);
        try testing.expectEqualStrings("fresh\na2\n", out);
        const tc = try c.stats();
        defer gpa.free(tc);
        try testing.expect(std.mem.indexOf(u8, tc, "\"reader_arm\":\"tokens\"") != null);
        try expectMustStayZero(tc);
        const ta = try rig.onMount("cat .stats");
        defer gpa.free(ta);
        try expectMustStayZero(ta);
        try testing.expectEqual(@as(?u64, 1), numberAfter(ta, "\"membership_members\":"));
    }
    try c.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try c.waitExit());
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// GNU tar's write(2) grain on extraction. `extract_file` issues one
/// `write(2)` per record-contiguous span of an entry's data (the record is
/// `-b N` blocks of `tar_block`; `tar --show-defaults` names N, GNU tar's
/// default 20 = 10,240 B), so an entry whose data straddles a record
/// boundary lands as TWO writes — the first exactly the bytes to the
/// record's end. For this tree (a 512 B header + 1,000 B of data padded to
/// 1,024 B per entry, the `./` directory header first) the data of every
/// 20th file — f19, f39, …, f199, … — starts at a record's last block:
/// 512 + 488, 75 of the 1,500 (strace-proven; `docs/evidence/rung-09-
/// gates.md` §7). A crash between the two leaves a legitimate POSIX state
/// — the first write landed, the second never issued or never acked — so
/// the oracle accepts a file cut THERE and nowhere else. The table is
/// derived from the ARCHIVE (`tar -R -tf`: each entry's header block),
/// never assumed from the name.
const TarWriteGrain = struct {
    record_blocks: u64,
    /// The length of tar's first `write(2)` for `f<idx>`: the entry's size
    /// when its data lies inside one record.
    first_write: [kill_tree_files]u16,

    /// `-bN` from `tar --show-defaults`.
    fn recordBlocks(defaults: []const u8) !u64 {
        var it = std.mem.tokenizeAny(u8, defaults, " \n");
        while (it.next()) |word| {
            if (std.mem.startsWith(u8, word, "-b")) return std.fmt.parseInt(u64, word["-b".len..], 10);
        }
        return error.TarDefaultsUnparsed;
    }

    /// The first write of an entry of `size` whose header sits at
    /// `header_block`: its data starts at the next block and the write
    /// spans to the record's end.
    fn firstWrite(header_block: u64, size: u64, record_blocks: u64) u64 {
        const data_block = header_block + 1;
        return @min(size, (record_blocks - data_block % record_blocks) * tar_block);
    }

    /// From `tar -R -tf` (`block N: ./fIDX` per member); every file of the
    /// tree named exactly once.
    fn parse(listing: []const u8, record_blocks: u64) !TarWriteGrain {
        var g: TarWriteGrain = .{ .record_blocks = record_blocks, .first_write = @splat(0) };
        var named: usize = 0;
        var lines = std.mem.splitScalar(u8, listing, '\n');
        while (lines.next()) |line| {
            const head = "block ";
            if (!std.mem.startsWith(u8, line, head)) continue;
            const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.TarListingUnparsed;
            const block = try std.fmt.parseInt(u64, line[head.len..colon], 10);
            const member = "./f";
            if (line.len < colon + ": ".len) return error.TarListingUnparsed;
            const name = line[colon + ": ".len ..];
            if (!std.mem.startsWith(u8, name, member)) continue;
            const idx = try std.fmt.parseInt(usize, name[member.len..], 10);
            if (idx >= kill_tree_files or g.first_write[idx] != 0) return error.TarListingUnparsed;
            g.first_write[idx] = @intCast(firstWrite(block, kill_tree_file_len, record_blocks));
            named += 1;
        }
        if (named != kill_tree_files) return error.TarListingUnparsed;
        return g;
    }

    /// How many entries tar extracts in two writes.
    fn twoWriteEntries(self: *const TarWriteGrain) usize {
        var n: usize = 0;
        for (self.first_write) |w| n += @intFromBool(w < kill_tree_file_len);
        return n;
    }
};

test "smoke: tar's write(2) grain — the record blocks from --show-defaults, the first write from the header block (data at a record's last block = one block, else the size), the -R listing parsed once per member" {
    try testing.expectEqual(@as(u64, 20), try TarWriteGrain.recordBlocks("--format=gnu -f- -b20 --quoting-style=escape\n"));
    try testing.expectError(error.TarDefaultsUnparsed, TarWriteGrain.recordBlocks("--format=gnu -f-\n"));
    // ./ at block 0, f0's header at 1 (data 2–3), f1 at 4, … f19 at 58:
    // data at 59 = the record's last block → 512; f20 at 61 → whole.
    try testing.expectEqual(@as(u64, 1000), TarWriteGrain.firstWrite(1, 1000, 20));
    try testing.expectEqual(@as(u64, 512), TarWriteGrain.firstWrite(58, 1000, 20));
    try testing.expectEqual(@as(u64, 1000), TarWriteGrain.firstWrite(61, 1000, 20));
    // A 1,024 B entry at the record's last block is 512 + 512; a 300 B one
    // there fits its first write.
    try testing.expectEqual(@as(u64, 512), TarWriteGrain.firstWrite(58, 1024, 20));
    try testing.expectEqual(@as(u64, 300), TarWriteGrain.firstWrite(58, 300, 20));
    // The full tree in archive order: 75 two-write entries, all ≡ 19 (mod 20).
    var listing: std.Io.Writer.Allocating = .init(testing.allocator);
    defer listing.deinit();
    try listing.writer.writeAll("block 0: ./\n");
    for (0..kill_tree_files) |i| try listing.writer.print("block {d}: ./f{d}\n", .{ 1 + 3 * i, i });
    const g = try TarWriteGrain.parse(listing.written(), 20);
    try testing.expectEqual(@as(usize, 75), g.twoWriteEntries());
    for (g.first_write, 0..) |w, i| try testing.expectEqual(@as(u16, if (i % 20 == 19) 512 else 1000), w);
    // A listing that names a member twice or misses one is refused.
    try testing.expectError(error.TarListingUnparsed, TarWriteGrain.parse("block 0: ./\nblock 1: ./f0\nblock 4: ./f0\n", 20));
    try testing.expectError(error.TarListingUnparsed, TarWriteGrain.parse("block 0: ./\nblock 1: ./f0\n", 20));
}

/// One extracted entry's state after the crash, at tar's write(2) grain.
const EntryState = enum { whole, empty, first_write_only };

/// THE write(2)-grain oracle for one entry (charter §1.10 "zero acked
/// loss"): `got` against the body the name promises; `acked` = tar's
/// write(s) returned before the kill (its stderr names the unacked set);
/// `first_write` = tar's first `write(2)` length for the entry
/// (`TarWriteGrain`). An acked entry is whole or LOST; an unacked one is
/// whole (landed, the reply lost), empty (its create landed, no write did)
/// or cut exactly at its first write (the second never landed) — any other
/// content is TORN: a prefix inside a single write, or bytes that are not
/// the body's.
fn judgeAtWriteGrain(got: []const u8, want: []const u8, acked: bool, first_write: u64) error{ AckedWriteLost, TornFile }!EntryState {
    const prefix_ok = got.len <= want.len and std.mem.eql(u8, got, want[0..got.len]);
    if (prefix_ok and got.len == want.len) return .whole;
    if (acked) return error.AckedWriteLost;
    if (got.len == 0) return .empty;
    if (prefix_ok and got.len == first_write) return .first_write_only;
    return error.TornFile;
}

/// The body the kill tree's `f<idx>` promises: `file-NNNNN:` + the letter.
fn killTreeBody(idx: usize, want: *[kill_tree_file_len]u8) !void {
    const head = try std.fmt.bufPrint(want, "file-{d:0>5}:", .{idx});
    @memset(want[head.len..], 'a' + @as(u8, @intCast(idx % 26)));
}

test "smoke: the write(2)-grain oracle — acked ⇒ whole or lost; unacked ⇒ whole, empty or exactly tar's first write; a prefix inside a write, or at a boundary the entry does not have, is torn" {
    var want: [kill_tree_file_len]u8 = undefined;
    try killTreeBody(199, &want);
    try testing.expectEqualStrings("file-00199:rrr", want[0..14]);
    // Whole is whole either way.
    try testing.expectEqual(EntryState.whole, try judgeAtWriteGrain(&want, &want, true, 512));
    try testing.expectEqual(EntryState.whole, try judgeAtWriteGrain(&want, &want, false, 1000));
    // The gate's finding: 512 B of a two-write entry tar was NOT acked on.
    try testing.expectEqual(EntryState.first_write_only, try judgeAtWriteGrain(want[0..512], &want, false, 512));
    // The same 512 B of an entry tar WAS acked on: an acked write lost.
    try testing.expectError(error.AckedWriteLost, judgeAtWriteGrain(want[0..512], &want, true, 512));
    // 512 B of a ONE-write entry (first write = the size): torn inside a write.
    try testing.expectError(error.TornFile, judgeAtWriteGrain(want[0..512], &want, false, 1000));
    // A prefix that is not the first write's length is torn even on a two-write entry.
    try testing.expectError(error.TornFile, judgeAtWriteGrain(want[0..700], &want, false, 512));
    try testing.expectError(error.TornFile, judgeAtWriteGrain(want[0..488], &want, false, 512));
    // Empty: the create landed, no write did — unacked only.
    try testing.expectEqual(EntryState.empty, try judgeAtWriteGrain("", &want, false, 512));
    try testing.expectError(error.AckedWriteLost, judgeAtWriteGrain("", &want, true, 1000));
    // Bytes that are not the body's (a swapped neighbour): torn at any
    // length, lost when acked.
    var swapped: [kill_tree_file_len]u8 = undefined;
    try killTreeBody(198, &swapped);
    try testing.expectError(error.TornFile, judgeAtWriteGrain(&swapped, &want, false, 512));
    try testing.expectError(error.AckedWriteLost, judgeAtWriteGrain(&swapped, &want, true, 512));
    try testing.expectError(error.TornFile, judgeAtWriteGrain(swapped[0..512], &want, false, 512));
    // Longer than the body: torn.
    const longer: [kill_tree_file_len + 1]u8 = @splat('r');
    try testing.expectError(error.TornFile, judgeAtWriteGrain(&longer, &want, false, 512));
}

/// The kill row's body (the coalesced and the strict cadence rows):
/// format → mount → `tar -xf` of the 1,500-file tree in a child → `kill
/// -9` once `kill_after_files` are visible → the dead connection unmounted
/// → remount (the window replays) → the tree judged at tar's write(2)
/// grain against tar's own ack ledger (its stderr) and the archive's write
/// boundaries (`TarWriteGrain`) → the gauges → a clean cycle.
fn killRowTarX(strict: bool) !void {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    // The strict cadence: ONE barrier per group before any ack (the knob's
    // A/B control arm), named by the mount line.
    if (strict) try rig.env.put("SQUEEZEFS_META_FLUSH_INTERVAL_MS", "0");
    const cadence_word: []const u8 = if (strict) "strict cadence" else "coalesced cadence";
    {
        const f = try Io.Dir.cwd().createFile(io, rig.img, .{ .truncate = true });
        defer f.close(io);
        try f.setLength(io, volume_len);
    }
    {
        const r = try rig.squeezefs(&.{ "format", rig.meta_uri });
        defer rig.freeRun(r);
        try testing.expect(r.term.success());
    }
    // The kill tree on ext4: `kill_tree_files` files of `kill_tree_file_len`
    // distinct bytes each (the content names the file, so a swapped body
    // would be caught).
    {
        var script: std.Io.Writer.Allocating = .init(gpa);
        defer script.deinit();
        try script.writer.print(
            \\mkdir -p ktree
            \\i=0
            \\while [ $i -lt {d} ]; do
            \\  printf 'file-%05d:' $i > ktree/f$i
            \\  head -c {d} /dev/zero | tr '\0' "$(printf '\\%03o' $((97 + i % 26)))" >> ktree/f$i
            \\  i=$((i + 1))
            \\done
            \\tar -cf ktree.tar -C ktree .
        , .{ kill_tree_files, kill_tree_file_len - 11 });
        const out = try rig.shOk(rig.work, script.written());
        defer gpa.free(out);
    }
    // tar's write(2) boundaries, from the archive it will extract.
    const grain = blk: {
        const defaults = try rig.shOk(rig.work, "tar --show-defaults");
        defer gpa.free(defaults);
        const listing = try rig.shOk(rig.work, "tar -R -tf ktree.tar");
        defer gpa.free(listing);
        break :blk try TarWriteGrain.parse(listing, try TarWriteGrain.recordBlocks(defaults));
    };
    // The coalesced arm runs SUPERVISED (charter §5.2 "The ack point",
    // decision 0003 §BB.7): its acks precede the landing, and the kill -9
    // is the replay's proof — the supervisor writes the journal tail to the
    // device before the writer guard is released, so every acked create is
    // present on the remount. The strict arm is durable at the ack and runs
    // in the foreground (no replay to prove).
    const supervised = !strict;
    var daemon_pid: linux.pid_t = 0;
    if (supervised) {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\ndaemon mount: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    } else try rig.spawnMount(&.{});
    const ready1 = try rig.awaitReady(0);
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expect(std.mem.indexOf(u8, text[0..ready1], cadence_word) != null);
        if (supervised) {
            const ready_i = std.mem.lastIndexOf(u8, text[0..ready1], "ready: ") orelse return error.NoReadyLine;
            daemon_pid = @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid);
            try testing.expect(std.mem.indexOf(u8, text, "journal tails: 1 volume(s) handed to the supervisor") != null);
        }
    }
    // tar -x in a child; kill the daemon once enough files exist. tar's
    // stderr IS its ack ledger: the entries it could not open or write
    // when the daemon died are the unacked ones (read after the wait).
    var tar_argv_buf: [64]u8 = undefined;
    const tar_path = try std.fmt.bufPrint(&tar_argv_buf, "{s}/ktree.tar", .{rig.work});
    var tar_err_buf: [192]u8 = undefined;
    const tar_err_path = try std.fmt.bufPrint(&tar_err_buf, "{s}/tar.err", .{rig.work});
    const tar_err_file = try Io.Dir.cwd().createFile(io, tar_err_path, .{ .truncate = true });
    defer tar_err_file.close(io);
    var tar = try std.process.spawn(io, .{ .argv = &.{ "tar", "-xf", tar_path, "-C", rig.mp }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .ignore, .stderr = .{ .file = tar_err_file } });
    var seen: usize = 0;
    {
        // A TIGHT poll (readdir back to back, no sleep): the kill should
        // land as soon as the `kill_after_files`-th entry is visible — while
        // its two writes are still in flight — so the record-boundary state
        // is exercised, not merely tolerated (met 3 times in 60 rows, all
        // under the strict cadence whose barrier widens the gap; the 5 ms
        // cadence before met it once in weeks of gates).
        const deadline = clock.monotonicNs() + 60 * std.time.ns_per_s;
        while (clock.monotonicNs() < deadline) {
            var dir = try Io.Dir.cwd().openDir(io, rig.mp, .{ .iterate = true });
            defer dir.close(io);
            seen = try countFiles(gpa, io, dir);
            if (seen >= kill_after_files) break;
        }
    }
    try testing.expect(seen >= kill_after_files);
    if (supervised) {
        _ = linux.kill(daemon_pid, .KILL);
        // The supervisor's replay, then the guard's release, then its exit.
        const replay_i = try rig.awaitLog("supervisor: journal tail of volume 0 (", ready1, 30 * std.time.ns_per_s);
        const released_i = try rig.awaitLog("supervisor: writer guard released on 1 volume(s) after the replay", ready1, 30 * std.time.ns_per_s);
        try testing.expect(released_i > replay_i);
        _ = try rig.awaitLog("exited (wait status 0x9); done", released_i, 30 * std.time.ns_per_s);
        const after = try rig.readLog();
        defer gpa.free(after);
        const line = after[replay_i - 1 ..];
        std.debug.print("\nsmoke[replay]: {s}\n", .{line[0 .. std.mem.indexOfScalar(u8, line, '\n') orelse line.len]});
        try testing.expect(std.mem.indexOf(u8, after, "replay FAILED") == null);
    } else {
        _ = linux.kill(rig.child_pid, .KILL);
        const killed = try rig.waitChild();
        try testing.expectEqual(std.process.Child.Term{ .signal = .KILL }, killed);
    }
    // tar fails (ENOTCONN) and exits; the dead connection unmounts.
    const tar_term = try tar.wait(io);
    try testing.expect(!tar_term.success());
    try rig.umountAfterKill();
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    const tar_err = try Io.Dir.cwd().readFileAlloc(io, tar_err_path, gpa, .limited(1 << 20));
    defer gpa.free(tar_err);
    var unacked = try tarUnackedNames(gpa, tar_err, "tar: ./");
    defer freeNames(gpa, &unacked);
    // A tar that finished clean never met the kill.
    try testing.expect(unacked.items.len > 0);
    std.debug.print("\nsmoke: kill -9 sent with {d} of {d} files visible ({s}); tar {f}, {d} entries unacked\n", .{ seen, kill_tree_files, cadence_word, tar_term, unacked.items.len });

    // Remount: the window replays (NOT a clean unmount), nothing torn is a
    // corruption alert only after a clean one — here it is counted.
    const mark = try rig.logLen();
    try rig.spawnMount(&.{});
    const ready2 = try rig.awaitReady(mark);
    var replayed: u64 = 0;
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        const seg = text[mark..ready2];
        try testing.expect(std.mem.indexOf(u8, seg, "mounted — ledger seq") != null);
        try testing.expect(std.mem.indexOf(u8, seg, ", clean unmount") == null);
        try testing.expect(std.mem.indexOf(u8, seg, cadence_word) != null);
        replayed = numberAfter(seg, "replayed ") orelse 0;
    }
    // The tree at tar's write(2) grain: an entry tar was ACKED on is
    // present and whole; an unacked one is whole (landed, the reply lost),
    // empty (its create landed, no write did) or exactly tar's FIRST write
    // (a record-boundary entry whose second write never landed); anything
    // else is torn.
    var whole: usize = 0;
    var empty: usize = 0;
    var first_only: usize = 0;
    var present: usize = 0;
    var present_set: [kill_tree_files]bool = @splat(false);
    {
        var dir = try Io.Dir.cwd().openDir(io, rig.mp, .{ .iterate = true });
        defer dir.close(io);
        var it = dir.iterate();
        while (try it.next(io)) |ent| {
            if (ent.kind != .file) continue;
            present += 1;
            const got = try dir.readFileAlloc(io, ent.name, gpa, .limited(1 << 20));
            defer gpa.free(got);
            // The expected body from the name: `file-NNNNN:` + the letter.
            const idx = try std.fmt.parseInt(usize, ent.name[1..], 10);
            if (idx >= kill_tree_files) return error.UnexpectedName;
            present_set[idx] = true;
            const acked = !namesContain(unacked.items, ent.name);
            var want: [kill_tree_file_len]u8 = undefined;
            try killTreeBody(idx, &want);
            const state = judgeAtWriteGrain(got, &want, acked, grain.first_write[idx]) catch |e| {
                std.debug.print("\n--- {s}: {d} bytes, {s} by tar, its first write(2) {d} B — {t} ---\n", .{ ent.name, got.len, if (acked) "ACKED" else "unacked", grain.first_write[idx], e });
                return e;
            };
            switch (state) {
                .whole => whole += 1,
                .empty => empty += 1,
                .first_write_only => {
                    std.debug.print("smoke: {s}: {d} bytes = tar's first write(2) of the entry, its second ({d} B) never acked — the write(2)-grain state the oracle accepts\n", .{ ent.name, got.len, kill_tree_file_len - got.len });
                    first_only += 1;
                },
            }
        }
    }
    // Every entry tar was acked on (not in its unacked set) is present.
    for (present_set, 0..) |is_present, idx| {
        if (is_present) continue;
        var name_buf: [16]u8 = undefined;
        const name = try std.fmt.bufPrint(&name_buf, "f{d}", .{idx});
        if (namesContain(unacked.items, name)) continue;
        std.debug.print("\n--- {s}: ACKED by tar (its open returned), absent on the remount — an acked create lost ---\n", .{name});
        return error.AckedCreateLost;
    }
    try testing.expect(present >= kill_after_files);
    try testing.expect(whole > 0);
    std.debug.print("smoke: after kill -9 ({s}): replayed {d} journal entries; {d} files present ({d} whole, {d} empty — created, write not yet issued, {d} at tar's first write(2) boundary), {d} never created; every entry tar was acked on is whole; {d} of {d} entries are two-write entries under tar's {d}-block record\n", .{ cadence_word, replayed, present, whole, empty, first_only, kill_tree_files - present, grain.twoWriteEntries(), kill_tree_files, grain.record_blocks });
    // The gauges on the recovered mount, then a clean cycle: the next
    // remount's window is empty and nothing torn.
    {
        const m = try rig.logLen();
        _ = linux.kill(rig.child_pid, .USR1);
        _ = try rig.awaitLog("stats daemon: ", m, 10 * std.time.ns_per_s);
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expect(std.mem.indexOf(u8, text[m..], "\"open_count_stranded\":0,") != null);
        try testing.expect(std.mem.indexOf(u8, text[m..], "\"transport_requests_abandoned\":0,") != null);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    const mark3 = try rig.logLen();
    try rig.spawnMount(&.{});
    const ready3 = try rig.awaitReady(mark3);
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expect(std.mem.indexOf(u8, text[mark3..ready3], ", clean unmount") != null);
        try testing.expect(std.mem.indexOf(u8, text[mark3..ready3], "0 torn dropped") != null);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
}

test "smoke: kill -9 mid-tar -x (a `--daemon --supervise` mount: the replay's proof — the supervisor writes the journal tail to the device before the writer guard is released) → remount replays the window → judged at tar's write(2) grain: every write tar was acked on is present whole, an unacked file is whole, empty or cut exactly at tar's first write of a record-boundary entry, nothing else; a clean cycle after it" {
    try killRowTarX(false);
