test "smoke: --daemon --supervise --log-file: the invoking process returns 0 only after ready, the log file is 0600 and carries the ready line, umount ends the daemon and the supervisor; a refused daemon mount reports its reason to the invoker" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    {
        const f = try Io.Dir.cwd().createFile(io, rig.img, .{ .truncate = true });
        defer f.close(io);
        try f.setLength(io, volume_len);
    }
    // A daemon mount of an unformatted volume: the invoker gets the reason.
    {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--log-file", rig.log_path, rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "not formatted") != null);
        try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    }
    {
        const r = try rig.squeezefs(&.{ "format", rig.meta_uri });
        defer rig.freeRun(r);
        try testing.expect(r.term.success());
    }
    const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, rig.meta_uri, rig.mp });
    defer rig.freeRun(r);
    if (!r.term.success()) std.debug.print("\ndaemon mount: {s}\n", .{r.stderr});
    try testing.expect(r.term.success());
    try testing.expectEqual(@as(usize, 1), try fuseMountsOf(gpa, io, rig.mp));
    // The log file: 0600, the ready line with the daemon's pid.
    var st: linux.Statx = undefined;
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.statx(linux.AT.FDCWD, rig.log_path.ptr, 0, linux.STATX.BASIC_STATS, &st)));
    try testing.expectEqual(@as(u16, 0o600), st.mode & 0o777);
    const text = try rig.readLog();
    defer gpa.free(text);
    const ready_i = std.mem.indexOf(u8, text, "ready: ") orelse return error.NoReadyLine;
    const pid = numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid;
    // The supervisor's own first line lands AFTER the ready handoff that
    // returned the invoker (a separate process, scheduled in its own time:
    // under a loaded venue it trails the invoker's exit by seconds), so its
    // appearance is awaited, never asserted on the snapshot above.
    _ = try rig.awaitLog("supervisor: watching daemon ", ready_i, ready_wait_ns);
    // The mount works through the shell.
    {
        const out = try rig.shOk(rig.mp, "echo daemonized > f && test \"$(cat f)\" = daemonized && echo ok");
        defer gpa.free(out);
    }
    // umount: the daemon exits, the supervisor notices and exits too.
    try rig.umount();
    {
        const deadline = clock.monotonicNs() + exit_wait_ns;
        while (alive(@intCast(pid)) and clock.monotonicNs() < deadline) sleepMs(20);
        try testing.expect(!alive(@intCast(pid)));
    }
    _ = try rig.awaitLog("supervisor: daemon ", ready_i, 20 * std.time.ns_per_s);
    const after = try rig.readLog();
    defer gpa.free(after);
    try testing.expect(std.mem.indexOf(u8, after, "exited (wait status 0x0); done") != null);
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    // Nothing of ours survives: no squeezefs process holds the volume.
    try testing.expect(!@import("status.zig").writerGuardHeld(testing.io, rig.img));
}

/// generic/604's file count, each file 8 KiB: past `inline_max`, so every
/// one is STAGED (never fsync'd) and the dismount pass is a real promotion
/// pass — the one the hold parks.
const raced_umount_files: usize = 501;
const raced_umount_file_bytes: usize = 8192;

/// One raced cycle of the row below over the rig's current `--daemon
/// --supervise` mount (`pid_a`): the files, the unmount in the background
/// with a second mount at once, the second mount's wait judged, the
/// release, the verdicts; the second daemon's pid. `log_file` is the
/// rig's append sink for both verbs.
fn racedUnmountCycle(rig: *Rig, fifo: [:0]const u8, log_file: Io.File, pid_a: linux.pid_t, label: []const u8) !linux.pid_t {
    const io = rig.io;
    const gpa = rig.gpa;
    {
        var script: [192]u8 = undefined;
        gpa.free(try rig.shOk(rig.mp, try std.fmt.bufPrint(&script, "for i in $(seq 0 {d}); do printf '%0{d}d' $i > $i; done; echo filled", .{ raced_umount_files - 1, raced_umount_file_bytes })));
    }
    var released = false;
    defer if (!released) releaseHold(fifo);
    const mark = try rig.logLen();
    // The unmount in the background and the second mount at once: what
    // `_scratch_unmount & ; sleep 0.01s ; _scratch_mount` does. B's invoker
    // returns only at B's ready line (or its refusal).
    var umounter = try std.process.spawn(io, .{ .argv = &.{ rig.bin, "umount", rig.mp }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .{ .file = log_file }, .stderr = .{ .file = log_file } });
    var umounter_done = false;
    defer if (!umounter_done) {
        _ = umounter.wait(io) catch {};
    };
    const t0 = clock.monotonicNs();
    var mounter = try std.process.spawn(io, .{ .argv = &.{ rig.bin, "mount", "--daemon", "--supervise", "--log-file", rig.log_path, rig.meta_uri, rig.mp }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .{ .file = log_file }, .stderr = .{ .file = log_file } });
    const mounter_pid = mounter.id.?;
    var mounter_done = false;
    defer if (!mounter_done) {
        _ = linux.kill(mounter_pid, .KILL);
        _ = mounter.wait(io) catch {};
    };
    // A parks in its dismount pass: its mount is off the table, its lock
    // held, its process alive — the window generic/604 mounts into.
    _ = try rig.awaitLog("SQUEEZEFS_TEST_PROMOTION_HOLD — holding", mark, ready_wait_ns);
    // B met the lock and WAITS (its own line names the holder and why) —
    // or, the red, it refused (or joined the exiting manager) and returned.
    const waiting_i = blk: {
        const deadline = clock.monotonicNs() + ready_wait_ns;
        while (true) {
            const t = try rig.readLog();
            defer gpa.free(t);
            if (std.mem.indexOf(u8, t[mark..], "holds it and is exiting (")) |i| break :blk mark + i;
            if (!alive(mounter_pid)) {
                mounter_done = true;
                const term = try mounter.wait(io);
                std.debug.print("\n--- {s}: the racing mount returned ({f}) instead of waiting for the exiting holder ---\n{s}\n", .{ label, term, t[mark..] });
                return error.RacingMountRefused;
            }
            if (clock.monotonicNs() >= deadline) {
                std.debug.print("\n--- {s}: the racing mount neither waited nor returned ---\n{s}\n", .{ label, t[mark..] });
                return error.Timeout;
            }
            sleepMs(20);
        }
    };
    try testing.expect(alive(mounter_pid));
    try testing.expect(alive(pid_a));
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    // Released: A promotes, exits 0; its supervisor replays and lets the
    // lock go; the umount verb's verdict is the orderly exit.
    releaseHold(fifo);
    released = true;
    umounter_done = true;
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try umounter.wait(io));
    _ = try rig.awaitLog("clean unmount", mark, exit_wait_ns);
    mounter_done = true;
    const term_b = try mounter.wait(io);
    const waited_ns = clock.monotonicNs() - t0;
    if (term_b != .exited or term_b.exited != 0) {
        const t = try rig.readLog();
        defer gpa.free(t);
        std.debug.print("\n--- {s}: the racing mount returned ({f}) after the holder's release ---\n{s}\n", .{ label, term_b, t[mark..] });
    }
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, term_b);
    try testing.expect(waited_ns < proc.EXITING_HOLDER_WAIT_NS);
    const released_i = try rig.awaitLog("released it after", waiting_i, exit_wait_ns);
    const ready_b = try rig.awaitLog("ready: ", released_i, ready_wait_ns);
    _ = try rig.awaitLog("exited (wait status 0x0); done", mark, exit_wait_ns);
    const after = try rig.readLog();
    defer gpa.free(after);
    const pid_b: linux.pid_t = @intCast(numberAfter(after[ready_b..], "(pid ") orelse return error.NoPid);
    try testing.expect(pid_b != pid_a);
    // Exactly one daemon of the set alive; the mount is B's, and B is its
    // MANAGER (never a joiner of the exiting one).
    try testing.expect(!alive(pid_a));
    try testing.expect(alive(pid_b));
    try testing.expectEqual(@as(usize, 1), try fuseMountsOf(gpa, io, rig.mp));
    try testing.expect(std.mem.indexOf(u8, after[released_i..], "mounted in canonical order as manager") != null);
    try testing.expect(std.mem.indexOf(u8, after[mark..], "joining as appender") == null);
    try expectSupervisorSilent(after[mark..]);
    {
        var script: [192]u8 = undefined;
        gpa.free(try rig.shOk(rig.mp, try std.fmt.bufPrint(&script, "for i in $(seq 0 {d}); do printf '%0{d}d' $i | cmp -s - $i; done; echo whole", .{ raced_umount_files - 1, raced_umount_file_bytes })));
    }
    // The dismount pass promoted what the hold parked; the mechanism's
    // engagement gauge on B.
    try testing.expect(std.mem.indexOf(u8, after[mark..], "dismount promotion: 0 staged") == null);
    {
        const st = try rig.stats();
        defer gpa.free(st);
        const rounds = numberAfter(st, "\"guard_exiting_holder_waits\":") orelse 0;
        const why = after[waiting_i..@min(after.len, waiting_i + 240)];
        std.debug.print("\nsmoke[mount races umount, {s}]: the second mount waited {d} ms behind the exiting holder ({d} round(s)); its first judgement: {s}\n", .{ label, waited_ns / std.time.ns_per_ms, rounds, why[0 .. std.mem.indexOfScalar(u8, why, '\n') orelse why.len] });
        try testing.expect(rounds >= 1);
    }
    return pid_b;
}

/// The rig's current `--daemon --supervise` mount's daemon pid (its ready line after `from`).
fn daemonMountReady(rig: *Rig, from: usize) !linux.pid_t {
    const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, rig.meta_uri, rig.mp });
    defer rig.freeRun(r);
    if (!r.term.success()) std.debug.print("\ndaemon mount: {s}\n", .{r.stderr});
    try testing.expect(r.term.success());
    const ready_i = try rig.awaitLog("ready: ", from, ready_wait_ns);
    const text = try rig.readLog();
    defer rig.gpa.free(text);
    const pid: linux.pid_t = @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid);
    _ = try rig.awaitLog("supervisor: watching daemon ", ready_i, ready_wait_ns);
    return pid;
}

/// The orderly umount of a `--daemon --supervise` mount and its daemon's exit.
fn umountDaemon(rig: *Rig, pid: linux.pid_t) !void {
    try rig.umount();
    const deadline = clock.monotonicNs() + exit_wait_ns;
    while (alive(pid) and clock.monotonicNs() < deadline) sleepMs(20);
    try testing.expect(!alive(pid));
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(rig.gpa, rig.io, rig.mp));
}

test "smoke: A MOUNT THAT RACES THE PREVIOUS UNMOUNT WAITS, THEN SERVES (xfstests generic/604) — a `--daemon --supervise` mount, 501 staged 8 KiB files (never fsync'd) → `squeezefs umount` in the BACKGROUND and a second `--daemon --supervise` mount of the same set at once, the first daemon's dismount pass held on SQUEEZEFS_TEST_PROMOTION_HOLD (its mount already off the table, its writer lock held): the second mount meets the exiting holder's lock and WAITS — its log names the holder and why, it is alive and unmounted while the hold stands, never BUSY → released: the umount exits 0 (`clean unmount`, `exited (wait status 0x0)`), the second mount returns 0 within the orderly-exit ceiling as the set's MANAGER with `guard_exiting_holder_waits` ≥ 1, every file whole, exactly one daemon of the set alive, the supervisors silent → clean umount → `fsck --offline --scrub` 0 findings; the same cycle on a `--single-writer` set (the suites' posture) and on the SYMMETRIC default (where the join door must not be taken against an exiting manager) (red: `another writer holds the single-writer guard … (BUSY, refusal)` at once on the single-writer set — the release run's `-g auto` stopped at generic/604 — and `device I/O failed` from a join of the exiting manager on the symmetric one)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    var fb: [linux.PATH_MAX]u8 = undefined;
    const fifo = try std.fmt.bufPrintSentinel(&fb, "{s}/promotion.fifo", .{rig.work}, 0);
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.mknodat(linux.AT.FDCWD, fifo.ptr, linux.S.IFIFO | 0o600, 0)));
    try rig.env.put("SQUEEZEFS_TEST_PROMOTION_HOLD", fifo);
    if (rig.log_file == null) rig.log_file = try openLogAppend(rig.log_path);
    const log_file = rig.log_file.?;
    // Arm 1: the suites' posture.
    try rig.formatSetWith(true, &.{"--single-writer"});
    {
        const pid_a = try daemonMountReady(rig, 0);
        const pid_b = try racedUnmountCycle(rig, fifo, log_file, pid_a, "single-writer");
        try umountDaemon(rig, pid_b);
    }
    try rig.env.put("SQUEEZEFS_TEST_PROMOTION_HOLD", "off");
    _ = try fsckClean(rig, "the raced unmount cycle (single-writer)");
    // Arm 2: the symmetric default — a fresh set.
    try rig.env.put("SQUEEZEFS_TEST_PROMOTION_HOLD", fifo);
    try rig.formatSet(true);
    {
        const mark = try rig.logLen();
        const pid_a = try daemonMountReady(rig, mark);
        const pid_b = try racedUnmountCycle(rig, fifo, log_file, pid_a, "symmetric");
        try umountDaemon(rig, pid_b);
    }
    try rig.env.put("SQUEEZEFS_TEST_PROMOTION_HOLD", "off");
    _ = try fsckClean(rig, "the raced unmount cycle (symmetric)");
}

test "smoke: THE REPLAY PROOF (charter §5.2 the ack point, decision 0003 §BB) — a `--daemon --supervise` mount under the landing-hold seam acks creates whose journal writes are never issued; kill -9 the daemon: the supervisor replays the journal tail to the device, barriers, and only then releases the writer guard; fsck clean; after the remount every acked create is present; the same creates on a FOREGROUND mount (no supervisor) are gone after its kill — the power-cut window; fsck clean; the cadence's times drain of the directory's parked stamp answers under the held landing (a commit of this mount's own, acked at its apply: drain commits ≥ 1, nothing parked), the directory's next create is served, and the remount reads the drained mtime (red on dev: the drain held the directory's exclusive guard until a landing that never came — under load its 50 ms tick fell between `touch d/x d/y`'s creates and the second parked for good, HUNG TEST)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    // Every window acked and held un-landed from the ready line on; no
    // §L hold (nothing ever lands to end one).
    try rig.env.put("SQUEEZEFS_TEST_JOURNAL_HOLD_LANDING", "1");
    try rig.env.put("SQUEEZEFS_META_WINDOW_HOLD", "none");
    // 1. The supervised arm.
    {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\ndaemon mount: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    }
    const text = try rig.readLog();
    defer gpa.free(text);
    const ready_i = std.mem.indexOf(u8, text, "ready: ") orelse return error.NoReadyLine;
    const pid: linux.pid_t = @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid);
    // A failed step before the kill leaves no daemon behind (its supervisor
    // replays and exits on the death).
    var daemon_live = true;
    defer if (daemon_live) {
        _ = linux.kill(pid, .KILL);
    };
    try testing.expect(std.mem.indexOf(u8, text, "journal tails: 1 volume(s) handed to the supervisor") != null);
    _ = try rig.awaitLog("supervisor: watching daemon ", ready_i, ready_wait_ns);
    {
        // d's stamps in the past: the create's parked stamp advances the
        // stored record, so the drain has a delta to commit.
        const out = try rig.shOk(rig.mp, "mkdir d && touch -d @1000000000 d && touch d/x && echo ok");
        defer gpa.free(out);
    }
    // The cadence's drain of d's parked stamp (one flush interval later):
    // answered under the held landing, the stamp retired.
    {
        const deadline = clock.monotonicNs() + 20 * std.time.ns_per_s;
        while (true) {
            const st = try rig.stats();
            defer gpa.free(st);
            const drains = numberAfter(st, "\"meta_kv_times_echo_drain_commits\":") orelse 0;
            const parked = numberAfter(st, "\"meta_kv_times_echo_pending\":") orelse 1;
            if (drains >= 1 and parked == 0) break;
            if (clock.monotonicNs() >= deadline) {
                std.debug.print("\nsmoke[replay]: the times drain never answered under the held landing (drain commits {d}, parked {d}): its window waits for a landing that never comes, d's exclusive guard with it\n", .{ drains, parked });
                return error.TimesDrainParkedOnLanding;
            }
            sleepMs(20);
        }
    }
    {
        const out = try rig.shOk(rig.mp, "touch d/y && echo hello > d/z && test -e d/x && echo ok");
        defer gpa.free(out);
    }
    // Acked, never landed: the tail holds them.
    daemon_live = false;
    _ = linux.kill(pid, .KILL);
    const replay_i = try rig.awaitLog("supervisor: journal tail of volume 0 (", ready_i, 20 * std.time.ns_per_s);
    const released_i = try rig.awaitLog("supervisor: writer guard released on 1 volume(s) after the replay", ready_i, 20 * std.time.ns_per_s);
    try testing.expect(released_i > replay_i);
    _ = try rig.awaitLog("); done", released_i, 20 * std.time.ns_per_s);
    {
        const after = try rig.readLog();
        defer gpa.free(after);
        const line = after[replay_i - 1 ..];
        const n = numberAfter(after[replay_i..], "): ") orelse return error.NoReplayCount;
        std.debug.print("\nsmoke[replay]: {s}\n", .{line[0 .. std.mem.indexOfScalar(u8, line, '\n') orelse line.len]});
        try testing.expect(n >= 1);
        try testing.expect(std.mem.indexOf(u8, after, "replay FAILED") == null);
    }
    try rig.umountAfterKill();
    _ = rig.env.swapRemove("SQUEEZEFS_TEST_JOURNAL_HOLD_LANDING");
    _ = try fsckClean(rig, "the supervised kill");
    {
        const mark = try rig.logLen();
        try rig.spawnMount(&.{});
        _ = try rig.awaitReady(mark);
    }
    {
        const out = try rig.shOk(rig.mp, "test -d d && test -e d/x && test -e d/y && test \"$(cat d/z)\" = hello && test \"$(stat -c %Y d)\" -gt 1000000000 && echo present");
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "present") != null);
    }
    {
        const out = try rig.onMount("rm -r d && echo ok");
        defer gpa.free(out);
    }
    try rig.umount();
    try testing.expect(try rig.waitChild() == .exited);
    _ = try fsckClean(rig, "the supervised arm's clean unmount");

    // 2. The control arm: a foreground mount — no supervisor, no replay.
    try rig.env.put("SQUEEZEFS_TEST_JOURNAL_HOLD_LANDING", "1");
    const mark = try rig.logLen();
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(mark);
    {
        const fg = try rig.readLog();
        defer gpa.free(fg);
        try testing.expect(std.mem.indexOf(u8, fg[mark..], "no supervisor holds the journal tail") != null);
    }
    {
        const out = try rig.shOk(rig.mp, "mkdir e && touch e/w && test -e e/w && echo ok");
        defer gpa.free(out);
    }
    rig.killed = true;
    _ = linux.kill(rig.child_pid, .KILL);
    try testing.expectEqual(std.process.Child.Term{ .signal = .KILL }, try rig.waitChild());
    try rig.umountAfterKill();
    _ = rig.env.swapRemove("SQUEEZEFS_TEST_JOURNAL_HOLD_LANDING");
    _ = try fsckClean(rig, "the foreground kill");
    {
        const mark2 = try rig.logLen();
        try rig.spawnMount(&.{});
        _ = try rig.awaitReady(mark2);
    }
    {
        const out = try rig.shOk(rig.mp, "if test -e e/w; then echo kept; else echo lost; fi");
        defer gpa.free(out);
        std.debug.print("smoke[replay]: the foreground arm's acked create after its kill: {s}", .{out});
        try testing.expect(std.mem.indexOf(u8, out, "lost") != null);
    }
    try rig.umount();
    try testing.expect(try rig.waitChild() == .exited);
    _ = try fsckClean(rig, "the foreground arm's clean unmount");
}

/// A set over ONE device-mapper device whose table flips between `linear`
/// and `error` (xfstests `common/dmerror`): a loop device over a sparse
/// file under the rig's work dir, the switchable device over it, and the
/// set's three slices over that (the suites' layout, `setpaths.sh`). Names
/// are pid-tagged; `down` is idempotent and runs on every exit.
const DmErrorSet = struct {
    rig: *Rig,
    name: []u8,
    loop: []u8 = &.{},
    sectors: u64 = 0,
    meta_uri: []u8,
    data_uri: []u8,
    up_count: u8 = 0,

    const meta_sectors: u64 = (512 << 20) / 512;
    const data_sectors: u64 = (128 << 20) / 512;

    /// The venue's device-mapper and loop driver (root, `dmsetup`,
    /// `losetup`), else the skip's reason.
    fn venueMissing() ?testkit.Why {
        for ([_][:0]const u8{ "/dev/mapper/control", "/dev/loop-control" }) |node| {
            const rc = linux.open(node.ptr, .{ .ACCMODE = .RDWR, .CLOEXEC = true }, 0);
            if (linux.errno(rc) != .SUCCESS) return .{ .class = .no_device, .detail = node };
            _ = linux.close(@intCast(rc));
        }
        return null;
    }

    fn up(rig: *Rig) !DmErrorSet {
        const gpa = rig.gpa;
        const pid = linux.getpid();
        const name = try std.fmt.allocPrint(gpa, "sqz-smoke-{d}-err", .{pid});
        errdefer gpa.free(name);
        const meta_uri = try std.fmt.allocPrint(gpa, "sqmeta:///dev/mapper/{s}-meta", .{name});
        errdefer gpa.free(meta_uri);
        const data_uri = try std.fmt.allocPrint(gpa, "sqdata:///dev/mapper/{s}-d0,/dev/mapper/{s}-d1", .{ name, name });
        errdefer gpa.free(data_uri);
        var self: DmErrorSet = .{ .rig = rig, .name = name, .meta_uri = meta_uri, .data_uri = data_uri, .sectors = meta_sectors + 2 * data_sectors };
        errdefer self.down();
        var script: [1024]u8 = undefined;
        const out = try rig.shOk(rig.work, try std.fmt.bufPrint(&script,
            \\truncate -s {d} dmerr.img
            \\losetup -f --show dmerr.img
        , .{self.sectors * 512}));
        defer gpa.free(out);
        self.loop = try gpa.dupe(u8, std.mem.trim(u8, out, " \n"));
        self.up_count = 1;
        gpa.free(try rig.shOk(rig.work, try std.fmt.bufPrint(&script,
            \\dmsetup create {s} --table "0 {d} linear {s} 0"
            \\dmsetup create {s}-meta --table "0 {d} linear /dev/mapper/{s} 0"
            \\dmsetup create {s}-d0 --table "0 {d} linear /dev/mapper/{s} {d}"
            \\dmsetup create {s}-d1 --table "0 {d} linear /dev/mapper/{s} {d}"
            \\dmsetup mknodes >/dev/null 2>&1 || true
            \\echo up
        , .{ name, self.sectors, self.loop, name, meta_sectors, name, name, data_sectors, name, meta_sectors, name, data_sectors, name, meta_sectors + data_sectors })));
        self.up_count = 2;
        return self;
    }

    /// The venue's dm-delay target (loaded on demand), else the skip's
    /// reason.
    fn delayMissing(rig: *Rig) ?testkit.Why {
        const r = rig.sh(rig.work, "modprobe dm-delay >/dev/null 2>&1; dmsetup targets | grep -q '^delay '") catch return .{ .class = .no_kernel_feature, .detail = "dm-delay" };
        defer rig.freeRun(r);
        return if (r.term.success()) null else .{ .class = .no_kernel_feature, .detail = "dm-delay" };
    }

    /// Every write and flush of the set `ms` slower (dm-delay over the
    /// whole device; reads untouched) — a slow metadata device's latency;
    /// 0 swaps the working table back. Suspended without lockfs, as `load`.
    fn delayWrites(self: *DmErrorSet, ms: u32) !void {
        var script: [512]u8 = undefined;
        const table = if (ms == 0) try std.fmt.bufPrint(script[256..], "0 {d} linear {s} 0", .{ self.sectors, self.loop }) else try std.fmt.bufPrint(script[256..], "0 {d} delay {s} 0 0 {s} 0 {d}", .{ self.sectors, self.loop, self.loop, ms });
        self.rig.gpa.free(try self.rig.shOk(self.rig.work, try std.fmt.bufPrint(script[0..256], "dmsetup suspend --nolockfs {s} && dmsetup load {s} --table \"{s}\" && dmsetup resume {s} && echo ok", .{ self.name, self.name, table, self.name })));
    }

    /// The venue's dm-flakey target (loaded on demand), else the skip's
    /// reason.
    fn flakeyMissing(rig: *Rig) ?testkit.Why {
        const r = rig.sh(rig.work, "modprobe dm-flakey >/dev/null 2>&1; dmsetup targets | grep -q '^flakey '") catch return .{ .class = .no_kernel_feature, .detail = "dm-flakey" };
        defer rig.freeRun(r);
        return if (r.term.success()) null else .{ .class = .no_kernel_feature, .detail = "dm-flakey" };
    }

    /// A POWER CUT from this instant (xfstests `_load_flakey_table
    /// $FLAKEY_DROP_WRITES`): every write and flush of the set is
    /// acknowledged and dropped, reads served; false swaps the working
    /// table back. Suspended without lockfs, as `load`.
    fn dropWrites(self: *DmErrorSet, drop: bool) !void {
        var script: [512]u8 = undefined;
        const table = if (drop) try std.fmt.bufPrint(script[256..], "0 {d} flakey {s} 0 0 180 1 drop_writes", .{ self.sectors, self.loop }) else try std.fmt.bufPrint(script[256..], "0 {d} linear {s} 0", .{ self.sectors, self.loop });
        self.rig.gpa.free(try self.rig.shOk(self.rig.work, try std.fmt.bufPrint(script[0..256], "dmsetup suspend --nolockfs {s} && dmsetup load {s} --table \"{s}\" && dmsetup resume {s} && echo ok", .{ self.name, self.name, table, self.name })));
    }

    /// The table swap without lockfs (`_dmerror_load_error_table`'s
    /// sudden disk failure; `_dmerror_load_working_table`).
    fn load(self: *DmErrorSet, failing: bool) !void {
        var script: [512]u8 = undefined;
        const table = if (failing) try std.fmt.bufPrint(script[256..], "0 {d} error", .{self.sectors}) else try std.fmt.bufPrint(script[256..], "0 {d} linear {s} 0", .{ self.sectors, self.loop });
        self.rig.gpa.free(try self.rig.shOk(self.rig.work, try std.fmt.bufPrint(script[0..256], "dmsetup suspend --nolockfs {s} && dmsetup load {s} --table \"{s}\" && dmsetup resume {s} && echo ok", .{ self.name, self.name, table, self.name })));
    }

    fn down(self: *DmErrorSet) void {
        const gpa = self.rig.gpa;
        var script: [1024]u8 = undefined;
        if (self.up_count >= 1) {
            // A row that failed mid-cycle leaves its daemon (and supervisor)
            // holding the slices: killed and detached first (`[/]` keeps the
            // pattern from matching this shell's own command line).
            const cmd = std.fmt.bufPrint(&script, "pkill -KILL -f '[/]dev/mapper/{s}-meta' >/dev/null 2>&1 || true; umount -l {s} >/dev/null 2>&1 || true; dmsetup resume {s} >/dev/null 2>&1 || true; for s in -d1 -d0 -meta ''; do dmsetup remove --retry {s}$s >/dev/null 2>&1 || true; done; losetup -d {s} >/dev/null 2>&1 || true; rm -f dmerr.img", .{ self.name, self.rig.mp, self.name, self.name, self.loop }) catch "";
            if (self.rig.sh(self.rig.work, cmd)) |r| self.rig.freeRun(r) else |_| {}
        }
        self.up_count = 0;
        if (self.loop.len != 0) gpa.free(self.loop);
        self.loop = &.{};
    }

    fn deinit(self: *DmErrorSet) void {
        self.down();
        const gpa = self.rig.gpa;
        gpa.free(self.name);
        gpa.free(self.meta_uri);
        gpa.free(self.data_uri);
    }
};

/// A set whose DATA volumes are thin volumes of a dm-thin pool far smaller
/// than they claim (xfstests generic/347's device): the metadata volume a
/// linear slice of the same loop file, the pool's data device a linear
/// slice the row can grow, the pool in `error_if_no_space` (a DMA past the
/// pool's last block answers ENOSPC at once — 347's pool after its
/// `no_space_timeout`). The allocator sees two whole virtual volumes: the
/// device refuses DMAs while the allocator has free blocks in sight.
const DmThinSet = struct {
    rig: *Rig,
    name: []u8,
    loop: []u8 = &.{},
    meta_uri: []u8,
    data_uri: []u8,
    up: bool = false,

    const meta_sectors: u64 = (512 << 20) / 512;
    const pool_meta_sectors: u64 = (16 << 20) / 512;
    /// The pool's data device at setup, and the room the row grows it to.
    const pool_data_sectors: u64 = (64 << 20) / 512;
    const pool_data_max_sectors: u64 = (1024 << 20) / 512;
    /// Each thin volume's virtual size: what the allocator believes.
    const thin_sectors: u64 = (1024 << 20) / 512;
    /// 64 KiB: the pool's smallest data block.
    const pool_block_sectors: u64 = 128;

    fn missing(rig: *Rig) ?testkit.Why {
        const r = rig.sh(rig.work, "modprobe dm-thin-pool >/dev/null 2>&1; dmsetup targets | grep -q '^thin-pool ' && command -v losetup >/dev/null") catch return .{ .class = .no_kernel_feature, .detail = "dm-thin-pool" };
        defer rig.freeRun(r);
        return if (r.term.success()) null else .{ .class = .no_kernel_feature, .detail = "dm-thin-pool" };
    }

    fn init(rig: *Rig) !DmThinSet {
        const gpa = rig.gpa;
        const name = try std.fmt.allocPrint(gpa, "sqz-smoke-{d}-thin", .{linux.getpid()});
        errdefer gpa.free(name);
        const meta_uri = try std.fmt.allocPrint(gpa, "sqmeta:///dev/mapper/{s}-meta", .{name});
        errdefer gpa.free(meta_uri);
        const data_uri = try std.fmt.allocPrint(gpa, "sqdata:///dev/mapper/{s}-d0,/dev/mapper/{s}-d1", .{ name, name });
        errdefer gpa.free(data_uri);
        var self: DmThinSet = .{ .rig = rig, .name = name, .meta_uri = meta_uri, .data_uri = data_uri };
        errdefer self.down();
        var script: [2048]u8 = undefined;
        const total = meta_sectors + pool_meta_sectors + pool_data_max_sectors;
        const out = try rig.shOk(rig.work, try std.fmt.bufPrint(&script,
            \\truncate -s {d} dmthin.img
            \\losetup -f --show dmthin.img
        , .{total * 512}));
        defer gpa.free(out);
        self.loop = try gpa.dupe(u8, std.mem.trim(u8, out, " \n"));
        self.up = true;
        gpa.free(try rig.shOk(rig.work, try std.fmt.bufPrint(&script,
            \\dmsetup create {[n]s}-meta --table "0 {[ms]d} linear {[l]s} 0"
            \\dmsetup create {[n]s}-tmeta --table "0 {[pms]d} linear {[l]s} {[ms]d}"
            \\dmsetup create {[n]s}-tdata --table "0 {[pds]d} linear {[l]s} {[pdo]d}"
            \\dd if=/dev/zero of=/dev/mapper/{[n]s}-tmeta bs=4096 count=1 conv=fsync status=none
            \\dmsetup create {[n]s}-pool --table "0 {[pds]d} thin-pool /dev/mapper/{[n]s}-tmeta /dev/mapper/{[n]s}-tdata {[pb]d} 0 1 error_if_no_space"
            \\dmsetup message /dev/mapper/{[n]s}-pool 0 "create_thin 0"
            \\dmsetup message /dev/mapper/{[n]s}-pool 0 "create_thin 1"
            \\dmsetup create {[n]s}-d0 --table "0 {[ts]d} thin /dev/mapper/{[n]s}-pool 0"
            \\dmsetup create {[n]s}-d1 --table "0 {[ts]d} thin /dev/mapper/{[n]s}-pool 1"
            \\dmsetup mknodes >/dev/null 2>&1 || true
            \\echo up
        , .{ .n = name, .l = self.loop, .ms = meta_sectors, .pms = pool_meta_sectors, .pds = pool_data_sectors, .pdo = meta_sectors + pool_meta_sectors, .pb = pool_block_sectors, .ts = thin_sectors })));
        return self;
    }

    /// The pool's data device grown to its whole slice (`_dmthin_grow`):
    /// the pool leaves its out-of-space mode and the refused DMAs land.
    fn grow(self: *DmThinSet) !void {
        var script: [1024]u8 = undefined;
        self.rig.gpa.free(try self.rig.shOk(self.rig.work, try std.fmt.bufPrint(&script,
            \\dmsetup suspend {[n]s}-tdata && dmsetup load {[n]s}-tdata --table "0 {[pds]d} linear {[l]s} {[pdo]d}" && dmsetup resume {[n]s}-tdata
            \\dmsetup suspend {[n]s}-pool && dmsetup load {[n]s}-pool --table "0 {[pds]d} thin-pool /dev/mapper/{[n]s}-tmeta /dev/mapper/{[n]s}-tdata {[pb]d} 0 1 error_if_no_space" && dmsetup resume {[n]s}-pool
            \\echo grown
        , .{ .n = self.name, .l = self.loop, .pds = pool_data_max_sectors, .pdo = meta_sectors + pool_meta_sectors, .pb = pool_block_sectors })));
    }

    fn down(self: *DmThinSet) void {
        if (!self.up) return;
        self.up = false;
        var script: [1024]u8 = undefined;
        const cmd = std.fmt.bufPrint(&script, "pkill -KILL -f '[/]dev/mapper/{s}-meta' >/dev/null 2>&1 || true; umount -l {s} >/dev/null 2>&1 || true; for s in d1 d0 pool tdata tmeta meta; do dmsetup resume {s}-$s >/dev/null 2>&1 || true; dmsetup remove --retry {s}-$s >/dev/null 2>&1 || true; done; losetup -d {s} >/dev/null 2>&1 || true; rm -f dmthin.img", .{ self.name, self.rig.mp, self.name, self.name, self.loop }) catch "";
        if (self.rig.sh(self.rig.work, cmd)) |r| self.rig.freeRun(r) else |_| {}
        self.rig.gpa.free(self.loop);
        self.loop = &.{};
    }

    fn deinit(self: *DmThinSet) void {
        self.down();
        const gpa = self.rig.gpa;
        gpa.free(self.name);
        gpa.free(self.meta_uri);
        gpa.free(self.data_uri);
    }
};

/// THE STALLED-PLANE ROW's request timeout (the frozen-daemon seam): the
/// kernel aborts a request older than this at its next 15 s check, so a
/// write the daemon held past it ends the mount within 30–45 s.
const stalled_plane_request_timeout_s: u16 = 30;

/// One timed fill of the stalled-plane mount (xfstests generic/347's
/// shape): `files` files `<prefix><i>` preallocated (`fallocate -l 2M`, the
/// blocks reserved, nothing written on the thin pool), then 1 MiB written
/// into each at byte 512 (`dd conv=notrunc`: off the page grain, so neither
/// the overlay nor the in-place patch takes it — the accumulation arm parks
/// a partial block whose landing is the device's) until the first refusal, under a KILL
/// bound past the kernel's abort; the refusal's exit code (0 = none), the
/// file it met, the writes' wall time and dd's stderr.
const TimedFill = struct { rc: u32, at: u32, ms: u64, err: []u8 };

fn timedFill(rig: *Rig, prefix: []const u8, files: u32) !TimedFill {
    var script: [768]u8 = undefined;
    const r = try rig.sh(rig.mp, try std.fmt.bufPrint(&script, "err=$(mktemp); for i in $(seq 1 {[n]d}); do fallocate -l 2M {[p]s}$i; done; s=$(date +%s%N); rc=0; at=0; for i in $(seq 1 {[n]d}); do timeout -s KILL 120 dd if=/dev/urandom of={[p]s}$i bs=1M count=1 seek=512 oflag=seek_bytes conv=notrunc status=none 2>\"$err\" || {{ rc=$?; at=$i; break; }}; done; e=$(date +%s%N); echo $rc $at $(( (e - s) / 1000000 )); cat \"$err\" >&2; rm -f \"$err\"", .{ .p = prefix, .n = files }));
    defer rig.gpa.free(r.stdout);
    errdefer rig.gpa.free(r.stderr);
    var it = std.mem.tokenizeAny(u8, r.stdout, " \n");
    const rc = std.fmt.parseInt(u32, it.next() orelse return error.NoRc, 10) catch return error.NoRc;
    const at = std.fmt.parseInt(u32, it.next() orelse return error.NoAt, 10) catch return error.NoAt;
    const ms = std.fmt.parseInt(u64, it.next() orelse return error.NoMs, 10) catch return error.NoMs;
    return .{ .rc = rc, .at = at, .ms = ms, .err = r.stderr };
}

test "smoke: A WRITE HELD BEHIND A DEVICE THAT REFUSES EVERY DMA ANSWERS BEFORE THE KERNEL'S REQUEST DEADLINE AND THE MOUNT KEEPS SERVING (the daemon answers, never holds — xfstests generic/347) — a set whose two data volumes are thin volumes of a 64 MiB dm-thin pool in error_if_no_space (the allocator sees 2 GiB free), the write cache off, 8 parked buffers, the FUSE request timeout 30 s → a 1 MiB file written and synced → 64 files preallocated and 1 MiB written into each off the page grain (generic/347's shape: the accumulation arm parks each): the pool fills, every later DMA answers ENOSPC, the parked set fills, the next write meets the parked-buffer gate behind a stalled plane and answers ENOSPC before the 30 s request deadline (red on dev: held at the gate until the kernel aborted the connection at 30.7 s — ENOTCONN, the daemon fail-stopped) → a second writer during the stall answers within two ticks → `stat` and a read of the synced file succeed, the daemon alive → the pool grown: the parked set lands, `sync -f` succeeds → umount clean → `fsck --offline --scrub` 0 findings" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    if (DmErrorSet.venueMissing()) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    if (DmThinSet.missing(rig)) |why| return testkit.skipWhy(@src(), why);
    var dm = try DmThinSet.init(rig);
    defer dm.deinit();
    var timeout_text: [8]u8 = undefined;
    try rig.env.put("SQUEEZEFS_TEST_FUSE_REQUEST_TIMEOUT_S", try std.fmt.bufPrint(&timeout_text, "{d}", .{stalled_plane_request_timeout_s}));
    try rig.env.put("SQUEEZEFS_WRITE_CACHE_PCT", "0");
    try rig.env.put("SQUEEZEFS_PARKED_BUFFERS", "8");
    {
        const r = try rig.squeezefs(&.{ "format", dm.meta_uri, dm.data_uri });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\nformat: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    }
    try rig.spawnMountOf(dm.meta_uri, &.{});
    _ = try rig.awaitReady(0);
    const kept = try rig.onMount("dd if=/dev/urandom of=keep bs=1M count=1 conv=fsync status=none && sha256sum keep");
    defer gpa.free(kept);
    // The stall: the pool fills under the stream, the parked set behind it.
    const big = try timedFill(rig, "f", 64);
    defer gpa.free(big.err);
    std.debug.print("\nsmoke[stalled plane]: 64 preallocated 1 MiB files written in place onto a 64 MiB pool: rc {d} at file {d} after {d} ms: {s}\n", .{ big.rc, big.at, big.ms, big.err });
    try rig.expectAlive("the stalled write's answer");
    try testing.expect(big.rc != 0);
    try testing.expect(std.mem.indexOf(u8, big.err, "No space left on device") != null);
    try testing.expect(big.ms < @as(u64, stalled_plane_request_timeout_s) * std.time.ms_per_s);
    // A second writer meets the same stalled gate: answered at once.
    const more = try timedFill(rig, "g", 4);
    defer gpa.free(more.err);
    std.debug.print("smoke[stalled plane]: a second writer during the stall: rc {d} at file {d} after {d} ms: {s}\n", .{ more.rc, more.at, more.ms, more.err });
    try rig.expectAlive("the second writer's answer");
    try testing.expect(more.rc != 0);
    try testing.expect(more.ms < 2 * tick_law.tick_ns / std.time.ns_per_ms + 2 * std.time.ms_per_s);
    {
        // Both answers were the gate's stall answer, after a counted stall.
        const st = try rig.stats();
        defer gpa.free(st);
        std.debug.print("smoke[stalled plane]: stall answers {d}, plane stalls {d}, joined refusals taken {d}\n", .{ numberAfter(st, "\"parked_gate_stall_answers\":") orelse 0, numberAfter(st, "\"parked_gate_wall_plane_stalls\":") orelse 0, numberAfter(st, "\"upload_join_refusals_taken\":") orelse 0 });
        try testing.expect((numberAfter(st, "\"parked_gate_stall_answers\":") orelse 0) >= 2);
        try testing.expect((numberAfter(st, "\"parked_gate_wall_plane_stalls\":") orelse 0) >= 1);
        // The held write is the op watchdog's overdue op by design (held
        // up to the bound); no "cannot happen" fired, the volume is live.
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"invariant_tripwires\":"));
        try testing.expect(std.mem.indexOf(u8, st, "\"volume_failed\":false") != null);
    }
    // The mount serves everything else.
    {
        const back = try rig.onMount("stat -c %s keep && sha256sum keep");
        defer gpa.free(back);
        try testing.expect(std.mem.endsWith(u8, back, kept));
        try testing.expect(std.mem.startsWith(u8, back, "1048576\n"));
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expect(std.mem.indexOf(u8, text, "the kernel ended the FUSE connection") == null);
    }
    // The pool grows: the refused custody lands and the sync point holds.
    try dm.grow();
    gpa.free(try rig.onMountTimed("sync -f . && echo synced", 120));
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    const r = try rig.squeezefs(&.{ "fsck", "--offline", "--scrub", dm.meta_uri });
    defer rig.freeRun(r);
    if (!r.term.success() or std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") == null) std.debug.print("\n--- fsck --offline after the stalled plane ({f}) ---\n{s}\n--- stderr ---\n{s}\n", .{ r.term, r.stdout, r.stderr });
    try testing.expect(std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") != null);
}

/// One worker of the xattr storm (generic/753's fsstress mix: unlink and
/// rmdir heavy, xattr sets, lists and gets of up to 2,000 names per file —
/// values mostly small so 64 files stay far below the metadata volume's
/// capacity: a full volume answers ENOSPC, never the FAILED path) under
/// `<mp>/w<N>`; every refusal (EIO on the FAILED volume) is swallowed — the
/// storm runs until killed.
const xattr_storm_script =
    \\import os, random, sys
    \\mp, w = sys.argv[1], sys.argv[2]
    \\d = os.path.join(mp, "w" + w)
    \\r = random.Random(int(w))
    \\sizes = (8, 32, 256, 256, 4000)
    \\while True:
    \\    try:
    \\        os.makedirs(d, exist_ok=True)
    \\        f = os.path.join(d, "f%d" % r.randrange(16))
    \\        op = r.randrange(100)
    \\        if op < 3:
    \\            os.unlink(f)
    \\        elif op < 6:
    \\            s = os.path.join(d, "s%d" % r.randrange(4))
    \\            os.mkdir(s)
    \\            os.rmdir(s)
    \\        else:
    \\            if not os.path.exists(f):
    \\                open(f, "a").close()
    \\            if op < 60:
    \\                os.setxattr(f, "user.a%d" % r.randrange(2000), b"x" * r.choice(sizes))
    \\            elif op < 70:
    \\                os.removexattr(f, "user.a%d" % r.randrange(2000))
    \\            elif op < 90:
    \\                os.listxattr(f)
    \\            else:
    \\                names = os.listxattr(f)
    \\                if names:
    \\                    os.getxattr(f, r.choice(names))
    \\    except OSError:
    \\        pass
;

/// One worker of the data storm beside it (generic/475's fsstress shape on
/// the data plane): 64 KiB writes with an fsync, 4 KiB overwrites in place,
/// reads, and a `syncfs` of the mount, over 8 files of `<mp>/d<N>`; every
/// refusal is swallowed — the storm runs until killed.
const data_storm_script =
    \\import ctypes, os, random, sys
    \\mp, w = sys.argv[1], sys.argv[2]
    \\d = os.path.join(mp, "d" + w)
    \\r = random.Random(int(w))
    \\libc = ctypes.CDLL(None, use_errno=True)
    \\big, small = b"y" * 65536, b"z" * 4096
    \\while True:
    \\    try:
    \\        os.makedirs(d, exist_ok=True)
    \\        fd = os.open(os.path.join(d, "f%d" % r.randrange(8)), os.O_RDWR | os.O_CREAT, 0o644)
    \\        try:
    \\            op = r.randrange(100)
    \\            if op < 40:
    \\                os.pwrite(fd, big, r.randrange(16) * 65536)
    \\                os.fsync(fd)
    \\            elif op < 70:
    \\                os.pwrite(fd, small, r.randrange(256) * 4096)
    \\            elif op < 92:
    \\                os.pread(fd, 65536, r.randrange(16) * 65536)
    \\            else:
    \\                libc.syncfs(fd)
    \\        finally:
    \\            os.close(fd)
    \\    except OSError:
    \\        pass
;

const dm_error_cycles: usize = 8;
const dm_error_storm_workers: usize = 4;
const dm_error_data_workers: usize = 2;

/// The per-operation failure lines of a set (`journal.FailureLatch.LogClass`:
/// the metadata volume's and the data plane's): once the volume latched
/// FAILED every operation behind it fails the same way, so each class logs
/// at most one line from the latch to the daemon's exit (generic/753's
/// scratch daemons logged ~50 of each per mount; generic/475's up to 67
/// fsync legs). A line is in a class when it carries `needle` (and `also`).
const failed_volume_line_classes = [_]struct { name: []const u8, needle: []const u8, also: ?[]const u8 = null }{
    .{ .name = "window write", .needle = ") write failed: " },
    .{ .name = "hole checkpoint (drain)", .needle = "post-failure checkpoint could not drain" },
    .{ .name = "hole checkpoint (isolation)", .needle = "post-isolation checkpoint could not cover" },
    .{ .name = "hole cover under the SMO lock", .needle = "is not covered from the lane" },
    .{ .name = "node read", .needle = ": node read at offset " },
    .{ .name = "bset append", .needle = ": bset append at offset " },
    .{ .name = "node image", .needle = ": node image at offset " },
    .{ .name = "ledger slot", .needle = ": ledger slot at offset " },
    .{ .name = "bitmap page", .needle = ": bitmap page at offset " },
    .{ .name = "fdatasync", .needle = ": fdatasync at offset " },
    .{ .name = "journal entry", .needle = ": journal entry at offset " },
    .{ .name = "checkpoint tick", .needle = "kv checkpoint tick failed" },
    .{ .name = "maintenance pass", .needle = "kv maintenance pass failed" },
    .{ .name = "fsync leg", .needle = ": a leg failed (", .also = "fsync ino " },
    .{ .name = "syncfs leg", .needle = "syncfs: a leg failed (" },
    .{ .name = "in-place DMA", .needle = ": DMA failed (" },
    .{ .name = "edge seed read", .needle = "the edge seed read of page" },
    .{ .name = "lost staged read", .needle = "staged payload unreachable" },
    .{ .name = "block-map commit", .needle = "the block-map commit of" },
};

/// A failed node read on a volume that never latches FAILED opens a
/// read-failure episode (one line), closed by the next node read that lands.
const read_episode_closed = "the read-failure episode closed";

/// The lines of class `c` in `t`.
fn classLines(t: []const u8, c: @TypeOf(failed_volume_line_classes[0])) usize {
    var n: usize = 0;
    var it = std.mem.splitScalar(u8, t, '\n');
    while (it.next()) |line| {
        if (std.mem.indexOf(u8, line, c.needle) == null) continue;
        if (c.also) |a| if (std.mem.indexOf(u8, line, a) == null) continue;
        n += 1;
    }
    return n;
}

/// The census of one cycle's daemon log `t` (its mount to its exit). A
/// latched cycle: each class's lines from the first latch line on, at most
/// one. A cycle that never latched: the node-read lines, at most one per
/// read-failure episode (its open; every close is a line of its own).
/// False when either law broke (printed).
fn failedVolumeLinesOnce(t: []const u8, cycle: usize) bool {
    const marked = std.mem.indexOf(u8, t, "volume marked FAILED");
    const latching = std.mem.indexOf(u8, t, "latching the volume FAILED");
    const at = @min(marked orelse t.len, latching orelse t.len);
    if (at == t.len) {
        const reads = classLines(t, failed_volume_line_classes[4]);
        const closes = std.mem.count(u8, t, read_episode_closed);
        if (reads != 0) std.debug.print("\nsmoke[dm-error]: cycle {d} (never latched): {d} node-read line(s), {d} episode close(s)", .{ cycle, reads, closes });
        return reads <= closes + 1;
    }
    const from = (std.mem.lastIndexOfScalar(u8, t[0..at], '\n') orelse 0);
    var ok = true;
    for (failed_volume_line_classes) |c| {
        const before = classLines(t[0..from], c);
        const after = classLines(t[from..], c);
        if (before + after != 0) std.debug.print("\nsmoke[dm-error]: cycle {d}: {s}: {d} line(s) before the latch, {d} after", .{ cycle, c.name, before, after });
        if (after > 1) ok = false;
    }
    return ok;
}

test "smoke: A FAILED VOLUME'S DAEMON SERVES EIO UNTIL ITS UNMOUNT AND NEVER DIES OF IT — ITS UNMOUNT ALWAYS COMPLETES AND NEVER LEAVES A SERVER-LESS MOUNT (xfstests generic/753; charter §1.8) — a set over a device-mapper device whose table flips to `error` without lockfs under an xattr storm, 8 cycles: the volume latches FAILED (a create answers EIO), the daemon stays alive with its mount in the table; the storm killed, `squeezefs umount` exits 0 without the `no squeezefs daemon serves it` fallback, the daemon exits 1 by itself naming the FAILED member (its supervisor: `exited (wait status 0x100)` — never a signal), no mount at the path, a second `squeezefs umount` answers `not mounted`; the working table back, the next mount serves the storm's tree, unmounts clean and the set fscks clean; once a volume latched FAILED each per-operation failure class (window write, hole cover, node read, bset append, checkpoint tick, …) logs at most ONE line until the exit, the rest counted (red on 517121d: up to 226 window-write, 231 hole and 210 bset-append lines after the latch in one cycle) — the data plane's classes too, under a cache-less data storm beside it (fsync and syncfs legs, in-place DMAs, edge seed reads, lost staged reads, block-map commits); a cycle whose volume never latches logs ONE node-read line per read-failure episode (red on 5d3e411: 11,463 in-place DMA lines after the latch in one cycle, 5,910 node-read lines in the never-latched one) (red on 7a6e224: every failed node read freed its 256 KiB buffer twice — the second munmap took a FUSE worker's live listxattr array, SIGSEGV, wait status 0x8b, the test's unmount met a mount with no daemon)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    if (DmErrorSet.venueMissing()) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    // The cache-less posture: the data storm's bytes go straight to the data
    // volumes. With the write cache, a FAILED daemon's supervisor holds the
    // unpromoted ring for the next mount, and the cycle's second umount
    // meets that supervisor instead of `not mounted`.
    try rig.env.put("SQUEEZEFS_WRITE_CACHE_PCT", "0");
    var dm = try DmErrorSet.up(rig);
    defer dm.deinit();
    if (rig.log_file == null) rig.log_file = try openLogAppend(rig.log_path);
    {
        const r = try rig.squeezefs(&.{ "format", dm.meta_uri, dm.data_uri });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\nformat: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    }
    // A cycle's failed replay is held (decision 0003 §BR) — here, in the
    // rig's work dir — and the next cycle's mount replays it.
    var held_buf: [linux.PATH_MAX]u8 = undefined;
    try rig.env.put("SQUEEZEFS_TEST_JOURNAL_TAIL_DIR", try std.fmt.bufPrint(&held_buf, "{s}/held-tails", .{rig.work}));
    var latched_cycles: usize = 0;
    var lines_once = true;
    var cycle: usize = 0;
    while (cycle < dm_error_cycles) : (cycle += 1) {
        const mark = try rig.logLen();
        const pid = blk: {
            const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, "-o", "default_permissions,allow_other", dm.meta_uri, rig.mp });
            defer rig.freeRun(r);
            if (!r.term.success()) {
                const t = try rig.readLog();
                defer gpa.free(t);
                std.debug.print("\ncycle {d}: daemon mount: {s}\n--- its log ---\n{s}\n", .{ cycle, r.stderr, t[@min(mark, t.len)..] });
                return error.MountFailed;
            }
            const ready_i = try rig.awaitLog("ready: ", mark, ready_wait_ns);
            const text = try rig.readLog();
            defer gpa.free(text);
            break :blk @as(linux.pid_t, @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid));
        };
        var workers: [dm_error_storm_workers + dm_error_data_workers]std.process.Child = undefined;
        var spawned: usize = 0;
        defer for (workers[0..spawned]) |*w| {
            if (w.id) |wp| _ = linux.kill(-wp, .KILL);
            w.kill(io);
        };
        while (spawned < workers.len) : (spawned += 1) {
            var nb: [8]u8 = undefined;
            const script = if (spawned < dm_error_storm_workers) xattr_storm_script else data_storm_script;
            workers[spawned] = try std.process.spawn(io, .{ .argv = &.{ "python3", "-c", script, rig.mp, try std.fmt.bufPrint(&nb, "{d}", .{spawned}) }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore, .pgid = 0 });
        }
        // generic/753's `sleep $((RANDOM % 3))`, 0 included: the failure
        // lands right after the bring-up too.
        sleepMs(400 * (cycle % 3));
        try dm.load(true);
        // FAILED: a create answers EIO (the first may still be acked in RAM;
        // its journal write fails and latches the volume).
        {
            const deadline = clock.monotonicNs() + 20 * std.time.ns_per_s;
            var probe: usize = 0;
            while (true) : (probe += 1) {
                var script: [160]u8 = undefined;
                const r = try rig.sh(rig.work, try std.fmt.bufPrint(&script, "touch {s}/probe-{d}-{d} 2>&1 || true", .{ rig.mp, cycle, probe }));
                defer rig.freeRun(r);
                if (std.mem.indexOf(u8, r.stdout, "Input/output error") != null) break;
                if (!alive(pid) or clock.monotonicNs() >= deadline) {
                    const t = try rig.readLog();
                    defer gpa.free(t);
                    std.debug.print("\n--- cycle {d}: no EIO from a create under the error table (daemon alive: {}) — last answer: {s} ---\n{s}\n", .{ cycle, alive(pid), r.stdout, t[mark..] });
                    return error.NoFailStop;
                }
                sleepMs(20);
            }
        }
        // The storm keeps running against the FAILED volume (the window the
        // daemon died in): served, EIO, the mount standing.
        for (0..10) |_| {
            sleepMs(100);
            if (!alive(pid)) {
                const t = try rig.readLog();
                defer gpa.free(t);
                std.debug.print("\n--- cycle {d}: the daemon of a FAILED volume died with its mount in the table ---\n{s}\n", .{ cycle, t[mark..] });
                return error.FailedDaemonDied;
            }
            try testing.expectEqual(@as(usize, 1), try fuseMountsOf(gpa, io, rig.mp));
        }
        for (workers[0..spawned]) |*w| {
            if (w.id) |wp| _ = linux.kill(-wp, .KILL);
            _ = w.wait(io) catch {};
        }
        spawned = 0;
        // What the FAILED volume counted instead of logging.
        if (try rig.statsTry()) |st| {
            defer gpa.free(st);
            std.debug.print("\nsmoke[dm-error]: cycle {d}: counted {d} window write failure(s), {d} uncovered hole(s), {d} bset append failure(s), {d} node read failure(s) in {d} read-failure episode(s), {d} fsync leg(s), {d} syncfs leg(s), {d} block-map commit(s); {d} line(s) quieted", .{
                cycle,
                numberAfter(st, "\"journal_lane_write_failures\":") orelse 0,
                numberAfter(st, "\"meta_kv_journal_hole_checkpoint_failures\":") orelse 0,
                numberAfter(st, "\"bset_append_failures\":") orelse 0,
                numberAfter(st, "\"node_read_failures\":") orelse 0,
                numberAfter(st, "\"read_failure_episodes\":") orelse 0,
                numberAfter(st, "\"fsync_leg_failures\":") orelse 0,
                numberAfter(st, "\"syncfs_leg_failures\":") orelse 0,
                numberAfter(st, "\"layout_map_commit_failures\":") orelse 0,
                numberAfter(st, "\"meta_failed_volume_lines_quieted\":") orelse 0,
            });
        }
        {
            const r = try rig.squeezefs(&.{ "umount", rig.mp });
            defer rig.freeRun(r);
            if (!r.term.success() or std.mem.indexOf(u8, r.stderr, "no squeezefs daemon serves it") != null or std.mem.indexOf(u8, r.stderr, "died without unmounting") != null) {
                const t = try rig.readLog();
                defer gpa.free(t);
                std.debug.print("\n--- cycle {d}: umount of the FAILED mount ({f}): {s} ---\n{s}\n", .{ cycle, r.term, r.stderr, t[mark..] });
                return error.FailedUnmountNotOrderly;
            }
        }
        // The daemon's own exit, never a signal: 1 when a member latched
        // FAILED (named in its log), 0 when the cycle's failures were reads
        // and checkpoint writes alone (those retry; they never latch).
        const exit_i = try rig.awaitLog("exited (wait status 0x", mark, exit_wait_ns);
        {
            const t = try rig.readLog();
            defer gpa.free(t);
            const latched = std.mem.indexOf(u8, t[mark..exit_i], "latched FAILED during this mount (EIO until remount) — exiting 1") != null;
            if (!std.mem.startsWith(u8, t[exit_i..], if (latched) "100); done" else "0); done")) {
                std.debug.print("\n--- cycle {d}: the daemon's exit was not its own (latched FAILED: {}) ---\n{s}\n", .{ cycle, latched, t[mark..] });
                return error.FailedDaemonNotOwnExit;
            }
            if (latched) latched_cycles += 1;
            if (!failedVolumeLinesOnce(t[mark..exit_i], cycle)) lines_once = false;
        }
        try testing.expect(!alive(pid));
        try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
        {
            const r = try rig.squeezefs(&.{ "umount", rig.mp });
            defer rig.freeRun(r);
            try testing.expect(!r.term.success());
            if (std.mem.indexOf(u8, r.stderr, "not mounted") == null or std.mem.indexOf(u8, r.stderr, "no squeezefs daemon serves it") != null) {
                std.debug.print("\n--- cycle {d}: the second umount: {s} ---\n", .{ cycle, r.stderr });
                return error.SecondUmountMisjudged;
            }
        }
        try dm.load(false);
    }
    // The storm's acked mutations meet the error table in most cycles: the
    // row exercises the FAILED latch, not only failed reads.
    try testing.expect(latched_cycles >= 1);
    // The working table: the next mount replays what landed and serves the
    // storm's tree; a clean unmount; fsck clean.
    const mark = try rig.logLen();
    const pid = blk: {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, dm.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\nthe final mount: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
        const ready_i = try rig.awaitLog("ready: ", mark, ready_wait_ns);
        const text = try rig.readLog();
        defer gpa.free(text);
        break :blk @as(linux.pid_t, @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid));
    };
    {
        const out = try rig.onMount("n=$(find ./w* -type f | wc -l); test \"$n\" -gt 0; for f in w*/f*; do if test -e \"$f\"; then getfattr -d -m - \"$f\" >/dev/null; fi; done; echo \"$n files\"");
        defer gpa.free(out);
        std.debug.print("\nsmoke[dm-error]: {d} error-table cycles ({d} latched FAILED), each unmounted in order by the daemon's own exit; the working table's mount serves the tree: {s}", .{ dm_error_cycles, latched_cycles, out });
    }
    try umountDaemon(rig, pid);
    {
        const t = try rig.readLog();
        defer gpa.free(t);
        try testing.expect(std.mem.indexOf(u8, t[mark..], "exited (wait status 0x0); done") != null);
    }
    {
        const r = try rig.squeezefs(&.{ "fsck", "--offline", "--scrub", dm.meta_uri });
        defer rig.freeRun(r);
        if (!r.term.success() or std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") == null) {
            std.debug.print("\n--- fsck --offline after the dm-error cycles ({f}) ---\n{s}\n--- stderr ---\n{s}\n", .{ r.term, r.stdout, r.stderr });
            return error.FsckNotClean;
        }
    }
    // The one-line law: no failure class logged twice on a FAILED volume.
    try testing.expect(lines_once);
}

/// Who replays a held journal tail once the device answers again: the
/// supervisor's own retry, or — the supervisor gone — the volume's next
/// mount, from the held copy.
const HeldTailArm = enum { supervisor_retry, successor };

test "smoke: A FAILED REPLAY'S JOURNAL TAIL IS HELD, NEVER DISCARDED (charter §5.2, decision 0003 §BR) — a `--daemon --supervise` set over one device-mapper device, under the landing-hold seam, acks creates whose journal writes never issue; the table flips to `error`; kill -9: the supervisor's replay FAILS and the tail is HELD (its copy under the held dir before the guard drops); (a) the supervisor alive, the table restored: its retry lands the tail, removes the copy and exits — the next mount reads every acked create; (b) the supervisor KILLED with the tail held: the copy stays, the table restored, the next mount replays it before it admits writes (`held_tail_replays` 1) — every acked create present, the copy gone; fsck clean after each (red on 885727b: `replay FAILED (…) — acked metadata of the flush window may be lost`, the tail discarded, the creates gone after the device recovered)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    if (DmErrorSet.venueMissing()) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    var dm = try DmErrorSet.up(rig);
    defer dm.deinit();
    if (rig.log_file == null) rig.log_file = try openLogAppend(rig.log_path);
    {
        const r = try rig.squeezefs(&.{ "format", dm.meta_uri, dm.data_uri });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\nformat: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    }
    var dir_buf: [linux.PATH_MAX]u8 = undefined;
    const held_dir = try std.fmt.bufPrint(&dir_buf, "{s}/held-tails", .{rig.work});
    try rig.env.put("SQUEEZEFS_TEST_JOURNAL_TAIL_DIR", held_dir);
    // The retry's cadence: a quarter second, not a watchdog tick.
    try rig.env.put("SQUEEZEFS_TEST_SUPERVISOR_PROBE_MS", "250");
    // Nothing ever lands to end a §L hold.
    try rig.env.put("SQUEEZEFS_META_WINDOW_HOLD", "none");
    for ([_]HeldTailArm{ .supervisor_retry, .successor }) |arm| {
        try rig.env.put("SQUEEZEFS_TEST_JOURNAL_HOLD_LANDING", "1");
        const mark = try rig.logLen();
        const pid = blk: {
            const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, dm.meta_uri, rig.mp });
            defer rig.freeRun(r);
            if (!r.term.success()) std.debug.print("\n{t}: daemon mount: {s}\n", .{ arm, r.stderr });
            try testing.expect(r.term.success());
            const ready_i = try rig.awaitLog("ready: ", mark, ready_wait_ns);
            const text = try rig.readLog();
            defer gpa.free(text);
            break :blk @as(linux.pid_t, @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid));
        };
        const sup = ppidOf(pid) orelse return error.NoSupervisor;
        var daemon_live = true;
        defer if (daemon_live) {
            _ = linux.kill(pid, .KILL);
        };
        _ = try rig.awaitLog("supervisor: watching daemon ", mark, ready_wait_ns);
        var script: [256]u8 = undefined;
        {
            const out = try rig.shOk(rig.mp, try std.fmt.bufPrint(&script, "mkdir {t} && touch {t}/a {t}/b && echo hello > {t}/c && test -e {t}/a && echo ok", .{ arm, arm, arm, arm, arm }));
            defer gpa.free(out);
        }
        // Acked, never landed; the device fails; the daemon dies.
        try dm.load(true);
        daemon_live = false;
        _ = linux.kill(pid, .KILL);
        const failed_i = try rig.awaitLog("replay FAILED", mark, 20 * std.time.ns_per_s);
        _ = try rig.awaitLog("); done", failed_i, 20 * std.time.ns_per_s);
        try rig.umountAfterKill();
        _ = rig.env.swapRemove("SQUEEZEFS_TEST_JOURNAL_HOLD_LANDING");
        var copy_held = false;
        switch (arm) {
            .supervisor_retry => {
                try dm.load(false);
                const deadline = clock.monotonicNs() + 30 * std.time.ns_per_s;
                while (alive(sup) and clock.monotonicNs() < deadline) sleepMs(20);
                try testing.expect(!alive(sup));
            },
            .successor => {
                _ = linux.kill(sup, .KILL);
                const deadline = clock.monotonicNs() + 10 * std.time.ns_per_s;
                while (alive(sup) and clock.monotonicNs() < deadline) sleepMs(20);
                try testing.expect(!alive(sup));
                const ls = try rig.shOk(rig.work, try std.fmt.bufPrint(&script, "ls {s} 2>/dev/null | grep -c '\\.jtail$' || true", .{held_dir}));
                defer gpa.free(ls);
                copy_held = std.mem.eql(u8, std.mem.trim(u8, ls, " \n"), "1");
                try dm.load(false);
            },
        }
        // The next mount: every acked create present.
        const mark2 = try rig.logLen();
        const pid2 = blk: {
            const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, dm.meta_uri, rig.mp });
            defer rig.freeRun(r);
            if (!r.term.success()) {
                const t = try rig.readLog();
                defer gpa.free(t);
                std.debug.print("\n{t}: the next mount: {s}\n--- its log ---\n{s}\n", .{ arm, r.stderr, t[@min(mark, t.len)..] });
                return error.MountFailed;
            }
            const ready_i = try rig.awaitLog("ready: ", mark2, ready_wait_ns);
            const text = try rig.readLog();
            defer gpa.free(text);
            break :blk @as(linux.pid_t, @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid));
        };
        {
            const out = try rig.shOk(rig.mp, try std.fmt.bufPrint(&script, "if test -e {t}/a && test -e {t}/b && test \"$(cat {t}/c 2>/dev/null)\" = hello; then echo present; else echo lost; fi", .{ arm, arm, arm }));
            defer gpa.free(out);
            const t = try rig.readLog();
            defer gpa.free(t);
            const line_at = std.mem.indexOf(u8, t[mark..], "replay FAILED").? + mark;
            const line = t[line_at..];
            std.debug.print("\nsmoke[held tail, {t}]: …{s}\nsmoke[held tail, {t}]: the acked creates after the device recovered: {s}", .{ arm, line[0 .. std.mem.indexOfScalar(u8, line, '\n') orelse line.len], arm, out });
            if (std.mem.indexOf(u8, out, "present") == null) {
                std.debug.print("--- the log since the arm's mount ---\n{s}\n", .{t[mark..]});
                return error.AckedMetadataLost;
            }
        }
        switch (arm) {
            .supervisor_retry => {
                const t = try rig.readLog();
                defer gpa.free(t);
                try testing.expect(std.mem.indexOf(u8, t[mark..mark2], "replayed on retry") != null);
            },
            .successor => {
                try testing.expect(copy_held);
                const st = try rig.stats();
                defer gpa.free(st);
                try testing.expectEqual(@as(?u64, 1), numberAfter(st, "\"held_tail_replays\":"));
            },
        }
        {
            const ls = try rig.shOk(rig.work, try std.fmt.bufPrint(&script, "ls {s} 2>/dev/null | grep -c '\\.jtail$' || true", .{held_dir}));
            defer gpa.free(ls);
            try testing.expectEqualStrings("0", std.mem.trim(u8, ls, " \n"));
        }
        try umountDaemon(rig, pid2);
        {
            const r = try rig.squeezefs(&.{ "fsck", "--offline", "--scrub", dm.meta_uri });
            defer rig.freeRun(r);
            if (!r.term.success() or std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") == null) {
                std.debug.print("\n--- fsck --offline after the held tail ({t}) ({f}) ---\n{s}\n--- stderr ---\n{s}\n", .{ arm, r.term, r.stdout, r.stderr });
                return error.FsckNotClean;
            }
        }
    }
}

/// The custody row's residents: `custody_files` × 256 KiB, staged whole.
const custody_files: usize = 4;
const custody_file_bytes: usize = 256 << 10;

test "smoke: A SUPERVISOR HOLDING CUSTODY IS NEVER THE DAEMON (charter §4, decision 0003 §BR.7) — a `--daemon --supervise` set over one device-mapper device: 4 files of 256 KiB staged in the write cache (closed, never synced; the directory fsync'd, so their staged layouts are durable), the table flips to `error`, a create answers EIO (FAILED); `squeezefs umount` exits 0 and the daemon exits 1 by itself — its supervisor holds the ring (residents unpromoted); a SECOND `squeezefs umount` of the path answers `not mounted` and signals nobody, the supervisor still holding; the working table back, the next supervised mount takes the ring and every file reads byte-exact (staged_payload_lost_reads 0); the supervisor exits; fsck clean (red on origin/dev: the second umount took the childless supervisor for the daemon and signalled it — the ring died with it)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    if (DmErrorSet.venueMissing()) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    var dm = try DmErrorSet.up(rig);
    defer dm.deinit();
    if (rig.log_file == null) rig.log_file = try openLogAppend(rig.log_path);
    {
        const r = try rig.squeezefs(&.{ "format", dm.meta_uri, dm.data_uri });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\nformat: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    }
    var dir_buf: [linux.PATH_MAX]u8 = undefined;
    try rig.env.put("SQUEEZEFS_TEST_JOURNAL_TAIL_DIR", try std.fmt.bufPrint(&dir_buf, "{s}/held-tails", .{rig.work}));
    var script: [512]u8 = undefined;
    gpa.free(try rig.shOk(rig.work, try std.fmt.bufPrint(&script, "i=0; while [ $i -lt {d} ]; do head -c {d} /dev/urandom > src$i; i=$((i + 1)); done; echo ok", .{ custody_files, custody_file_bytes })));
    const mark = try rig.logLen();
    const pid = blk: {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, dm.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\ndaemon mount: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
        const ready_i = try rig.awaitLog("ready: ", mark, ready_wait_ns);
        const text = try rig.readLog();
        defer gpa.free(text);
        break :blk @as(linux.pid_t, @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid));
    };
    const sup = ppidOf(pid) orelse return error.NoSupervisor;
    defer if (alive(sup)) {
        _ = linux.kill(sup, .KILL);
    };
    var daemon_live = true;
    defer if (daemon_live) {
        _ = linux.kill(pid, .KILL);
    };
    _ = try rig.awaitLog("supervisor: watching daemon ", mark, ready_wait_ns);
    // Staged whole, the layouts durable (the directory's fsync), the
    // residents in the ring: no file is synced.
    gpa.free(try rig.onMount(try std.fmt.bufPrint(&script, "i=0; while [ $i -lt {d} ]; do cp \"$1/src$i\" f$i; i=$((i + 1)); done; python3 -c 'import os; fd = os.open(\".\", os.O_RDONLY); os.fsync(fd)' && echo ok", .{custody_files})));
    {
        const st = try rig.stats();
        defer gpa.free(st);
        try testing.expectEqual(@as(?u64, 1), numberAfter(st, "\"data_staging_on\":"));
    }
    // The device fails; a create latches the volume FAILED.
    try dm.load(true);
    {
        const deadline = clock.monotonicNs() + 20 * std.time.ns_per_s;
        var probe: usize = 0;
        while (true) : (probe += 1) {
            var pb: [160]u8 = undefined;
            const r = try rig.sh(rig.work, try std.fmt.bufPrint(&pb, "touch {s}/probe-{d} 2>&1 || true", .{ rig.mp, probe }));
            defer rig.freeRun(r);
            if (std.mem.indexOf(u8, r.stdout, "Input/output error") != null) break;
            if (!alive(pid) or clock.monotonicNs() >= deadline) return error.NoFailStop;
            sleepMs(20);
        }
    }
    // The first umount: the daemon's own exit, 1 (FAILED).
    {
        const r = try rig.squeezefs(&.{ "umount", rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\nthe first umount ({f}): {s}\n", .{ r.term, r.stderr });
        try testing.expect(r.term.success());
    }
    var nb: [64]u8 = undefined;
    const exit_i = try rig.awaitLog(try std.fmt.bufPrint(&nb, "daemon {d} exited (wait status 0x", .{pid}), mark, exit_wait_ns);
    daemon_live = false;
    const hold_i = try rig.awaitLog("supervisor: holding the dead daemon's write cache", exit_i, 30 * std.time.ns_per_s);
    // The second umount: no daemon serves the path.
    const second = blk: {
        const r = try rig.squeezefs(&.{ "umount", rig.mp });
        defer rig.freeRun(r);
        std.debug.print("\nsmoke[custody]: the second umount: {f}: {s}", .{ r.term, r.stderr });
        break :blk !r.term.success() and std.mem.indexOf(u8, r.stderr, "not mounted") != null;
    };
    // A TERM the verb sent would end the seat within its own exit wait.
    sleepMs(200);
    const held_after = alive(sup);
    try dm.load(false);
    // The next supervised mount takes the ring.
    const mark2 = try rig.logLen();
    const pid2 = blk: {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, dm.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) {
            const t = try rig.readLog();
            defer gpa.free(t);
            std.debug.print("\nthe next mount: {s}\n--- its log ---\n{s}\n", .{ r.stderr, t[@min(mark2, t.len)..] });
            return error.MountFailed;
        }
        const ready_i = try rig.awaitLog("ready: ", mark2, ready_wait_ns);
        const text = try rig.readLog();
        defer gpa.free(text);
        break :blk @as(linux.pid_t, @intCast(numberAfter(text[ready_i..], "(pid ") orelse return error.NoPid));
    };
    const exact = blk: {
        const out = try rig.onMount(try std.fmt.bufPrint(&script, "n=0; i=0; while [ $i -lt {d} ]; do if cmp -s \"$1/src$i\" f$i; then n=$((n + 1)); fi; i=$((i + 1)); done; echo $n", .{custody_files}));
        defer gpa.free(out);
        break :blk std.fmt.parseInt(usize, std.mem.trim(u8, out, " \n"), 10) catch 0;
    };
    const lost = try stagedLostReads(rig);
    {
        const t = try rig.readLog();
        defer gpa.free(t);
        const wc_at = std.mem.indexOf(u8, t[mark2..], " in a sealed memfd ");
        std.debug.print("smoke[custody]: the supervisor {s} after the second umount; the next mount's write cache recovered {?d} record(s); {d} of {d} files byte-exact, staged_payload_lost_reads {d}\n", .{ if (held_after) "still holding" else "GONE", if (wc_at) |a| numberAfter(t[mark2 + a ..], "recovered ") else null, exact, custody_files, lost });
        _ = hold_i;
    }
    try testing.expect(second);
    try testing.expect(held_after);
    try testing.expectEqual(custody_files, exact);
    try testing.expectEqual(@as(u64, 0), lost);
    {
        const deadline = clock.monotonicNs() + 30 * std.time.ns_per_s;
        while (alive(sup) and clock.monotonicNs() < deadline) sleepMs(20);
        try testing.expect(!alive(sup));
    }
    try umountDaemon(rig, pid2);
    {
        const r = try rig.squeezefs(&.{ "fsck", "--offline", "--scrub", dm.meta_uri });
        defer rig.freeRun(r);
        if (!r.term.success() or std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") == null) {
            std.debug.print("\n--- fsck --offline after the custody row ({f}) ---\n{s}\n--- stderr ---\n{s}\n", .{ r.term, r.stdout, r.stderr });
            return error.FsckNotClean;
        }
    }
}

/// A process whose cwd is the mount (the holder of the busy-umount rows):
/// `sleep` parks with the mount root as its cwd until killed.
const Holder = struct {
    child: std.process.Child,
    pid: linux.pid_t,
    gone: bool = false,

    fn spawn(rig: *Rig) !Holder {
        const c = try std.process.spawn(rig.io, .{ .argv = &.{ "sleep", "300" }, .cwd = .{ .path = rig.mp }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore });
        return .{ .child = c, .pid = c.id.? };
    }

    /// Kill and reap (idempotent: the row's `defer` meets an already-gone holder).
    fn kill(self: *Holder, io: Io) void {
        if (self.gone) return;
        self.gone = true;
        _ = linux.kill(self.pid, .KILL);
        _ = self.child.wait(io) catch {};
    }
};

/// The supervisor's verdict lines after `from`: none of the escalation
/// ladder may appear on an orderly cycle (charter §1.1: a daemon is never
/// "unresponsive" for being asked to unmount).
fn expectSupervisorSilent(text: []const u8) !void {
    inline for (.{ "missed a probe", "heartbeat stale", "unresponsive for", "is dead (wait status", "detaching lazily" }) |needle| {
        if (std.mem.indexOf(u8, text, needle)) |i| {
            std.debug.print("\n--- the supervisor/transport fired on an orderly cycle: '{s}' ---\n{s}\n", .{ needle, text[i..@min(text.len, i + 400)] });
            return error.SupervisorFired;
        }
    }
}

test "smoke: umount of a BUSY mount (another process's cwd inside it) — the verb REFUSES loud within a tick naming the holder's pid (EBUSY, exit 1), the daemon keeps serving (stat, a write), nothing detaches, the supervisor stays silent; a bare SIGTERM is refused the same way (counted in .stats); after the holder leaves the next umount is the clean one (`clean unmount`, `exited (wait status 0x0)`)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, "-o", "default_permissions,allow_other", rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\ndaemon mount: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    }
    const text0 = try rig.readLog();
    defer gpa.free(text0);
    const ready_i = std.mem.indexOf(u8, text0, "ready: ") orelse return error.NoReadyLine;
    const pid: linux.pid_t = @intCast(numberAfter(text0[ready_i..], "(pid ") orelse return error.NoPid);
    _ = try rig.awaitLog("supervisor: watching daemon ", ready_i, ready_wait_ns);
    {
        const out = try rig.shOk(rig.mp, "echo before > f && test \"$(cat f)\" = before");
        defer gpa.free(out);
    }
    var holder = try Holder.spawn(rig);
    defer holder.kill(io);
    // The holder's cwd is the mount root: readable through /proc.
    {
        var pb: [64:0]u8 = undefined;
        var lb: [linux.PATH_MAX]u8 = undefined;
        const link = try std.fmt.bufPrintSentinel(&pb, "/proc/{d}/cwd", .{holder.pid}, 0);
        const rc = linux.readlink(link.ptr, &lb, lb.len);
        try testing.expectEqual(linux.E.SUCCESS, linux.errno(rc));
        try testing.expectEqualStrings(rig.mp, lb[0..rc]);
    }
    var pid_text: [16]u8 = undefined;
    const pid_s = try std.fmt.bufPrint(&pid_text, "{d}", .{holder.pid});
    // 1. The verb refuses: EBUSY within one lock-plane tick, the holder
    //    named, exit 1 — never 0, never 29 s, never a dead daemon.
    {
        const t0 = clock.monotonicNs();
        const r = try rig.squeezefs(&.{ "umount", rig.mp });
        defer rig.freeRun(r);
        const took_ms = (clock.monotonicNs() - t0) / std.time.ns_per_ms;
        if (r.term.success() or took_ms > 5000) std.debug.print("\n--- umount of the busy mount: rc {f} after {d} ms (expected exit 1 within a tick); stderr:\n{s}\n", .{ r.term, took_ms, r.stderr });
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(took_ms <= 5000);
        if (std.mem.indexOf(u8, r.stderr, "busy") == null or std.mem.indexOf(u8, r.stderr, pid_s) == null) std.debug.print("\n--- the refusal did not name the holder {d}:\n{s}\n", .{ holder.pid, r.stderr });
        try testing.expect(std.mem.indexOf(u8, r.stderr, "busy") != null);
        try testing.expect(std.mem.indexOf(u8, r.stderr, pid_s) != null);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "cwd") != null);
    }
    // The daemon is alive and the mount serves: the control inode answers
    // and a write lands.
    try testing.expect(alive(pid));
    try testing.expectEqual(@as(usize, 1), try fuseMountsOf(gpa, io, rig.mp));
    {
        const out = try rig.shOk(rig.mp, "test -s .stats && echo during > g && test \"$(cat g)\" = during && test \"$(cat f)\" = before");
        defer gpa.free(out);
    }
    // 2. A bare SIGTERM (an operator's `kill`) meets the daemon's own
    //    census: refused, logged, counted; the mount keeps serving.
    {
        const mark = try rig.logLen();
        _ = linux.kill(pid, .TERM);
        _ = try rig.awaitLog("is busy", mark, 10 * std.time.ns_per_s);
        try testing.expect(alive(pid));
        const out = try rig.shOk(rig.mp, "test \"$(cat g)\" = during");
        defer gpa.free(out);
        const st = try rig.stats();
        defer gpa.free(st);
        try testing.expectEqual(@as(?u64, 1), numberAfter(st, "\"transport_umount_busy_refusals\":"));
    }
    {
        const during = try rig.readLog();
        defer gpa.free(during);
        try expectSupervisorSilent(during[ready_i..]);
        try testing.expect(std.mem.indexOf(u8, during[ready_i..], "stop requested") != null);
    }
    // 3. The holder leaves; the orderly unmount is the clean one.
    holder.kill(io);
    {
        const t0 = clock.monotonicNs();
        const r = try rig.squeezefs(&.{ "umount", rig.mp });
        defer rig.freeRun(r);
        const took_ms = (clock.monotonicNs() - t0) / std.time.ns_per_ms;
        if (!r.term.success()) std.debug.print("\n--- the clean umount failed ({f}) after {d} ms:\n{s}\n", .{ r.term, took_ms, r.stderr });
        try testing.expect(r.term.success());
        try testing.expect(took_ms <= 20_000);
    }
    {
        const deadline = clock.monotonicNs() + exit_wait_ns;
        while (alive(pid) and clock.monotonicNs() < deadline) sleepMs(20);
        try testing.expect(!alive(pid));
    }
    _ = try rig.awaitLog("exited (wait status 0x0); done", ready_i, 20 * std.time.ns_per_s);
    const after = try rig.readLog();
    defer gpa.free(after);
    try testing.expect(std.mem.indexOf(u8, after[ready_i..], "clean unmount") != null);
    try expectSupervisorSilent(after[ready_i..]);
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    try testing.expect(!status_verb.writerGuardHeld(testing.io, rig.img));
}

test "smoke: the stop's own sender reading `.stats` is no holder — a process opens `<mp>/.stats` and SIGTERMs the daemon with the fd open (what `squeezefs umount` does: its verdict poll opens `.stats` on its signal's heels — the matrix row's `is busy (0 holder(s))`): the daemon's census exempts the sender's control-document fds and unmounts — never `is busy`, never the lazy detach — and exits 0" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try rig.spawnMount(&.{});
    const ready = try rig.awaitReady(0);
    const stats_path = try std.fmt.allocPrintSentinel(gpa, "{s}/.stats", .{rig.mp}, 0);
    defer gpa.free(stats_path);
    var opened: [2]linux.fd_t = undefined;
    var go: [2]linux.fd_t = undefined;
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.pipe2(&opened, .{ .CLOEXEC = true })));
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.pipe2(&go, .{ .CLOEXEC = true })));
    const daemon_pid = rig.child_pid;
    const rc = linux.fork();
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(rc));
    if (rc == 0) {
        // The sender, dumpable so the daemon's census can read its fds (a
        // hardened test process is not): `.stats` open across its own
        // SIGTERM until the parent says go.
        _ = linux.close(opened[0]);
        _ = linux.close(go[1]);
        _ = linux.prctl(@backingInt(linux.PR.SET_DUMPABLE), 1, 0, 0, 0);
        const fd_rc = linux.open(stats_path.ptr, .{ .ACCMODE = .RDONLY, .CLOEXEC = true }, 0);
        if (linux.errno(fd_rc) != .SUCCESS) linux.exit(2);
        _ = linux.kill(daemon_pid, .TERM);
        var one: u8 = 1;
        _ = linux.write(opened[1], @ptrCast(&one), 1);
        _ = linux.read(go[0], @ptrCast(&one), 1);
        _ = linux.close(@intCast(fd_rc));
        linux.exit(0);
    }
    const sender: linux.pid_t = @intCast(rc);
    _ = linux.close(opened[1]);
    _ = linux.close(go[0]);
    var byte: u8 = 0;
    _ = linux.read(opened[0], @ptrCast(&byte), 1);
    _ = linux.close(opened[0]);
    // The daemon logs its verdict after its census; the sender closes then.
    const verdict = rig.awaitLog("stop requested", ready, 10 * std.time.ns_per_s);
    _ = linux.close(go[1]);
    var status: i32 = 0;
    _ = linux.waitpid(sender, &status, 0);
    _ = try verdict;
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        if (std.mem.indexOf(u8, text[ready..], "is busy")) |i| std.debug.print("\n--- the daemon refused its own sender's stop ---\n{s}\n", .{text[ready + i - @min(i, 120) .. @min(text.len, ready + i + 300)]});
        try testing.expect(std.mem.indexOf(u8, text[ready..], "is busy") == null);
    }
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    const after = try rig.readLog();
    defer gpa.free(after);
    try testing.expect(std.mem.indexOf(u8, after[ready..], "unmounting") != null);
    try testing.expect(std.mem.indexOf(u8, after[ready..], "detaching lazily") == null);
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
}

/// The reads a holder completed on its cwd (`<work>/count`), 0 before its
/// first.
fn holderCount(rig: *Rig) u64 {
    var pb: [192]u8 = undefined;
    var buf: [32]u8 = undefined;
    const path = std.fmt.bufPrint(&pb, "{s}/count", .{rig.work}) catch return 0;
    const text = Io.Dir.cwd().readFile(rig.io, path, &buf) catch return 0;
    return std.fmt.parseInt(u64, std.mem.trim(u8, text, " \n"), 10) catch 0;
}

/// Bounded poll until the holder's count passes `floor`.
fn awaitHolderReads(rig: *Rig, floor: u64, deadline_ns: u64) !u64 {
    const deadline = clock.monotonicNs() + deadline_ns;
    while (true) {
        const n = holderCount(rig);
        if (n > floor) return n;
        if (clock.monotonicNs() >= deadline) {
            std.debug.print("\n--- the holder made no progress past {d} reads ---\n", .{floor});
            return error.Timeout;
        }
        sleepMs(20);
    }
}

test "smoke: `umount --lazy` of a BUSY mount — the verb returns at once naming the holders it leaves, the mountpoint is gone from the table, the holder KEEPS reading its detached cwd (every ls and .stats served), the supervisor switches to the heartbeat and never warns; when the holder leaves the kernel ends the connection and the daemon tears down clean (`exited (wait status 0x0)`); `--lazy` on an unheld mount is the orderly stop" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    // The supervisor looks every quarter second (the probe seam): step 3's
    // switch to the heartbeat lands at its first look past the detach,
    // never after up to three 5 s intervals.
    try rig.env.put("SQUEEZEFS_TEST_SUPERVISOR_PROBE_MS", "250");
    {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, "-o", "default_permissions,allow_other", rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\ndaemon mount: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    }
    const text0 = try rig.readLog();
    defer gpa.free(text0);
    const ready_i = std.mem.indexOf(u8, text0, "ready: ") orelse return error.NoReadyLine;
    const pid: linux.pid_t = @intCast(numberAfter(text0[ready_i..], "(pid ") orelse return error.NoPid);
    _ = try rig.awaitLog("supervisor: watching daemon ", ready_i, ready_wait_ns);
    // The holder: cwd = the mount root, reading it (ls + the control
    // inode) until the stop file appears OUTSIDE the mount; its count of
    // served reads lands beside the stop file.
    var script: [512]u8 = undefined;
    // `-d work` too: a row that fails before the stop file leaves no
    // holder spinning on a deleted work dir.
    const holder_script = try std.fmt.bufPrint(&script, "n=0; while [ -d {s} ] && [ ! -e {s}/stop ]; do ls . >/dev/null || exit 2; cat .stats >/dev/null || exit 3; n=$((n+1)); echo $n > {s}/count; sleep 0.05; done; exit 0", .{ rig.work, rig.work, rig.work });
    var holder = try std.process.spawn(io, .{ .argv = &.{ "sh", "-c", holder_script }, .cwd = .{ .path = rig.mp }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .ignore, .stderr = .inherit });
    const holder_pid = holder.id.?;
    var stop_buf: [192]u8 = undefined;
    const stop_path = try std.fmt.bufPrint(&stop_buf, "{s}/stop", .{rig.work});
    defer Io.Dir.cwd().writeFile(io, .{ .sub_path = stop_path, .data = "" }) catch {};
    const before = try awaitHolderReads(rig, 0, 10 * std.time.ns_per_s);
    var pid_text: [16]u8 = undefined;
    const pid_s = try std.fmt.bufPrint(&pid_text, "{d}", .{holder_pid});
    // 1. The lazy detach: at once, the holder named, the path free.
    const lazy_mark = try rig.logLen();
    {
        const t0 = clock.monotonicNs();
        const r = try rig.squeezefs(&.{ "umount", "--lazy", rig.mp });
        defer rig.freeRun(r);
        const took_ms = (clock.monotonicNs() - t0) / std.time.ns_per_ms;
        const named = std.mem.indexOf(u8, r.stdout, "detached") != null and std.mem.indexOf(u8, r.stdout, pid_s) != null;
        // The daemon's log says which way its census went (the holder found
        // and the detach, or "unmounting": the orderly stop over a holder
        // the census missed, whose teardown ends the connection under it).
        if (!r.term.success() or took_ms > 5000 or !named) {
            const since = try rig.readLog();
            defer gpa.free(since);
            std.debug.print("\n--- umount --lazy: rc {f} after {d} ms; stdout:\n{s}\nstderr:\n{s}\n--- the daemon's log since the signal ---\n{s}\n", .{ r.term, took_ms, r.stdout, r.stderr, since[@min(lazy_mark, since.len)..] });
        }
        try testing.expect(r.term.success());
        try testing.expect(took_ms <= 5000);
        try testing.expect(named);
    }
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    try testing.expect(alive(pid));
    _ = try rig.awaitLog("detached lazily with", lazy_mark, 10 * std.time.ns_per_s);
    // 2. The holder keeps being served on the detached superblock.
    const after_detach = try awaitHolderReads(rig, before + 10, 20 * std.time.ns_per_s);
    try testing.expect(after_detach > before);
    // 3. The supervisor notices the detach, switches probes, stays silent.
    _ = try rig.awaitLog("is no longer attached", lazy_mark, 3 * cli_supervisor.PROBE_INTERVAL_NS);
    _ = try awaitHolderReads(rig, after_detach, 20 * std.time.ns_per_s);
    try testing.expect(alive(pid));
    {
        const during = try rig.readLog();
        defer gpa.free(during);
        try expectSupervisorSilent(during[ready_i..]);
    }
    // 4. The holder leaves: the kernel ends the connection, the daemon
    //    tears down clean, the supervisor reaps 0x0.
    try Io.Dir.cwd().writeFile(io, .{ .sub_path = stop_path, .data = "" });
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try holder.wait(io));
    _ = try rig.awaitLog("the FUSE session ended (unmounted): tearing down", lazy_mark, 20 * std.time.ns_per_s);
    _ = try rig.awaitLog("exited (wait status 0x0); done", lazy_mark, 20 * std.time.ns_per_s);
    try testing.expect(!alive(pid));
    {
        const after = try rig.readLog();
        defer gpa.free(after);
        try testing.expect(std.mem.indexOf(u8, after[lazy_mark..], "clean unmount") != null);
        try expectSupervisorSilent(after[ready_i..]);
    }
    try testing.expect(!status_verb.writerGuardHeld(testing.io, rig.img));
    // 5. `--lazy` on an unheld mount: the orderly stop, nothing lazy.
    Io.Dir.cwd().deleteFile(io, stop_path) catch {};
    const mark2 = try rig.logLen();
    {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        try testing.expect(r.term.success());
    }
    const ready2 = try rig.awaitReady(mark2);
    {
        const r = try rig.squeezefs(&.{ "umount", "-l", rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) {
            const text = try rig.readLog();
            defer gpa.free(text);
            std.debug.print("\n--- umount -l (unheld): {f}\n{s}\n--- the daemon's log since the remount ---\n{s}\n", .{ r.term, r.stderr, text[@min(ready2, text.len)..] });
        }
        try testing.expect(r.term.success());
    }
    _ = try rig.awaitLog("lazy stop requested (SIGUSR2): unmounting", ready2, 10 * std.time.ns_per_s);
    _ = try rig.awaitLog("exited (wait status 0x0); done", ready2, 20 * std.time.ns_per_s);
    const final = try rig.readLog();
    defer gpa.free(final);
    try testing.expect(std.mem.indexOf(u8, final[ready2..], "clean unmount") != null);
    try testing.expect(std.mem.indexOf(u8, final[ready2..], "detached lazily") == null);
    try expectSupervisorSilent(final[ready2..]);
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
}

test "smoke: `umount --lazy`'s verdict under MOUNT-ID CHURN — the kernel reissues the mount id the daemon's own unmount frees to the next mount on the host; with every lower id held and a tmpfs mounted and lazily unmounted every few ms behind a 100 ms holder, the freed id lands on a HELD mount inside the verb's poll: the verb still reports the orderly exit (red: `daemon … died without unmounting` on a clean cycle — the gate's parallel shards)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    try rig.env.put("SQUEEZEFS_TEST_SUPERVISOR_PROBE_MS", "250");
    var cb: [192]u8 = undefined;
    const churn_dir = try std.fmt.bufPrint(&cb, "{s}/churn", .{rig.work});
    try Io.Dir.cwd().createDirPath(io, churn_dir);
    // The churn (its own session, so one signal to the group ends every
    // sleep): a tmpfs mounted, lazily unmounted at once behind a 300 s
    // holder (a sleep's cwd — no id it takes is freed during the row),
    // back to back while the id it gets is a HOLE below the frontier
    // (every id the host frees, ours among them, is taken within one
    // iteration), and every 10 ms once at the frontier. The row's FUSE
    // mount is made once the holes are filled, so the id its unmount frees
    // is a hole: the next churn mount's, held for the rest of the row.
    var script: [1024]u8 = undefined;
    const churn_script = try std.fmt.bufPrint(&script, "d={s}; F=$(awk '{{ if ($1 + 0 > m) m = $1 + 0 }} END {{ print m }}' /proc/self/mountinfo); k=0; ready=0; while [ ! -e {s}/stop ]; do mount -t tmpfs none $d 2>/dev/null || {{ sleep 0.01; continue; }}; id=$(awk -v mp=$d '$5 == mp {{ i = $1 }} END {{ print i }}' /proc/self/mountinfo); (cd $d && sleep 300) & umount -l $d 2>/dev/null; k=$((k+1)); [ $k -gt 20000 ] && exit 3; if [ \"$id\" -gt \"$F\" ]; then F=$id; [ $ready = 1 ] || {{ ready=1; touch {s}/churn-ready; }}; sleep 0.01; fi; done; exit 0", .{ churn_dir, rig.work, rig.work });
    var churn = try std.process.spawn(io, .{ .argv = &.{ "setsid", "sh", "-c", churn_script }, .cwd = .{ .path = rig.work }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .ignore, .stderr = .inherit });
    const churn_pid = churn.id.?;
    var stop_buf: [192]u8 = undefined;
    const stop_path = try std.fmt.bufPrint(&stop_buf, "{s}/stop", .{rig.work});
    defer {
        Io.Dir.cwd().writeFile(io, .{ .sub_path = stop_path, .data = "" }) catch {};
        _ = linux.kill(-churn_pid, .TERM);
        _ = churn.wait(io) catch {};
        var zb: [192:0]u8 = undefined;
        if (std.fmt.bufPrintSentinel(&zb, "{s}", .{churn_dir}, 0)) |z| {
            _ = linux.umount2(z.ptr, linux.MNT.DETACH);
        } else |_| {}
    }
    var ready_buf: [192]u8 = undefined;
    const ready_path = try std.fmt.bufPrint(&ready_buf, "{s}/churn-ready", .{rig.work});
    {
        const t0 = clock.monotonicNs();
        while (true) {
            if (Io.Dir.cwd().access(io, ready_path, .{})) |_| break else |_| {}
            if (clock.monotonicNs() - t0 > 60 * std.time.ns_per_s) return error.ChurnNotReady;
            try std.Thread.yield();
        }
    }
    {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        try testing.expect(r.term.success());
    }
    const ready = try rig.awaitReady(0);
    {
        const r = try rig.squeezefs(&.{ "umount", "-l", rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) {
            const text = try rig.readLog();
            defer gpa.free(text);
            std.debug.print("\n--- umount -l under mount-id churn: {f}\n{s}\n--- the daemon's log ---\n{s}\n", .{ r.term, r.stderr, text[@min(ready, text.len)..] });
        }
        try testing.expect(r.term.success());
        try testing.expect(std.mem.indexOf(u8, r.stderr, "died") == null);
    }
    _ = try rig.awaitLog("exited (wait status 0x0); done", ready, 20 * std.time.ns_per_s);
    const final = try rig.readLog();
    defer gpa.free(final);
    try testing.expect(std.mem.indexOf(u8, final[ready..], "clean unmount") != null);
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
}

test "smoke: a LATE bring-up refusal — the kmbuf ring answers ENOMEM (the seam) after the data plane registered its budget sources: the daemon exits 1 (never a signal) with the typed refusal naming the region's pages and the levers that shrink it, nothing stays mounted or held, and the R5 sampler, ticking at its stop under its seam, reads no freed source; a clean mount → umount under the same sampler seam exits 0" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    // The registration is reached only where the probe confirmed kmbuf.
    if (transport.probes.driver.probeKmbuf(@intCast(derive.facts().page_size)).opcodes() == null) return testkit.skip(@src(), .no_kernel_feature, "no kmbuf register opcode on this kernel");
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    // The sampler's stop runs one tick over every registered source: a
    // teardown that frees a source before stopping the sampler dies on the
    // read (`samplerMain → current` over the freed plane: a fault or a
    // safety panic) instead of racing the 1 Hz tick.
    try rig.env.put("SQUEEZEFS_TEST_MEM_SAMPLER_TICK_ON_STOP", "1");
    // 1. The refusal: the plane is open (its tiers and pools registered)
    //    when the session's first worker meets ENOMEM after the retry
    //    ladder; the exit is a clean 1 and the stderr line is the remedy.
    {
        try rig.env.put("SQUEEZEFS_TEST_KMBUF_REGISTER_ENOMEM", "1");
        const r = try rig.squeezefs(&.{ "mount", rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (r.term != .exited) std.debug.print("\n--- the refused mount died ({f}) instead of exiting ---\n{s}\n", .{ r.term, r.stderr });
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "squeezefs mount: the FUSE session could not arm at ") != null);
        // The precise levers (decision 0003 §AG.4): the region's pages,
        // never a contiguous-page shortage.
        try testing.expect(std.mem.indexOf(u8, r.stderr, ": kmbuf ring registration ENOMEM: a queue's region takes ") != null);
        for ([_][]const u8{ "SQUEEZEFS_FUSE_MAX_WRITE", "SQUEEZEFS_FUSE_OVER_IO_URING_Q_DEPTH", "SQUEEZEFS_FUSE_BUFFER_MODE=user" }) |lever| try testing.expect(std.mem.indexOf(u8, r.stderr, lever) != null);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "contiguous") == null);
        // The retry ladder ran its bounded course before the refusal.
        try testing.expectEqual(@as(usize, transport.kmbuf.REGISTER_RETRIES), std.mem.count(u8, r.stderr, "refused ENOMEM — retry "));
        try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
        try testing.expect(!status_verb.writerGuardHeld(testing.io, rig.img));
    }
    // 2. The same sampler seam over a clean cycle: the stop's tick reads
    //    live sources on the serve-path teardown too; exit 0.
    try rig.env.put("SQUEEZEFS_TEST_KMBUF_REGISTER_ENOMEM", "0");
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
}

/// B's shipped frees at rest: every block B shipped answered (freed,
/// non-terminal or refused) with none pending in its batch, and A's grace
/// ring empty — so both `df`s count every free, and a kill of A meets no
/// free in flight. Bounded by the rows' 60 s free wait; B's freed count at
/// rest.
fn awaitShippedFreesSettled(b: *Peer, rig: *Rig) !u64 {
    const gpa = rig.gpa;
    const deadline = clock.monotonicNs() + 60 * std.time.ns_per_s;
    while (true) {
        const tb = try b.stats();
        defer gpa.free(tb);
        const ta = try rig.stats();
        defer gpa.free(ta);
        const shipped = numberAfter(tb, "\"free_shipped_blocks\":") orelse 0;
        const freed = numberAfter(tb, "\"free_ship_freed\":") orelse 0;
        const answered = freed + (numberAfter(tb, "\"free_ship_nonterminal\":") orelse 0) + (numberAfter(tb, "\"free_ship_refused\":") orelse 0);
        const pending = numberAfter(tb, "\"pending_frees\":") orelse 0;
        const graced = numberAfter(ta, "\"free_grace_offsets\":") orelse 0;
        if (shipped == answered and pending == 0 and graced == 0) return freed;
        if (clock.monotonicNs() >= deadline) {
            std.debug.print("\nsmoke: B's shipped frees never settled — shipped {d}, answered {d} (freed {d}), pending {d}; A's grace ring {d}\n", .{ shipped, answered, freed, pending, graced });
            return error.FreesNeverSettled;
        }
        sleepMs(200);
    }
}

/// A data volume of three 4 MiB(+4 KiB) chunks: two reserved, one usable.
const data_volume_len: u64 = 3 * ((4 << 20) + 4096) + 4096;

test "smoke: a SET format — meta + 2 data files + lz4 + aes-256-gcm → both data superblocks written and read back → status lists both tags → a re-format refuses on the meta AND on a data volume → a mount with no key refuses naming every source → with the key it mounts, logs the set config and the key id, serves, unmounts → renumbered or blank data devices refuse the mount by name" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    {
        const f = try Io.Dir.cwd().createFile(io, rig.img, .{ .truncate = true });
        defer f.close(io);
        try f.setLength(io, volume_len);
    }
    var d0: [128]u8 = undefined;
    var d1: [128]u8 = undefined;
    var key_path: [128]u8 = undefined;
    const d0p = try std.fmt.bufPrint(&d0, "{s}/d0.img", .{rig.work});
    const d1p = try std.fmt.bufPrint(&d1, "{s}/d1.img", .{rig.work});
    const kp = try std.fmt.bufPrint(&key_path, "{s}/set.key", .{rig.work});
    for ([_][]const u8{ d0p, d1p }) |dp| {
        const f = try Io.Dir.cwd().createFile(io, dp, .{ .truncate = true });
        defer f.close(io);
        try f.setLength(io, data_volume_len);
    }
    // The key file: 0600, ≥ 32 B.
    {
        const out = try rig.shOk(rig.work, "umask 077; head -c 48 /dev/urandom | base64 > set.key; chmod 600 set.key; wc -c < set.key");
        defer gpa.free(out);
    }
    var data_uri: [320]u8 = undefined;
    const du = try std.fmt.bufPrint(&data_uri, "sqdata://{s},{s}", .{ d0p, d1p });
    // The set format.
    {
        const r = try rig.squeezefs(&.{ "format", "--compress", "lz4", "--encrypt", "aes-256-gcm", "--encrypt-key", kp, rig.meta_uri, du });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\nformat: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
        try testing.expect(std.mem.indexOf(u8, r.stdout, "compression lz4; encryption aes-256-gcm; key hkdf-sha256/aead-kw/v2 id ") != null);
        try testing.expect(std.mem.indexOf(u8, r.stdout, "data volumes 2 (VOLUME_LIFECYCLE") != null);
        try testing.expect(std.mem.indexOf(u8, r.stdout, "chunk 4198400 B") != null);
        try testing.expect(std.mem.indexOf(u8, r.stdout, " 1 blocks (4 MiB)") != null);
        try testing.expectEqual(@as(usize, 2), std.mem.count(u8, r.stdout, "vol-"));
    }
    // Both data files carry the identity at sector 0 and the tail.
    for ([_][]const u8{ d0p, d1p }) |dp| {
        var buf: [8]u8 = undefined;
        const f = try Io.Dir.cwd().openFile(io, dp, .{});
        defer f.close(io);
        try testing.expectEqual(@as(usize, 8), try f.readPositionalAll(io, &buf, 0));
        try testing.expectEqualStrings("SQZDATLV", &buf);
        try testing.expectEqual(@as(usize, 8), try f.readPositionalAll(io, &buf, data_volume_len - 4096));
        try testing.expectEqualStrings("SQZDATLV", &buf);
    }
    // status lists both with their tags.
    {
        const r = try rig.squeezefs(&.{ "status", rig.meta_uri });
        defer rig.freeRun(r);
        try testing.expect(r.term.success());
        try testing.expect(std.mem.indexOf(u8, r.stdout, "data volumes 2") != null);
        try testing.expect(std.mem.indexOf(u8, r.stdout, d0p) != null and std.mem.indexOf(u8, r.stdout, d1p) != null);
        // Two volume rows and, since rung 4, their two reference-census rows.
        try testing.expectEqual(@as(usize, 2), std.mem.count(u8, r.stdout, " active "));
        try testing.expectEqual(@as(usize, 2), std.mem.count(u8, r.stdout, "  refs       vol-"));
        try testing.expectEqual(@as(usize, 4), std.mem.count(u8, r.stdout, "vol-"));
    }
    // A re-format refuses: the meta volume first; with the meta forced, a data volume.
    {
        const r = try rig.squeezefs(&.{ "format", rig.meta_uri, du });
        defer rig.freeRun(r);
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "already formatted") != null);
    }
    {
        var data0_uri: [160]u8 = undefined;
        const du0 = try std.fmt.bufPrint(&data0_uri, "sqdata://{s}", .{d0p});
        // A second meta file so only the data gate is in the way.
        var m2: [128]u8 = undefined;
        const m2p = try std.fmt.bufPrint(&m2, "{s}/vol2.img", .{rig.work});
        {
            const f = try Io.Dir.cwd().createFile(io, m2p, .{ .truncate = true });
            defer f.close(io);
            try f.setLength(io, volume_len);
        }
        var m2u: [160]u8 = undefined;
        const m2uri = try std.fmt.bufPrint(&m2u, "sqmeta://{s}", .{m2p});
        const r = try rig.squeezefs(&.{ "format", m2uri, du0 });
        defer rig.freeRun(r);
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "already a SqueezeFS data volume (vol-") != null);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "--force") != null);
        // The refused format wrote nothing: the second meta file is still Blank.
        const st = try rig.squeezefs(&.{ "status", m2uri });
        defer rig.freeRun(st);
        try testing.expect(std.mem.indexOf(u8, st.stdout, "not formatted") != null);
    }
    // A mount with no key source refuses naming all three sources.
    {
        const r = try rig.squeezefs(&.{ "mount", rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "no encryption key") != null);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "SQUEEZEFS_ENCRYPT_KEY_FILE") != null);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "/etc/squeezefs/keys/") != null);
        try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    }
    // A wrong key refuses by id.
    {
        const out = try rig.shOk(rig.work, "umask 077; head -c 48 /dev/urandom | base64 > wrong.key; chmod 600 wrong.key");
        defer gpa.free(out);
        var wk: [128]u8 = undefined;
        const wkp = try std.fmt.bufPrint(&wk, "{s}/wrong.key", .{rig.work});
        try rig.env.put("SQUEEZEFS_ENCRYPT_KEY_FILE", wkp);
        const r = try rig.squeezefs(&.{ "mount", rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "key id differs") != null);
    }
    // With the key: mount, the set config and the key id in the log, a write, umount.
    try rig.env.put("SQUEEZEFS_ENCRYPT_KEY_FILE", kp);
    try rig.spawnMount(&.{});
    const ready_at = try rig.awaitReady(0);
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expect(std.mem.indexOf(u8, text[0..ready_at], "encryption key verified (hkdf-sha256/aead-kw/v2, id ") != null);
        try testing.expect(std.mem.indexOf(u8, text[0..ready_at], "set config generation 1") != null);
        try testing.expect(std.mem.indexOf(u8, text[0..ready_at], "non-dumpable") != null);
    }
    {
        const out = try rig.shOk(rig.mp, "echo hello > f && test \"$(cat f)\" = hello && echo write-ok");
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "write-ok") != null);
    }
    try rig.umount();
    const term = try rig.waitChild();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, term);
    // A renumbered device: swap the two data files; the mount refuses
    // naming the tag it found and the tag the set names.
    {
        const out = try rig.shOk(rig.work, "mv d0.img swap.img && mv d1.img d0.img && mv swap.img d1.img");
        defer gpa.free(out);
        const r = try rig.squeezefs(&.{ "mount", rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "the device was renumbered or belongs to another set") != null);
        try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    }
    // A missing data device is not a formatted data volume: refused by name.
    {
        const out = try rig.shOk(rig.work, "mv d1.img d0.img && truncate -s 13M d1.img");
        defer gpa.free(out);
        const r = try rig.squeezefs(&.{ "mount", rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        try testing.expectEqual(std.process.Child.Term{ .exited = 1 }, r.term);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "is not a formatted data volume") != null);
    }
    std.debug.print("\nsmoke: set format ok (2 data volumes, lz4 + aes-256-gcm, key gate, renumbered/blank refusals)\n", .{});
}

const transform_mod = @import("../data/transform.zig");
const bench_terms = @import("bench.zig").StatsTerms;

/// The transformed append row's appends: 72 B lines, each its own fsync'd
/// O_APPEND write (one drain per append).
const xform_appends = 40;

test "smoke: THE TRANSFORMED APPEND on a cache-less mount (decision 0003 §AK) — lz4, then aes-256-gcm: a file past the inline bound grows by 40 fsync'd 72 B appends and reads back exact (the write side seeded a transformed block's image through a block-sized buffer the chunk-sized read window refused: EIO at the first write past 4 KiB); a transformed block cannot be patched in place, so each drain lands the block's framed image whole — trimmed to its live bytes: ≤ the stored bound of the file's bytes per drain (8,192 B on aes-256-gcm for a 7,880 B file), where the untrimmed image of an encrypted set was the whole block; a read past the image's plaintext within EOF serves zeros" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    for ([_]transform_mod.Encryption{ .none, .aes256gcm }) |enc| {
        const rig = try Rig.init(gpa, io);
        defer rig.deinit();
        var kp_buf: [160]u8 = undefined;
        const kp = try std.fmt.bufPrint(&kp_buf, "{s}/set.key", .{rig.work});
        const cfg: transform_mod.VolumeTransform = .{ .compression = if (enc == .none) .lz4 else .none, .encryption = enc, .block_size = @intCast(4 * derive.MiB) };
        if (enc == .none) {
            try rig.formatSetWith(false, &.{ "--compress", "lz4" });
            try rig.spawnMount(&.{});
        } else {
            const out = try rig.shOk(rig.work, "umask 077; head -c 48 /dev/urandom | base64 > set.key; chmod 600 set.key");
            gpa.free(out);
            try rig.formatSetWith(false, &.{ "--encrypt", "aes-256-gcm", "--encrypt-key", kp });
            try rig.spawnMount(&.{ "--encrypt-key", kp });
        }
        _ = try rig.awaitReady(0);
        // Past the inline bound: 4,096 B inline, then 904 B that promote the
        // file — fsync'd: its custody lands before the appends' window
        // opens (close is no durability point, decision 0003 §AJ).
        const sp = try rig.stats();
        defer gpa.free(sp);
        {
            const out = try rig.onMountTimed("head -c 5000 /dev/urandom > \"$1/ref\" && dd if=\"$1/ref\" of=f bs=4096 conv=fsync status=none && cmp f \"$1/ref\" && echo same", 60);
            defer gpa.free(out);
            try testing.expectEqualStrings("same\n", out);
        }
        // The promotion's own-block DMA counts the bytes it landed (the
        // stored image, grain-padded): the device-write ledger closes.
        {
            const sq = try rig.stats();
            defer gpa.free(sq);
            const own = (numberAfter(sq, "\"own_block_dma_bytes\":") orelse 0) - (numberAfter(sp, "\"own_block_dma_bytes\":") orelse 0);
            try testing.expect(own != 0 and own % 4096 == 0 and own <= transform_mod.storedImageBound(cfg, 4096));
            if (enc != .none) try testing.expectEqual(transform_mod.storedImageBound(cfg, 4096), own);
        }
        const st0 = try rig.stats();
        defer gpa.free(st0);
        {
            var script: std.Io.Writer.Allocating = .init(gpa);
            defer script.deinit();
            try script.writer.print("i=0; while [ $i -lt {d} ]; do printf '%071d\\n' $i >> \"$1/ref\"; printf '%071d\\n' $i | dd of=f oflag=append conv=notrunc,fsync status=none; i=$((i+1)); done; cmp f \"$1/ref\" && echo same", .{xform_appends});
            const out = try rig.onMountTimed(script.written(), 120);
            defer gpa.free(out);
            try testing.expectEqualStrings("same\n", out);
        }
        const st1 = try rig.stats();
        defer gpa.free(st1);
        const device = bench_terms.parse(st1).device_write_bytes - bench_terms.parse(st0).device_write_bytes;
        const per_drain = transform_mod.storedImageBound(cfg, 5000 + xform_appends * 72);
        std.debug.print("\nsmoke[xform append {t}]: {d} appends of 72 B drained as {d} B of images (×{d} per appended byte; the bound {d} B per drain)\n", .{ enc, xform_appends, device, device / (xform_appends * 72), per_drain });
        try testing.expect(device > 0);
        try testing.expect(device <= xform_appends * per_drain);
        // A read past the image's plaintext within EOF: zeros.
        {
            const out = try rig.onMountTimed("truncate -s 300000 f && cp \"$1/ref\" \"$1/ref2\" && truncate -s 300000 \"$1/ref2\" && dd if=f of=\"$1/tail\" bs=4096 skip=60 count=1 iflag=direct status=none && cmp -n 4096 \"$1/tail\" /dev/zero && cmp f \"$1/ref2\" && echo same", 60);
            defer gpa.free(out);
            try testing.expectEqualStrings("same\n", out);
        }
    }
}

// ---------------------------------------------------------------------------
// Rung 4: the data plane bound to the mount (charter §6, §13 rung 4).
// ---------------------------------------------------------------------------

/// A data volume: 2 GiB sparse on the venue's ext4 = 510 usable 4 MiB
/// blocks past the superblock chunk; two of them hold the pass's peak
/// (200 MiB `dd` + 100 MiB copy + 8 × 50 MiB storm ≈ 175 blocks) and, on
/// the cache-less mount, 100 one-block 64 KiB files.
const data_len: u64 = 2 << 30;
/// The random image on ext4 every stage slices (`image_mib` ≥ 200 for the
/// `dd`, 100 for the copy, 8 × 50 MiB at 25 MiB strides = 225, the storm
/// kill's 3 MiB resident at 240, 1000 × 64 KiB = 62.5).
const image_mib: u64 = 256;
const big_mib: u64 = 200;
const copy_mib: u64 = 100;
const storm_files: usize = 8;
const storm_mib: u64 = 50;
/// The storm's sources are overlapping slices of the image, one per file.
const storm_stride_mib: u64 = 25;
/// The packed candidates on the staging set: 64 KiB (> inline_max, ≪ the
/// 2 MiB max slot) × 1000 = 62.5 MiB.
const small_files_staged: usize = 1000;
/// Without the write cache a 64 KiB file is one striped block: 100 of them
/// = 400 MiB of the set's 4080 MiB.
const small_files_striped: usize = 100;
const small_len: u64 = 64 << 10;
/// The pack census bound (the task's): ceil(1000 × 64 KiB / 2 MiB) = 32
/// blocks, plus one open pack per data volume that the DISMOUNT seal may
/// close short.
const pack_census_bound: u64 = (small_files_staged * small_len + (2 << 20) - 1) / (2 << 20) + 2;
/// The write-cache row's daemon budget, pinned. The write cache's bound is
/// `SQUEEZEFS_WRITE_CACHE_PCT` of `budget ÷ 0.7` (`cache.derivedBound`:
/// 25 % of 1.43 GiB = 365 MiB here), and the storm beside the small files
/// must overflow it, so the LRU drain packs the small files (the oldest)
/// online: the open packs the post-rm census judges (leak67). A derived
/// budget on a big host (kamrui, 61 GiB) gave a ring the storm never
/// filled; nothing packed, and the row passed without judging a pack. Under
/// the gate's shared cage this budget also reads Red (the cage's
/// unreclaimable over the daemon census): the shed is one drain pass to the
/// budget's target, the small files still leave through the pack dispatch.
const cache_row_budget_mib: u64 = 1024;
/// The bound the pinned budget derives (`cache.derivedBound(25, …)`), MiB.
const cache_row_ring_mib: u64 = cache_row_budget_mib * 10 / 7 * 25 / 100;
comptime {
    if (cache_row_ring_mib >= storm_files * storm_mib + small_files_staged * small_len / (1 << 20)) @compileError("the storm no longer overflows the write-cache row's ring");
}
/// 4 KiB overwrites against the mirrored image: page-aligned (the W1
/// patch class on a striped file) and at arbitrary byte offsets (the
/// overlay / RMW classes).
const overwrites_aligned: usize = 64;
const overwrites_unaligned: usize = 16;
/// The overwrite stage's fixed seed (a pass is reproducible from the log).
const overwrite_seed: u64 = 0x5151_4a4a_0404_2026;
/// The looped single-stage repro's knob (`knobs.zig`, harness class).
const smoke_loops_knob = "SQUEEZEFS_TEST_SMOKE_STAGE_LOOPS";
const data_dir_knob = "SQUEEZEFS_TEST_DATA_DIR";
const rings_knob = "SQUEEZEFS_FUSE_RINGS_PER_QUEUE";
/// One looped pass's wall bound: the overwrite stage runs ~5 s, the storm
/// ~15 s on the venue; a pass past this is a hang, killed and failed.
const stage_loop_timeout_s: u32 = 300;
/// No op of any class may take longer than this on the looped passes (the
/// phantom "5 s stall" was a watchdog artifact; the real tail is ≤ 256 ms).
const op_latency_bound = "<=1s";
/// The kill points of the mid-`dd` matrix: the MiB the inode claims when
/// SIGKILL is sent. The staged phase ends at one block (4 MiB), so every
/// point is deep in the striped write pipeline.
const kill_points_mib = [_]u64{ 50, 100, 150 };
/// The files the strict ack law covers: `fsync` returned before the kill.
const acked_mib: u64 = 8;
/// The storm kill fires once this many bytes are claimed across the eight
/// files: a quarter of the storm in flight.
const storm_kill_mib: u64 = 100;
/// The census grain: a FUSE page. Every page inside a file's claimed size
/// is exact or a hole (the write pipeline publishes whole blocks after
/// their DMA; the size claim lands after the pieces ack; a crash leaves
/// holes, never garbage).
const census_grain: usize = 4096;

/// Stage A: the 200 MiB `dd`, fsync, the sha round trip against the image.
const stage_dd_script =
    \\W="$1"
    \\s=$(date +%s%N)
    \\dd if="$W/image" of=big bs=1M count=200 status=none
    \\sync -d big
    \\e=$(date +%s%N)
    \\echo "dd_ns=$((e - s))"
    \\test "$(stat -c %s big)" = 209715200
    \\head -c 209715200 "$W/image" > "$W/expect"
    \\sha256sum big | cut -d' ' -f1 > "$W/big.sha"
    \\sha256sum "$W/expect" | cut -d' ' -f1 > "$W/expect.sha"
    \\cmp "$W/big.sha" "$W/expect.sha"
    \\echo stage-dd-ok
;

/// Stage B: `cp` 100 MiB + `cmp`, an O_DIRECT read pass (the daemon's
/// READ path; the page cache bypassed).
const stage_cp_script =
    \\W="$1"
    \\head -c 104857600 "$W/image" > "$W/hundred"
    \\s=$(date +%s%N)
    \\cp "$W/hundred" big100
    \\sync -d big100
    \\e=$(date +%s%N)
    \\echo "cp_ns=$((e - s))"
    \\cmp big100 "$W/hundred"
    \\s=$(date +%s%N)
    \\dd if=big100 of=/dev/null bs=1M iflag=direct status=none
    \\e=$(date +%s%N)
    \\echo "read_ns=$((e - s))"
    \\dd if=big100 of=/dev/null bs=1M iflag=direct status=none
    \\s=$(date +%s%N)
    \\dd if=big100 of=/dev/null bs=1M iflag=direct status=none
    \\e=$(date +%s%N)
    \\echo "reread_ns=$((e - s))"
    \\echo stage-cp-ok
;

/// Stage C: shrink to 150 MiB, grow to 220 MiB — mirrored on the image.
/// Then the shared-mode classifier's repro (fstests generic/013,
/// `write_shared_class_violation`): an 8 MiB striped file shrunk to
/// 1.3 MB — the kept block's zero tail `[1.3 MB, 4 MiB)` is a write the
/// plane folds and uploads with the BLOCK END as its map reach floor —
/// fsync (the upload's merge lands), then ONE extending 4 KiB write at
/// 1.5 MiB, past the new EOF and inside that block. The map merge used
/// to publish its reach floor (4 MiB) as the inode's shape, so the write
/// read as Shared on a size the file no longer had: `expectMustStayZero`
/// on the pass's tail is the assertion; the mirror pins the bytes.
const stage_truncate_script =
    \\W="$1"
    \\truncate -s 150M big
    \\truncate -s 150M "$W/expect"
    \\test "$(stat -c %s big)" = 157286400
    \\truncate -s 220M big
    \\truncate -s 220M "$W/expect"
    \\test "$(stat -c %s big)" = 230686720
    \\sync -d big
    \\cmp big "$W/expect"
    \\dd if="$W/image" of=shrunk bs=1M count=8 status=none
    \\dd if="$W/image" of="$W/shrunk" bs=1M count=8 status=none
    \\sync -d shrunk
    \\truncate -s 1300000 shrunk
    \\truncate -s 1300000 "$W/shrunk"
    \\sync -d shrunk
    \\head -c 4096 /dev/urandom > "$W/page"
    \\dd if="$W/page" of=shrunk bs=4k seek=384 count=1 conv=notrunc status=none
    \\dd if="$W/page" of="$W/shrunk" bs=4k seek=384 count=1 conv=notrunc status=none
    \\test "$(stat -c %s shrunk)" = 1576960
    \\sync -d shrunk
    \\cmp shrunk "$W/shrunk"
    \\echo stage-truncate-ok
;

/// Stage F: eight parallel `cp` of 50 MiB each, every file fsync'd, then
/// compared.
const stage_storm_script =
    \\W="$1"
    \\i=0
    \\while [ $i -lt 8 ]; do
    \\  dd if="$W/image" of="$W/s$i" bs=1M skip=$((i * 25)) count=50 status=none
    \\  i=$((i + 1))
    \\done
    \\s=$(date +%s%N)
    \\i=0
    \\while [ $i -lt 8 ]; do
    \\  ( cp "$W/s$i" storm$i && sync -d storm$i ) &
    \\  i=$((i + 1))
    \\done
    \\wait
    \\e=$(date +%s%N)
    \\echo "storm_ns=$((e - s))"
    \\i=0
    \\while [ $i -lt 8 ]; do
    \\  cmp storm$i "$W/s$i"
    \\  i=$((i + 1))
    \\done
    \\echo stage-storm-ok
;

/// Stage D's script: `n_aligned` page-aligned and `n_unaligned` arbitrary
/// 4 KiB overwrites of `big` (220 MiB after stage C), each mirrored on
/// the image copy with the same source page; deterministic offsets from
/// `seed` (the pass is reproducible from the log; a looped pass takes a
/// distinct seed so a lost write cannot hide behind the previous pass's
/// identical bytes).
fn overwriteScript(gpa: std.mem.Allocator, n_aligned: usize, n_unaligned: usize, seed: u64) ![]u8 {
    var script: std.Io.Writer.Allocating = .init(gpa);
    errdefer script.deinit();
    const w = &script.writer;
    try w.writeAll("W=\"$1\"\n");
    var prng = std.Random.DefaultPrng.init(seed);
    const rnd = prng.random();
    const file_len: u64 = 220 << 20;
    const pages = file_len / 4096;
    for (0..n_aligned + n_unaligned) |i| {
        const src_page = rnd.uintLessThan(u64, (image_mib << 20) / 4096);
        if (i < n_aligned) {
            const dst_page = rnd.uintLessThan(u64, pages);
            for ([_][]const u8{ "big", "\"$W/expect\"" }) |dst| {
                try w.print("dd if=\"$W/image\" of={s} bs=4096 count=1 skip={d} seek={d} conv=notrunc status=none\n", .{ dst, src_page, dst_page });
            }
        } else {
            const dst_off = rnd.uintLessThan(u64, file_len - 4096);
            for ([_][]const u8{ "big", "\"$W/expect\"" }) |dst| {
                try w.print("dd if=\"$W/image\" of={s} bs=4096 count=1 skip={d} seek={d} oflag=seek_bytes conv=notrunc status=none\n", .{ dst, src_page, dst_off });
            }
        }
    }
    try w.writeAll(
        \\sync -d big
        \\cmp big "$W/expect"
        \\sha256sum big | cut -d' ' -f1
        \\echo stage-overwrite-ok
        \\
    );
    return script.toOwnedSlice();
}

/// Stage E's script: `n` files of 64 KiB, each a distinct slice of the image.
fn smallFilesScript(gpa: std.mem.Allocator, n: usize) ![]u8 {
    return std.fmt.allocPrint(gpa,
        \\W="$1"
        \\mkdir -p p
        \\s=$(date +%s%N)
        \\i=0
        \\while [ $i -lt {d} ]; do
        \\  dd if="$W/image" of=p/f$i bs=65536 count=1 skip=$i status=none
        \\  i=$((i + 1))
        \\done
        \\sync -d p/f0 p/f{d}
        \\e=$(date +%s%N)
        \\echo "small_ns=$((e - s))"
        \\echo stage-small-ok
        \\
    , .{ n, n - 1 });
}

/// The small files after the remount: their concatenation is the image prefix.
fn smallFilesVerifyScript(gpa: std.mem.Allocator, n: usize) ![]u8 {
    return std.fmt.allocPrint(gpa,
        \\W="$1"
        \\i=0
        \\while [ $i -lt {d} ]; do
        \\  cat p/f$i
        \\  i=$((i + 1))
        \\done | sha256sum | cut -d' ' -f1 > "$W/small.sha"
        \\head -c {d} "$W/image" | sha256sum | cut -d' ' -f1 > "$W/small-expect.sha"
        \\cmp "$W/small.sha" "$W/small-expect.sha"
        \\rm -r p
        \\echo small-verify-ok
        \\
    , .{ n, n * small_len });
}

/// MB/s from a byte count and a `date +%s%N` difference parsed from `key=`.
fn mbPerS(out: []const u8, key: []const u8, bytes: u64) u64 {
    const ns = numberAfter(out, key) orelse return 0;
    if (ns == 0) return 0;
    return bytes * 1000 / ns;
}

/// The must-stay-0 gauges of a data-plane mount, read from one stats tail.
const must_stay_zero = [_][]const u8{
    "\"transport_requests_abandoned\":",
    "\"open_count_stranded\":",
    // The commit and CQE halves' TRIPWIRES only: `transport_park_tick_late_
    // commits` / `_late_cqes` count replies and completions that arrived
    // after a tick's deadline (late, not a fault).
    "\"transport_park_tick_commit_lost_wakes\":",
    "\"transport_park_tick_cqe_lost_wakes\":",
    "\"exec_lane_tick_rescues\":",
    "\"lock_ticked_reregisters\":",
    "\"channel_ticked_reregisters\":",
    "\"fuse_op_watchdog_overdue\":",
    "\"invariant_tripwires\":",
    "\"patch_edge_rmw_reads\":",
    "\"overlay_fence_drops\":",
    "\"data_unresolved_volume\":",
    "\"block_double_frees\":",
    "\"meta_kv_block_refs_drift\":",
    "\"pack_pin_refcount_drift\":",
    "\"staged_payload_lost_reads\":",
    "\"write_shared_class_violation\":",
    "\"read_dest_overruns\":",
    "\"layout_map_merge_failures\":",
    "\"promotions_failed\":",
    "\"held_store_failures\":",
    "\"transport_zc_direct_leg_recheck_withdrawn\":",
    "\"fuse_write_no_data_volume_refused\":",
    "\"fuse_write_u32_index_refused\":",
    "\"kvmap_resolve_failures\":",
    "\"kvmap_owner_mismatch\":",
    "\"kvmap_sweep_spawn_refusals\":",
    "\"writeback_errors_latched\":",
    "\"fsync_promote_failures\":",
};

/// The JSON object that follows `key` in `text` (brace-balanced, strings
/// skipped), or null.
fn objectAfter(text: []const u8, key: []const u8) ?[]const u8 {
    const at = (std.mem.indexOf(u8, text, key) orelse return null) + key.len;
    if (at >= text.len or text[at] != '{') return null;
    var depth: usize = 0;
    var in_str = false;
    var i = at;
    while (i < text.len) : (i += 1) {
        const c = text[i];
        if (in_str) {
            if (c == '\\') i += 1 else if (c == '"') in_str = false;
            continue;
        }
        switch (c) {
            '"' => in_str = true,
            '{', '[' => depth += 1,
            '}', ']' => {
                depth -= 1;
                if (depth == 0) return text[at .. i + 1];
            },
            else => {},
        }
    }
    return null;
}

/// The words a symmetric gauge may read on a `--single-writer` mount.
const solo_words = [_][]const u8{ "solo", "off", "none", "vacant", "" };

/// Charter §5.5 "Every one reads 0/`solo` on a `--single-writer`
/// mount": every `"key":value` pair of `family` (recursively) is a number
/// reading 0, a boolean reading false, or a string from `solo_words`;
/// the first offender is named.
fn expectSoloPosture(family_name: []const u8, family: []const u8) !void {
    var bad: usize = 0;
    var i: usize = 0;
    while (std.mem.indexOfScalarPos(u8, family, i, '"')) |q| {
        const end = std.mem.indexOfScalarPos(u8, family, q + 1, '"') orelse break;
        const k = family[q + 1 .. end];
        i = end + 1;
        if (i >= family.len or family[i] != ':') continue;
        const v = std.mem.trimStart(u8, family[i + 1 ..], " ");
        if (v.len == 0) break;
        switch (v[0]) {
            '{', '[' => {},
            '"' => {
                const se = std.mem.indexOfScalarPos(u8, v, 1, '"') orelse break;
                const s = v[1..se];
                var ok = false;
                for (solo_words) |w| ok = ok or std.mem.eql(u8, w, s);
                if (!ok) {
                    std.debug.print("\n--- {s}: {s} = \"{s}\" on a --single-writer mount (expected a solo word) ---\n", .{ family_name, k, s });
                    bad += 1;
                }
                i += 1 + se + 1;
            },
            't' => {
                std.debug.print("\n--- {s}: {s} = true on a --single-writer mount ---\n", .{ family_name, k });
                bad += 1;
            },
            'f', 'n' => {},
            else => {
                var e: usize = 0;
                while (e < v.len and (std.ascii.isDigit(v[e]) or v[e] == '-' or v[e] == '.')) : (e += 1) {}
                const n = v[0..e];
                if (n.len == 0) continue;
                if (!std.mem.allEqual(u8, n, '0') and !std.mem.eql(u8, n, "0.0")) {
                    std.debug.print("\n--- {s}: {s} = {s} on a --single-writer mount (expected 0) ---\n", .{ family_name, k, n });
                    bad += 1;
                }
            },
        }
    }
    try testing.expectEqual(@as(usize, 0), bad);
}

fn expectMustStayZero(tail: []const u8) !void {
    var bad = false;
    for (must_stay_zero) |k| {
        const v = numberAfter(tail, k) orelse {
            std.debug.print("\n--- gauge missing from the stats dump: {s} ---\n", .{k});
            bad = true;
            continue;
        };
        if (v != 0) {
            std.debug.print("\n--- must-stay-0 gauge {s} = {d} ---\n", .{ k, v });
            bad = true;
        }
    }
    try testing.expect(!bad);
    try testing.expect(std.mem.indexOf(u8, tail, "\"volume_failed\":false") != null);
}

/// The ledgers that close on a quiescent mount: the admission ledger ≡
/// the transport's WRITE payload bytes (every user byte admitted ONCE);
/// the read copy ledger ≡ the read path's user bytes; the reclaim ledger
/// `queued + elided ≡ terminal frees`.
fn expectLedgersClosed(tail: []const u8) !void {
    const admit = (numberAfter(tail, "\"admit_write_overlay_bytes\":") orelse 0) + (numberAfter(tail, "\"admit_write_inplace_bytes\":") orelse 0) + (numberAfter(tail, "\"admit_write_accumulate_bytes\":") orelse 0) + (numberAfter(tail, "\"admit_write_inline_bytes\":") orelse 0);
    // + the extension law's zeros (decision 0003 §AL).
    const transport_write = (numberAfter(tail, "\"transport_zc_write_extract_bytes\":") orelse 0) + (numberAfter(tail, "\"transport_zc_write_direct_bytes\":") orelse 0) + (numberAfter(tail, "\"transport_write_window_bytes\":") orelse 0) + (numberAfter(tail, "\"write_gap_zero_bytes\":") orelse 0);
    if (admit != transport_write) std.debug.print("\n--- admission ledger {d} ≠ transport WRITE payload bytes + the extension law's zeros {d} ---\n", .{ admit, transport_write });
    try testing.expectEqual(transport_write, admit);
    const user = numberAfter(tail, "\"read_user_bytes\":") orelse 0;
    const copies = (numberAfter(tail, "\"read_copy_dest_bytes\":") orelse 0) + (numberAfter(tail, "\"read_copy_bounce_bytes\":") orelse 0) + (numberAfter(tail, "\"read_dest_dma_bytes\":") orelse 0) + (numberAfter(tail, "\"read_zc_serve_bytes\":") orelse 0) + (numberAfter(tail, "\"read_zc_pool_serve_bytes\":") orelse 0);
    if (user != copies) std.debug.print("\n--- read copy ledger {d} ≠ read user bytes {d} ---\n", .{ copies, user });
    try testing.expectEqual(user, copies);
    // Every abandoned mint is an orphan's discard on a healthy device (a
    // superseded write-through publishes its snapshot, decision 0003 §AJ.7;
    // a failed DMA would be its own alert).
    const abandons = numberAfter(tail, "\"unpublished_mint_abandons\":") orelse 0;
    const legit = numberAfter(tail, "\"write_pipeline_discards\":") orelse 0;
    // (a flush that finds its entry already gone discards BEFORE minting.)
    if (abandons > legit) std.debug.print("\n--- mint abandons {d} > discards {d} ---\n", .{ abandons, legit });
    try testing.expect(abandons <= legit);
    const queued = numberAfter(tail, "\"block_free_reclaim_queued\":") orelse 0;
    const elided = numberAfter(tail, "\"block_free_reclaim_elided\":") orelse 0;
    const terminal = numberAfter(tail, "\"terminal_frees\":") orelse 0;
    if (terminal != queued + elided) std.debug.print("\n--- reclaim ledger: terminal {d} ≠ queued {d} + elided {d} ---\n", .{ terminal, queued, elided });
    try testing.expectEqual(queued + elided, terminal);
}

