    }
}

/// `reads` random 4 KiB O_DIRECT PREADs of `path` (kernel aio, `depth` per
/// submit), every event's `res` the page, every page byte-exact against
/// `pattern` (the same bytes on the host fs) — the perf matrix's
/// `rr4k` shape in miniature. Offsets below `len` (4 KiB-aligned).
fn aioRandomReads(path: [:0]const u8, pattern: [:0]const u8, len: u64, reads: usize, depth: usize, seed: u64) !void {
    const aio = @import("../shim/aio.zig");
    const page: usize = 4096;
    var ctx: aio.io_context_t = 0;
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.syscall2(.io_setup, @intCast(depth), @intFromPtr(&ctx))));
    defer _ = linux.syscall1(.io_destroy, ctx);
    const rc = linux.open(path.ptr, .{ .ACCMODE = .RDONLY, .DIRECT = true, .CLOEXEC = true }, 0);
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(rc));
    const fd: linux.fd_t = @intCast(rc);
    defer _ = linux.close(fd);
    const prc = linux.open(pattern.ptr, .{ .ACCMODE = .RDONLY, .CLOEXEC = true }, 0);
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(prc));
    const pfd: linux.fd_t = @intCast(prc);
    defer _ = linux.close(pfd);
    const gpa = testing.allocator;
    const buf = try gpa.alignedAlloc(u8, .fromByteUnits(page), depth * page);
    defer gpa.free(buf);
    const want = try gpa.alloc(u8, page);
    defer gpa.free(want);
    const cbs = try gpa.alloc(aio.Iocb, depth);
    defer gpa.free(cbs);
    const ptrs = try gpa.alloc(*aio.Iocb, depth);
    defer gpa.free(ptrs);
    const evs = try gpa.alloc(aio.IoEvent, depth);
    defer gpa.free(evs);
    var prng = std.Random.DefaultPrng.init(seed);
    const rnd = prng.random();
    var offs = try gpa.alloc(u64, depth);
    defer gpa.free(offs);
    var done: usize = 0;
    while (done < reads) {
        const n = @min(depth, reads - done);
        for (cbs[0..n], 0..) |*cb, i| {
            offs[i] = rnd.uintLessThan(u64, len / page) * page;
            cb.* = .{ .data = i, .key = 0, .aio_rw_flags = 0, .aio_lio_opcode = aio.IOCB_CMD_PREAD, .aio_reqprio = 0, .aio_fildes = fd, .buf = @intFromPtr(buf.ptr + i * page), .nbytes = page, .offset = @intCast(offs[i]), .__pad3 = 0, .flags = 0, .resfd = 0 };
            ptrs[i] = cb;
        }
        try testing.expectEqual(n, linux.syscall3(.io_submit, ctx, n, @intFromPtr(ptrs.ptr)));
        var got: usize = 0;
        while (got < n) {
            const ts: linux.timespec = .{ .sec = 30, .nsec = 0 };
            const r = linux.syscall5(.io_getevents, ctx, 1, n - got, @intFromPtr(evs.ptr + got), @intFromPtr(&ts));
            try testing.expectEqual(linux.E.SUCCESS, linux.errno(r));
            try testing.expect(r > 0);
            got += r;
        }
        for (evs[0..n]) |ev| {
            try testing.expectEqual(@as(i64, page), ev.res);
            const i: usize = @intCast(ev.data);
            try testing.expectEqual(page, linux.pread(pfd, want.ptr, page, @intCast(offs[i])));
            try testing.expectEqualSlices(u8, want, buf[i * page ..][0..page]);
        }
        done += n;
    }
}

test "smoke: THE READ VIEW — a 16 MiB striped file (no write cache), its custody landed; 512 random 4 KiB O_DIRECT reads (QD 8) byte-exact: every probe and every post-DMA recheck resolves off the per-ino view (read_view_hits ≥ 2 per read, no view miss after the first read's fill, at most the atime echo's refill); a truncate stales the view (a read at the old length is EOF, read_view_stale moved), an overwrite's publish stales it again (the new bytes read back), the must-stay-0 set clean" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    const file_len: u64 = 16 << 20;
    var script: [512]u8 = undefined;
    gpa.free(try rig.shOk(rig.work, try std.fmt.bufPrint(&script, "head -c {d} /dev/urandom > pattern && cp pattern {s}/f && sync -f {s}", .{ file_len, rig.mp, rig.mp })));
    var fb: [192]u8 = undefined;
    const f = try std.fmt.bufPrintSentinel(&fb, "{s}/f", .{rig.mp}, 0);
    var pb: [linux.PATH_MAX]u8 = undefined;
    const pattern = try std.fmt.bufPrintSentinel(&pb, "{s}/pattern", .{rig.work}, 0);
    // One read first: the view fills off the KV path for this file.
    try aioRandomReads(f, pattern, file_len, 1, 1, 1);
    const t0 = try rig.stats();
    defer gpa.free(t0);
    const reads: usize = 512;
    try aioRandomReads(f, pattern, file_len, reads, 8, 2);
    const t1 = try rig.stats();
    defer gpa.free(t1);
    const hits = numberAfter(t1, "\"read_view_hits\":").? - numberAfter(t0, "\"read_view_hits\":").?;
    const misses = numberAfter(t1, "\"read_view_misses\":").? - numberAfter(t0, "\"read_view_misses\":").?;
    const fills = numberAfter(t1, "\"read_view_fills\":").? - numberAfter(t0, "\"read_view_fills\":").?;
    const stale = numberAfter(t1, "\"read_view_stale\":").? - numberAfter(t0, "\"read_view_stale\":").?;
    const ring_reads = numberAfter(t1, "\"transport_ring_reads\":").? - numberAfter(t0, "\"transport_ring_reads\":").?;
    std.debug.print("\nsmoke: the read view over {d} random 4 KiB O_DIRECT reads ({d} ring reads): view hits {d}, misses {d}, fills {d}, stale {d}; direct legs {d}, fast-dispatch serves {d}\n", .{ reads, ring_reads, hits, misses, fills, stale, numberAfter(t1, "\"direct_leg_offers\":").? - numberAfter(t0, "\"direct_leg_offers\":").?, numberAfter(t1, "\"fast_dispatch_serves\":").? - numberAfter(t0, "\"fast_dispatch_serves\":").? });
    // The probe's resolution and the recheck's binding: two hits per read
    // at least, none of them a KV lookup (a miss would have filled).
    try testing.expect(hits >= 2 * reads);
    try testing.expectEqual(@as(u64, 0), misses);
    // The one admissible refill inside the loop: the first read's atime
    // echo (relatime: mtime > atime) drains as an inode record.
    try testing.expect(stale <= 1);
    try testing.expect(fills <= 2);
    // A truncate: the inode and layout records land, the witness moves,
    // the first read after it finds the view stale and refills; a read at
    // the old length is EOF (res 0), never the stale size's bytes.
    gpa.free(try rig.shOk(rig.work, try std.fmt.bufPrint(&script, "truncate -s {d} {s}/f && truncate -s {d} pattern", .{ file_len / 2, rig.mp, file_len / 2 })));
    {
        const aio = @import("../shim/aio.zig");
        var ctx: aio.io_context_t = 0;
        try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.syscall2(.io_setup, 1, @intFromPtr(&ctx))));
        defer _ = linux.syscall1(.io_destroy, ctx);
        const rc = linux.open(f.ptr, .{ .ACCMODE = .RDONLY, .DIRECT = true, .CLOEXEC = true }, 0);
        try testing.expectEqual(linux.E.SUCCESS, linux.errno(rc));
        const fd: linux.fd_t = @intCast(rc);
        defer _ = linux.close(fd);
        const buf = try gpa.alignedAlloc(u8, .fromByteUnits(4096), 4096);
        defer gpa.free(buf);
        var cb: aio.Iocb = .{ .data = 0, .key = 0, .aio_rw_flags = 0, .aio_lio_opcode = aio.IOCB_CMD_PREAD, .aio_reqprio = 0, .aio_fildes = fd, .buf = @intFromPtr(buf.ptr), .nbytes = 4096, .offset = @intCast(file_len - 4096), .__pad3 = 0, .flags = 0, .resfd = 0 };
        var ptr: *aio.Iocb = &cb;
        try testing.expectEqual(@as(usize, 1), linux.syscall3(.io_submit, ctx, 1, @intFromPtr(&ptr)));
        var ev: aio.IoEvent = undefined;
        const ts: linux.timespec = .{ .sec = 30, .nsec = 0 };
        try testing.expectEqual(@as(usize, 1), linux.syscall5(.io_getevents, ctx, 1, 1, @intFromPtr(&ev), @intFromPtr(&ts)));
        try testing.expectEqual(@as(i64, 0), ev.res);
    }
    // Reads inside the new length: the first finds the view stale (the
    // truncate's records moved the witness) and refills it.
    try aioRandomReads(f, pattern, file_len / 2, 64, 8, 3);
    const t2 = try rig.stats();
    defer gpa.free(t2);
    try testing.expect(numberAfter(t2, "\"read_view_stale\":").? > numberAfter(t1, "\"read_view_stale\":").?);
    // An overwrite of page 5 (its publish lands a new binding): the view
    // stales again and the new bytes read back.
    gpa.free(try rig.shOk(rig.work, try std.fmt.bufPrint(&script, "head -c 4096 /dev/urandom > page && dd if=page of={s}/f bs=4096 seek=5 conv=notrunc status=none && dd if=page of=pattern bs=4096 seek=5 conv=notrunc status=none && sync -f {s}", .{ rig.mp, rig.mp })));
    try aioRandomReads(f, pattern, 6 * 4096, 32, 4, 4);
    const t3 = try rig.stats();
    defer gpa.free(t3);
    try testing.expect(numberAfter(t3, "\"read_view_stale\":").? > numberAfter(t2, "\"read_view_stale\":").?);
    try expectMustStayZero(t3);
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// The streaming overwrite row's shape: one job, QD16, 1 MiB O_DIRECT
/// sequential writes over a laid-down file, time-based — the perf matrix's
/// `sw1m-q16j1`. 16 writes of ONE ino in flight on the one FUSE queue the
/// submitter's CPU binds, so two of them share a handler lane as a rule.
const stream_file_mib: u64 = 1024;
const stream_depth: usize = 16;
const stream_write_len: usize = 1 << 20;
const stream_secs: u64 = 12;
/// The writer's wall bound: the row's verdict when the daemon wedges
/// (`timeout -s KILL`), well inside the shard's hang limit.
const stream_bound_s: u32 = 90;

/// The smoke's own QD16 streaming overwriter (kernel aio, no fio): `depth`
/// PWRITEs of `len` each per `io_submit`, every event's `res` the write,
/// the stride advancing through `file_len` and wrapping, for `secs`.
/// Returns the bytes written.
fn aioStreamOverwrite(path: [:0]const u8, file_len: u64, depth: usize, len: usize, secs: u64) !u64 {
    const aio = @import("../shim/aio.zig");
    var ctx: aio.io_context_t = 0;
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.syscall2(.io_setup, @intCast(depth), @intFromPtr(&ctx))));
    defer _ = linux.syscall1(.io_destroy, ctx);
    const rc = linux.open(path.ptr, .{ .ACCMODE = .WRONLY, .DIRECT = true, .CLOEXEC = true }, 0);
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(rc));
    const fd: linux.fd_t = @intCast(rc);
    defer _ = linux.close(fd);
    const gpa = testing.allocator;
    const buf = try gpa.alignedAlloc(u8, .fromByteUnits(4096), depth * len);
    defer gpa.free(buf);
    for (0..depth) |i| @memset(buf[i * len ..][0..len], @as(u8, @truncate(0x40 + i)));
    const cbs = try gpa.alloc(aio.Iocb, depth);
    defer gpa.free(cbs);
    const ptrs = try gpa.alloc(*aio.Iocb, depth);
    defer gpa.free(ptrs);
    const evs = try gpa.alloc(aio.IoEvent, depth);
    defer gpa.free(evs);
    const deadline = clock.monotonicNs() + secs * std.time.ns_per_s;
    var off: u64 = 0;
    var written: u64 = 0;
    while (clock.monotonicNs() < deadline) {
        for (cbs, 0..) |*cb, i| {
            cb.* = .{ .data = i, .key = 0, .aio_rw_flags = 0, .aio_lio_opcode = aio.IOCB_CMD_PWRITE, .aio_reqprio = 0, .aio_fildes = fd, .buf = @intFromPtr(buf.ptr + i * len), .nbytes = len, .offset = @intCast(off), .__pad3 = 0, .flags = 0, .resfd = 0 };
            ptrs[i] = cb;
            off += len;
            if (off >= file_len) off = 0;
        }
        try testing.expectEqual(depth, linux.syscall3(.io_submit, ctx, depth, @intFromPtr(ptrs.ptr)));
        var got: usize = 0;
        while (got < depth) {
            const ts: linux.timespec = .{ .sec = @intCast(stream_bound_s), .nsec = 0 };
            const r = linux.syscall5(.io_getevents, ctx, 1, depth - got, @intFromPtr(evs.ptr + got), @intFromPtr(&ts));
            try testing.expectEqual(linux.E.SUCCESS, linux.errno(r));
            // A timed-out getevents with writes still owed IS the wedge.
            try testing.expect(r > 0);
            got += r;
        }
        for (evs) |ev| try testing.expectEqual(@as(i64, @intCast(len)), ev.res);
        written += depth * len;
    }
    return written;
}

test "smoke: A STREAMING OVERWRITE NEVER WEDGES THE DAEMON — format (no write cache), one 1 GiB file laid down, then ONE job's QD16 1 MiB sequential O_DIRECT overwrite of it (fio where present, else the smoke's kernel-aio writer) long enough to drain the fresh supply and run on block-grant top-ups: every write answered inside the row's bound, fuse_op_watchdog_overdue 0, lock_ticked_reregisters 0, the gauges clean, an orderly unmount (rung-10-fsync-route: a top-up winner parked on its journal ticket under a same-lane minter's spin)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const rig = try Rig.init(testing.allocator, io);
    defer rig.deinit();
    const gpa = rig.gpa;
    try rig.formatSet(false);
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    // The lay-down: the file's blocks owned, and the set filled to the
    // fill fraction so the fresh supply drains within the row and the
    // window runs on the frees the reclaimer returns — small grants, a
    // top-up every few mints.
    {
        var script: [384]u8 = undefined;
        const out = try rig.onMountTimed(try std.fmt.bufPrint(&script, "for f in ow fill0 fill1; do dd if=/dev/zero of=$f bs=1M count={d} oflag=direct status=none; done && echo lay-ok", .{stream_file_mib}), 2 * stream_bound_s);
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "lay-ok") != null);
    }
    const t0 = clock.monotonicNs();
    const has_fio = blk: {
        const r = try rig.sh(rig.work, "command -v fio >/dev/null 2>&1 && echo yes || echo no");
        defer rig.freeRun(r);
        break :blk std.mem.indexOf(u8, r.stdout, "yes") != null;
    };
    var written: u64 = 0;
    if (has_fio) {
        var script: [512]u8 = undefined;
        const out = try rig.onMountTimed(try std.fmt.bufPrint(&script, "fio --name=ow --filename=ow --rw=write --bs=1m --iodepth={d} --numjobs=1 --size={d}m --direct=1 --ioengine=io_uring --time_based --runtime={d} --output-format=terse --terse-version=3 | awk -F';' '{{print \"fio_write_kib=\" $47}}'", .{ stream_depth, stream_file_mib, stream_secs }), stream_bound_s);
        defer gpa.free(out);
        written = (numberAfter(out, "fio_write_kib=") orelse 0) << 10;
    } else {
        var path_buf: [192]u8 = undefined;
        written = try aioStreamOverwrite(try std.fmt.bufPrintSentinel(&path_buf, "{s}/ow", .{rig.mp}, 0), stream_file_mib << 20, stream_depth, stream_write_len, stream_secs);
    }
    const elapsed_ms = (clock.monotonicNs() - t0) / std.time.ns_per_ms;
    try rig.expectAlive("the streaming overwrite");
    // The row's verdict is the daemon's own posture, not the writer's
    // return: a wedged lane shows as overdue ops and ticking locks even
    // when the writer's bound ended it.
    const tail = try rig.quiescentStatsTail();
    defer gpa.free(tail);
    const topups = numberAfter(tail, "\"block_grant_topups\":") orelse 0;
    const overdue = numberAfter(tail, "\"fuse_op_watchdog_overdue\":") orelse 0;
    const lock_ticks = numberAfter(tail, "\"lock_ticked_reregisters\":") orelse 0;
    std.debug.print("\nsmoke: streaming overwrite ({s}, QD{d} × 1 MiB, {d} s): {d} MiB written ({d} MB/s), block-grant top-ups {d} (waits {d}), watchdog overdue {d}, lock ticks {d}\n", .{ if (has_fio) "fio" else "kernel aio", stream_depth, stream_secs, written >> 20, if (elapsed_ms == 0) 0 else written * 1000 / (elapsed_ms * std.time.ns_per_ms), topups, numberAfter(tail, "\"block_grant_topup_waits\":") orelse 0, overdue, lock_ticks });
    // The shape was exercised: the window ran on top-ups.
    try testing.expect(topups > 0);
    try testing.expectEqual(@as(u64, 0), overdue);
    try testing.expectEqual(@as(u64, 0), lock_ticks);
    try expectMustStayZero(tail);
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// The promotions a file takes out of the ring (or inline) to its own
/// block: the filesystem's at a write past the block, the plane's dispatch
/// (ring pressure, fsync, dismount) onto its own-block arm.
const Promotions = struct {
    by_write: u64,
    by_plane: u64,

    fn total(self: Promotions) u64 {
        return self.by_write + self.by_plane;
    }
};

fn promotionsToStriped(tail: []const u8) Promotions {
    return .{ .by_write = numberAfter(tail, "\"fuse_write_promotions_to_striped\":") orelse 0, .by_plane = numberAfter(tail, "\"layout_promoted_block\":") orelse 0 };
}

// The looped single-stage repro (`SQUEEZEFS_TEST_SMOKE_STAGE_LOOPS=N`):
// the cache-path set, `big` laid down and shaped once, then N passes of
// the 4 KiB overwrite stage (distinct source pages each pass, `cmp`
// against the mirror) and N passes of the 8-way storm, every pass under
// a wall bound and followed by the quiescent must-stay-0 census (the
// drift and double-free tripwires through `invariant_tripwires`, the
// ticked channel parks, the watchdog's overdue observations). The
// 2026-10-07 lost overwrite showed in ~1 run of 12 of the single pass.
test "smoke: the cache-path overwrite and storm stages LOOPED — 0 lost overwrites, 0 drift, 0 ticked channel parks, 0 watchdog reports over every pass" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    var env = try testing.environ.createMap(gpa);
    defer env.deinit();
    const raw = env.get(smoke_loops_knob) orelse return testkit.skip(@src(), .no_seam, smoke_loops_knob ++ " unset: the looped single-stage repro runs only when the harness arms it");
    const loops = std.fmt.parseInt(u32, std.mem.trim(u8, raw, " \t"), 10) catch return testkit.skip(@src(), .no_seam, smoke_loops_knob ++ " is not an integer");
    if (loops == 0) return testkit.skip(@src(), .no_seam, smoke_loops_knob ++ " is 0");
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    try rig.createImage();
    try rig.mountAsSet(&.{});
    _ = try rig.awaitReady(0);
    {
        const out = try rig.onMountTimed(stage_dd_script, stage_loop_timeout_s);
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "stage-dd-ok") != null);
    }
    {
        const out = try rig.onMountTimed(stage_truncate_script, stage_loop_timeout_s);
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "stage-truncate-ok") != null);
    }
    var pass: u32 = 0;
    while (pass < loops) : (pass += 1) {
        const script = try overwriteScript(gpa, overwrites_aligned, overwrites_unaligned, overwrite_seed +% pass);
        defer gpa.free(script);
        const t0 = clock.monotonicNs();
        const out = try rig.onMountTimed(script, stage_loop_timeout_s);
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "stage-overwrite-ok") != null);
        const tail = try rig.quiescentStatsTail();
        defer gpa.free(tail);
        try expectMustStayZero(tail);
        try expectOpLatencyWithin(tail, op_latency_bound);
        std.debug.print("smoke[loop]: overwrite pass {d}/{d}: image-exact in {d} ms; drift {d}, untracked frees {d}, channel ticks {d}, watchdog overdue {d}\n", .{ pass + 1, loops, (clock.monotonicNs() - t0) / std.time.ns_per_ms, numberAfter(tail, "\"rewrite_shadow_displaced_drift\":") orelse 0, numberAfter(tail, "\"block_untracked_free_refusals\":") orelse 0, numberAfter(tail, "\"channel_ticked_reregisters\":") orelse 0, numberAfter(tail, "\"fuse_op_watchdog_overdue\":") orelse 0 });
    }
    // Every storm pass writes FRESH files (the previous pass's removed
    // first: the storm's destroys ride the loop too), so each pass takes
    // its eight promotions out of the ring, by either arm.
    pass = 0;
    var promoted = blk: {
        const tail = try rig.quiescentStatsTail();
        defer gpa.free(tail);
        break :blk promotionsToStriped(tail);
    };
    while (pass < loops) : (pass += 1) {
        const rm = try rig.onMountTimed("rm -f storm0 storm1 storm2 storm3 storm4 storm5 storm6 storm7\nsync -f .\n", stage_loop_timeout_s);
        gpa.free(rm);
        const t0 = clock.monotonicNs();
        const out = try rig.onMountTimed(stage_storm_script, stage_loop_timeout_s);
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "stage-storm-ok") != null);
        const tail = try rig.quiescentStatsTail();
        defer gpa.free(tail);
        try expectMustStayZero(tail);
        try expectLedgersClosed(tail);
        try expectOpLatencyWithin(tail, op_latency_bound);
        const now = promotionsToStriped(tail);
        try testing.expect(now.total() - promoted.total() >= storm_files);
        std.debug.print("smoke[loop]: storm pass {d}/{d}: {d} MB/s aggregate in {d} ms; promotions {d} by the write path + {d} by the plane; channel ticks {d}, watchdog overdue {d}, joins {d}, close waits {d}\n", .{ pass + 1, loops, mbPerS(out, "storm_ns=", storm_files * (storm_mib << 20)), (clock.monotonicNs() - t0) / std.time.ns_per_ms, now.by_write - promoted.by_write, now.by_plane - promoted.by_plane, numberAfter(tail, "\"channel_ticked_reregisters\":") orelse 0, numberAfter(tail, "\"fuse_op_watchdog_overdue\":") orelse 0, numberAfter(tail, "\"write_pipeline_joins\":") orelse 0, numberAfter(tail, "\"rewrite_shadow_close_waits\":") orelse 0 });
        promoted = now;
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

// ---- the kill matrix ----

/// The page census of a file against its image slice after a crash.
const Census = struct { size: u64, exact: u64, holes: u64 };

/// Every `census_grain` page inside the claimed size is byte-exact against
/// the image at `src_off + page` or all zeros; anything else is TORN.
fn pageCensus(gpa: std.mem.Allocator, io: Io, dir: Io.Dir, name: []const u8, image: Io.File, src_off: u64, written_cap: u64) !Census {
    const f = try dir.openFile(io, name, .{});
    defer f.close(io);
    const size = (try f.stat(io)).size;
    if (size > written_cap) {
        std.debug.print("\n--- {s}: {d} B claimed, {d} B written ---\n", .{ name, size, written_cap });
        return error.SizeBeyondWritten;
    }
    const piece: usize = 1 << 20;
    const got = try gpa.alloc(u8, piece);
    defer gpa.free(got);
    const want = try gpa.alloc(u8, piece);
    defer gpa.free(want);
    var out: Census = .{ .size = size, .exact = 0, .holes = 0 };
    var off: u64 = 0;
    while (off < size) : (off += piece) {
        const n: usize = @intCast(@min(piece, size - off));
        if (try f.readPositionalAll(io, got[0..n], off) != n) return error.ShortRead;
        if (try image.readPositionalAll(io, want[0..n], src_off + off) != n) return error.ShortRead;
        var p: usize = 0;
        while (p < n) : (p += census_grain) {
            const e = @min(p + census_grain, n);
            if (std.mem.eql(u8, got[p..e], want[p..e])) {
                out.exact += 1;
            } else if (std.mem.allEqual(u8, got[p..e], 0)) {
                out.holes += 1;
            } else {
                std.debug.print("\n--- {s}: page at {d} is neither the image nor a hole ---\n", .{ name, off + p });
                return error.TornFile;
            }
        }
    }
    return out;
}

fn fileSize(path: [:0]const u8) u64 {
    var st: linux.Statx = undefined;
    if (linux.errno(linux.statx(linux.AT.FDCWD, path.ptr, 0, .{ .SIZE = true }, &st)) != .SUCCESS) return 0;
    return st.size;
}

/// What a remount after a kill reports.
const Recovery = struct { replayed: u64, torn: u64, ring_records: u64, ring_torn: u64 };

/// OUR oracle after a kill (charter §1.10 "fsck clean after every kill"):
/// `squeezefs fsck --offline --scrub` over the unmounted set — the D0
/// guarded open replays the ring, then C1–C17 and the scrub must report
/// `findings: 0 (clean)` with exit 0.
fn fsckClean(rig: *Rig, label: []const u8) !Recovery {
    // The metadata image as the kill left it: fsck's guarded open replays
    // and checkpoints it in place, so a refusal's evidence is this copy.
    rig.freeRunOk(try rig.sh(rig.work, "cp --sparse=always vol.img vol.prefsck.img"));
    const r = try rig.squeezefs(&.{ "fsck", "--offline", "--scrub", rig.meta_uri });
    defer rig.freeRun(r);
    if (!r.term.success() or std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") == null) {
        std.debug.print("\n--- fsck --offline after {s} ({f}) ---\n{s}\n--- stderr ---\n{s}\n", .{ label, r.term, r.stdout, r.stderr });
        rig.keepRefusedImage();
        return error.FsckNotClean;
    }
    std.debug.print("smoke[kill]: fsck --offline --scrub after {s}: {s}", .{ label, r.stdout[0 .. std.mem.indexOfScalar(u8, r.stdout, '\n') orelse r.stdout.len] });
    std.debug.print(" → findings: 0 (clean)\n", .{});
    // fsck's guarded open IS the post-kill recovery (the replay, the ring)
    // and its close checkpoints: the recovery numbers are its log's.
    return recoveryOf(r.stderr);
}

fn recoveryOf(seg: []const u8) !Recovery {
    const torn_at = std.mem.indexOf(u8, seg, "content records, ") orelse return error.NoReplayLine;
    return .{
        .replayed = numberAfter(seg, "replayed ") orelse 0,
        .torn = numberAfter(seg[torn_at..], "content records, ") orelse 0,
        .ring_records = numberAfter(seg, "recovered ") orelse 0,
        .ring_torn = if (std.mem.indexOf(u8, seg, "record(s) (")) |i| (numberAfter(seg[i..], "), ") orelse 0) else 0,
    };
}

/// Remount with the C8 oracle armed: zero drift (C8) and nothing leaked
/// or lost (C2) on both volumes. `recovered` = the replay fsck's guarded
/// open already performed (its close checkpointed, so THIS open is clean
/// by design); null = this open replays and its numbers are read here.
/// `posture` = the killed mount's: a supervised kill's ring waits for a
/// supervised successor (a mount without a write cache refuses a held
/// ring, decision 0003 §BR.6).
fn remountAfterKill(rig: *Rig, recovered: ?Recovery, posture: MountPosture) !Recovery {
    const mark = try rig.logLen();
    switch (posture) {
        .foreground => try rig.spawnMount(&.{}),
        .supervised => try rig.spawnSupervised(&.{}),
    }
    const ready = try rig.awaitReady(mark);
    const text = try rig.readLog();
    defer rig.gpa.free(text);
    const seg = text[mark..ready];
    if (recovered == null) try testing.expect(std.mem.indexOf(u8, seg, ", clean unmount") == null);
    if (std.mem.count(u8, seg, " 0 drift row(s)") != 2 or std.mem.count(u8, seg, ": 0 leaked block(s) freed, 0 lost block(s)") != 2) {
        std.debug.print("\n--- the oracles after the kill ---\n{s}\n", .{seg});
        return error.DriftAfterKill;
    }
    return recovered orelse try recoveryOf(seg);
}

/// The unsupervised row's files: `unsup_files` × `unsup_mib` MiB, each a
/// slice of the image, written and closed, never synced — 3 MiB, so the
/// old posture staged each whole (a block's worth at most).
const unsup_files: usize = 8;
const unsup_mib: u64 = 3;

/// One `mount` of the rig's set under `env_pct` (null: the knob unset) with
/// `argv_head` before the URI, bounded by `timeout` (a foreground mount
/// that is NOT refused would serve forever): its result.
fn mountUnderKnob(rig: *Rig, argv_head: []const []const u8, env_pct: ?[]const u8) !std.process.RunResult {
    var argv: [16][]const u8 = undefined;
    var n: usize = 0;
    for ([_][]const u8{ "timeout", "-s", "KILL", "20", rig.bin, "mount" }) |a| {
        argv[n] = a;
        n += 1;
    }
    for (argv_head) |a| {
        argv[n] = a;
        n += 1;
    }
    argv[n] = rig.meta_uri;
    argv[n + 1] = rig.mp;
    n += 2;
    if (env_pct) |v| try rig.env.put("SQUEEZEFS_WRITE_CACHE_PCT", v) else _ = rig.env.swapRemove("SQUEEZEFS_WRITE_CACHE_PCT");
    defer _ = rig.env.swapRemove("SQUEEZEFS_WRITE_CACHE_PCT");
    return std.process.run(rig.gpa, rig.io, .{ .argv = argv[0..n], .environ_map = &rig.env });
}

test "smoke: NO WRITE CACHE WITHOUT A SUPERVISOR (charter §6.1, decision 0003 §BR.6) — a FOREGROUND mount of a set in the write cache's default posture runs with the write cache OFF, said once at mount (`.stats`: data_staging_on 0, write_cache_off_unsupervised 1); 8 files of 3 MiB written and closed, never synced, their write-back custody drained and the directory fsync'd (every size durable) → kill -9 → fsck clean → remount: every file whole, byte for byte — no size ahead of its bytes; `SQUEEZEFS_WRITE_CACHE_PCT=25` on a foreground mount and on `--daemon` without `--supervise` is REFUSED at startup naming the reason, nothing mounted; the same knob under `--daemon --supervise` mounts with the write cache ON (red on 885727b: the foreground mount staged every file in a ring that died with it — the files read zeros under their durable 3 MiB sizes — and both unsupervised mounts with the knob came up)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    try rig.createImage();
    const image = try Io.Dir.cwd().openFile(io, rig.image, .{});
    defer image.close(io);
    // Every arm is judged at the end (each red names itself first).
    // 1. The foreground mount: the write cache off, said once.
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    const posture = blk: {
        const st = try rig.stats();
        defer gpa.free(st);
        const text = try rig.readLog();
        defer gpa.free(text);
        break :blk .{ .on = numberAfter(st, "\"data_staging_on\":"), .off = numberAfter(st, "\"write_cache_off_unsupervised\":"), .said = std.mem.count(u8, text, "no supervisor holds a write cache's ring: the write cache is off") };
    };
    std.debug.print("\nsmoke[unsupervised]: data_staging_on {?d}, write_cache_off_unsupervised {?d}, said {d} time(s)\n", .{ posture.on, posture.off, posture.said });
    {
        var script: [256]u8 = undefined;
        const out = try rig.onMount(try std.fmt.bufPrint(&script, "i=0; while [ $i -lt {d} ]; do dd if=\"$1/image\" of=f$i bs=1M skip=$((i * {d})) count={d} status=none; i=$((i + 1)); done; echo ok", .{ unsup_files, unsup_mib, unsup_mib }));
        defer gpa.free(out);
    }
    // The write-back custody lands within its bound and the extensions'
    // size claims drain after their bytes (§AL.5): wait for the
    // observables, then make every committed size durable with the
    // directory's fsync (no file is synced: no promotion, no sync point).
    {
        const deadline = clock.monotonicNs() + 30 * std.time.ns_per_s;
        while (true) {
            const st = try rig.stats();
            defer gpa.free(st);
            const parked = (numberAfter(st, "\"parked_buffers\":") orelse 0) + (numberAfter(st, "\"parked_extent_bytes\":") orelse 0) + (numberAfter(st, "\"overlay_open\":") orelse 0);
            const pending = numberAfter(st, "\"meta_kv_times_echo_pending\":") orelse 0;
            if (parked == 0 and pending == 0) break;
            if (clock.monotonicNs() >= deadline) {
                std.debug.print("\nsmoke[unsupervised]: the write-back custody never drained (parked {d}, pending {d})\n", .{ parked, pending });
                return error.CustodyNotDrained;
            }
            sleepMs(20);
        }
        const out = try rig.onMount("python3 -c 'import os; fd = os.open(\".\", os.O_RDONLY); os.fsync(fd)' && echo ok");
        defer gpa.free(out);
    }
    rig.killed = true;
    _ = linux.kill(rig.child_pid, .KILL);
    try testing.expectEqual(std.process.Child.Term{ .signal = .KILL }, try rig.waitChild());
    try rig.umountAfterKill();
    _ = try fsckClean(rig, "the unsupervised kill");
    {
        const mark = try rig.logLen();
        try rig.spawnMount(&.{});
        _ = try rig.awaitReady(mark);
    }
    const whole = census: {
        var dir = try Io.Dir.cwd().openDir(io, rig.mp, .{});
        defer dir.close(io);
        var whole: usize = 0;
        for (0..unsup_files) |i| {
            var nb: [16]u8 = undefined;
            const name = try std.fmt.bufPrint(&nb, "f{d}", .{i});
            const c = try pageCensus(gpa, io, dir, name, image, (i * unsup_mib) << 20, unsup_mib << 20);
            if (c.size == unsup_mib << 20 and c.holes == 0) whole += 1 else std.debug.print("\nsmoke[unsupervised]: {s} after the kill: {d} B, {d} pages exact, {d} zero pages under its size\n", .{ name, c.size, c.exact, c.holes });
        }
        std.debug.print("smoke[unsupervised]: after kill -9 of the foreground mount: {d} of {d} acked, closed files whole\n", .{ whole, unsup_files });
        break :census whole;
    };
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    _ = try fsckClean(rig, "the unsupervised arm's clean unmount");
    // 2. The knob by name without a supervisor: refused, nothing mounted.
    var refused: usize = 0;
    for ([_][]const []const u8{ &.{}, &.{ "--daemon", "--log-file", rig.log_path } }) |head| {
        const r = try mountUnderKnob(rig, head, "25");
        defer rig.freeRun(r);
        const mounted = try fuseMountsOf(gpa, io, rig.mp);
        std.debug.print("smoke[unsupervised]: SQUEEZEFS_WRITE_CACHE_PCT=25 `mount{s}`: {f}, {d} mount(s): {s}\n", .{ if (head.len == 0) "" else " --daemon", r.term, mounted, r.stderr });
        if (mounted != 0) {
            const u = try rig.squeezefs(&.{ "umount", rig.mp });
            rig.freeRun(u);
            _ = linux.umount2(rig.mp.ptr, linux.MNT.DETACH);
        }
        if (!r.term.success() and mounted == 0 and std.mem.indexOf(u8, r.stderr, "no supervisor to hold its ring") != null) refused += 1;
    }
    try testing.expectEqual(@as(?u64, 0), posture.on);
    try testing.expectEqual(@as(?u64, 1), posture.off);
    try testing.expectEqual(@as(usize, 1), posture.said);
    try testing.expectEqual(unsup_files, whole);
    try testing.expectEqual(@as(usize, 2), refused);
    // 3. Under a supervisor the same knob mounts with the write cache on.
    {
        try rig.env.put("SQUEEZEFS_WRITE_CACHE_PCT", "25");
        defer _ = rig.env.swapRemove("SQUEEZEFS_WRITE_CACHE_PCT");
        const mark = try rig.logLen();
        const pid = try daemonMountReady(rig, mark);
        {
            const st = try rig.stats();
            defer gpa.free(st);
            try testing.expectEqual(@as(?u64, 1), numberAfter(st, "\"data_staging_on\":"));
            try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"write_cache_off_unsupervised\":"));
        }
        try umountDaemon(rig, pid);
    }
    _ = try fsckClean(rig, "the supervised arm");
}

test "smoke: THE KILL MATRIX — kill -9 at 50/100/150 MiB of a 200 MiB dd and mid 8-way cp storm → fsck --offline clean → remount → every fsync'd file byte-exact, every page of an in-flight file exact or a hole, C8 zero drift, C2 nothing leaked or lost, rm → df baseline → fsck clean → status" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    try rig.createImage();
    // The C8 oracle at every mount of this test (the A/B lever).
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    const image = try Io.Dir.cwd().openFile(io, rig.image, .{});
    defer image.close(io);
    const storm_sources = try rig.shOk(rig.work, "i=0; while [ $i -lt 8 ]; do dd if=image of=s$i bs=1M skip=$((i * 25)) count=50 status=none; i=$((i + 1)); done; echo ok");
    gpa.free(storm_sources);

    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    const baseline = try rig.usedKib();
    var acked: usize = 0;
    var pb: [256:0]u8 = undefined;
    // Three mid-dd kills.
    for (kill_points_mib, 0..) |point, k| {
        // The acked file: 8 MiB from the image at a distinct offset, fsync returned.
        {
            var script: std.Io.Writer.Allocating = .init(gpa);
            defer script.deinit();
            try script.writer.print("dd if=\"$1/image\" of=acked{d} bs=1M skip={d} count={d} conv=fsync status=none && echo acked-ok", .{ k, 8 * k, acked_mib });
            const out = try rig.onMount(script.written());
            defer gpa.free(out);
            try testing.expect(std.mem.indexOf(u8, out, "acked-ok") != null);
            acked += 1;
        }
        const inflight = try std.fmt.bufPrintSentinel(&pb, "{s}/inflight{d}", .{ rig.mp, k }, 0);
        // Half the kill point fsynced, the rest streamed unsynced: the
        // fsync is the size's durability point (decision 0003 §AL.5).
        const synced_mib = point / 2;
        var dd_script: [768]u8 = undefined;
        const dd_cmd = try std.fmt.bufPrint(&dd_script, "dd if={s} of={s} bs=1M count={d} conv=fsync status=none && dd if={s} of={s} bs=1M skip={d} seek={d} count={d} conv=notrunc status=none", .{ rig.image, inflight, synced_mib, rig.image, inflight, synced_mib, synced_mib, big_mib - synced_mib });
        var dd = try std.process.spawn(io, .{ .argv = &.{ "sh", "-c", dd_cmd }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore });
        var claimed: u64 = 0;
        {
            const deadline = clock.monotonicNs() + 60 * std.time.ns_per_s;
            while (clock.monotonicNs() < deadline) {
                claimed = fileSize(inflight);
                if (claimed >= point << 20) break;
                sleepMs(1);
            }
        }
        try testing.expect(claimed >= point << 20);
        _ = linux.kill(rig.child_pid, .KILL);
        try testing.expectEqual(std.process.Child.Term{ .signal = .KILL }, try rig.waitChild());
        try testing.expect(!(try dd.wait(io)).success());
        try rig.umountAfterKill();
        const recovered = try fsckClean(rig, "the mid-dd kill");
        const rec = try remountAfterKill(rig, recovered, .foreground);
        // Every acked file byte-exact; the in-flight file exact or holes.
        var dir = try Io.Dir.cwd().openDir(io, rig.mp, .{});
        defer dir.close(io);
        for (0..acked) |a| {
            var nb: [32]u8 = undefined;
            const name = try std.fmt.bufPrint(&nb, "acked{d}", .{a});
            const c = try pageCensus(gpa, io, dir, name, image, (8 * a) << 20, acked_mib << 20);
            try testing.expectEqual(acked_mib << 20, c.size);
            try testing.expectEqual(@as(u64, 0), c.holes);
        }
        var nb: [32]u8 = undefined;
        const in_name = try std.fmt.bufPrint(&nb, "inflight{d}", .{k});
        // THE ORDERED LAW (decision 0003 §AL.5, §AJ.4): the size ends at
        // its last durable claim — `fsynced ≤ size ≤ bytes dd could have
        // written`; the unsynced extension is whole or absent (it lags the
        // claim stat saw by the landing bound plus one drain) — and never
        // covers a byte the kill took from RAM: every page below it is the
        // image's, no hole (the size never leads its bytes).
        const c = try pageCensus(gpa, io, dir, in_name, image, 0, big_mib << 20);
        std.debug.print("\nsmoke[kill]: dd killed at {d} MiB claimed (point {d} MiB, {d} MiB fsynced): replayed {d} entries ({d} torn dropped), ring {d} record(s) ({d} torn); inflight{d} durable at {d} B: {d} pages exact, {d} holes, 0 torn; {d} acked file(s) byte-exact; C8 0 drift, C2 0/0\n", .{ claimed >> 20, point, synced_mib, rec.replayed, rec.torn, rec.ring_records, rec.ring_torn, k, c.size, c.exact, c.holes, acked });
        try testing.expect(c.size >= synced_mib << 20);
        try testing.expectEqual(@as(u64, 0), c.holes);
        {
            const out = try rig.onMount("rm -f inflight* && echo ok");
            defer gpa.free(out);
        }
    }
    // The storm kill under both postures of the write cache across a kill
    // -9 (charter §6.1 "Staged"): this foreground mount, then a `--daemon
    // --supervise` one after a clean cycle.
    try killMatrixStorm(rig, image, acked, .foreground);
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    try killMatrixStorm(rig, image, acked, .supervised);
    // rm everything → the baseline; the gauges; a clean cycle; status.
    {
        const out = try rig.onMount("rm -f acked* storm* inflight* && echo ok");
        defer gpa.free(out);
    }
    try rig.awaitUsedKib(baseline);
    {
        const tail = try rig.quiescentStatsTail();
        defer gpa.free(tail);
        try expectMustStayZero(tail);
        try expectLedgersClosed(tail);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    try testing.expectEqual(@as(usize, 0), try fuseMountsOf(gpa, io, rig.mp));
    _ = try fsckClean(rig, "the clean unmount");
    {
        const report = try rig.statusReport();
        defer gpa.free(report);
        try testing.expectEqual(@as(u64, 0), refCensus(report).blocks);
        try testing.expect(std.mem.indexOf(u8, report, "not mounted") != null);
        std.debug.print("smoke[kill]: {s}", .{report[std.mem.lastIndexOf(u8, report, "summary:").?..]});
    }
}

/// The mount's posture across a kill (charter §6.1 "Staged", decision
/// 0003 §BR.6): `foreground` — no supervisor, so no write cache: every
/// write goes to the data volumes under the write-back bound, and a crash
/// loses at most what had not landed — never a byte under a durable size
/// (§AL.5); `supervised` — the write cache on, the supervisor replays the
/// journal tail and hands the ring to the member's next (supervised)
/// mount: no staged byte the daemon acked is lost (the kill -9 law).
const MountPosture = enum { foreground, supervised };

/// The reach the staged arm rings whole — the set's block (the format
/// default, 4 MiB): a layout naming a ring record claims at most this.
const staged_reach: u64 = 4 << 20;

/// The resident the storm kill always finds: closed, never synced —
/// nothing promotes it before the kill (no write past the block, no fsync,
/// a ring far under its bound), so every run meets the posture's law, not
/// only one whose kill lands before a cp's promotion. Its bytes are the
/// image's past every storm source. 3 MiB: over half the block, so a stray
/// promotion (a host-wide sync(2) reaches every FUSE mount as SYNCFS)
/// takes its own block, never a packed slot whose open pack keeps its
/// block until the dismount seal (the row's df baseline).
const storm_resident_off_mib: u64 = 240;
const storm_resident_mib: u64 = 3;
comptime {
    if (storm_resident_off_mib < (storm_files - 1) * storm_stride_mib + storm_mib or storm_resident_off_mib + storm_resident_mib > image_mib) @compileError("the storm kill's resident must lie past every storm source, inside the image");
    if (storm_resident_mib << 20 <= staged_reach / 2 or storm_resident_mib << 20 > staged_reach) @compileError("the storm kill's resident must be staged whole and promote to its own block");
}

/// The 8-way `cp` storm, killed once `storm_kill_mib` are claimed — the
/// KERNEL's sizes: its writeback cache runs them ahead of the daemon, which
/// has acked only the storm's first ~100 ms at the kill → fsck clean →
/// remount (in the same posture: a supervised kill's ring waits for a
/// supervised successor) → the census per file, judged by the posture. No
/// posture loses a staged read (`staged_payload_lost_reads` 0): the
/// foreground mount stages nothing, the supervised one hands its ring
/// over. After a FOREGROUND kill no page under a file's durable size reads
/// zeros (the size never ahead of its bytes — before the ruling, its ring
/// died with it and a staged image read 4 MiB of zeros under its landed
/// size, 6 of 240 copies beside the full smoke). After a SUPERVISED kill
/// the closed resident is exact. The acked files byte-exact; the storm
/// files and the resident are removed after.
fn killMatrixStorm(rig: *Rig, image: Io.File, acked: usize, posture: MountPosture) !void {
    const gpa = rig.gpa;
    const io = rig.io;
    var pb: [256:0]u8 = undefined;
    // The foreground storm runs on the rig's live mount; the supervised one
    // mounts its own.
    const ready_mark = try rig.logLen();
    if (posture == .supervised) try rig.spawnSupervised(&.{});
    const ready = if (posture == .supervised) try rig.awaitReady(ready_mark) else ready_mark;
    {
        const st = try rig.stats();
        defer gpa.free(st);
        try testing.expectEqual(@as(?u64, @intFromBool(posture == .supervised)), numberAfter(st, "\"data_staging_on\":"));
    }
    {
        var script: [160]u8 = undefined;
        const out = try rig.onMount(try std.fmt.bufPrint(&script, "dd if=\"$1/image\" of=resident bs=1M skip={d} count={d} status=none && echo ok", .{ storm_resident_off_mib, storm_resident_mib }));
        defer gpa.free(out);
    }
    var storm_cmd: [1024]u8 = undefined;
    const cmd = try std.fmt.bufPrint(&storm_cmd, "i=0; while [ $i -lt 8 ]; do cp {s}/s$i {s}/storm$i & i=$((i + 1)); done; wait", .{ rig.work, rig.mp });
    var storm = try std.process.spawn(io, .{ .argv = &.{ "sh", "-c", cmd }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore });
    var claimed: u64 = 0;
    {
        const deadline = clock.monotonicNs() + 60 * std.time.ns_per_s;
        while (clock.monotonicNs() < deadline) {
            claimed = 0;
            for (0..storm_files) |i| {
                const p = try std.fmt.bufPrintSentinel(&pb, "{s}/storm{d}", .{ rig.mp, i }, 0);
                claimed += fileSize(p);
            }
            if (claimed >= storm_kill_mib << 20) break;
            sleepMs(1);
        }
    }
    try testing.expect(claimed >= storm_kill_mib << 20);
    rig.killed = true;
    _ = linux.kill(rig.child_pid, .KILL);
    // A supervised daemon's term is its supervisor's line, logged after the
    // replay and the guard release: both come before fsck's open; the ring
    // waits for the remount.
    try testing.expectEqual(std.process.Child.Term{ .signal = .KILL }, try rig.waitChild());
    _ = try storm.wait(io);
    if (posture == .supervised) _ = try rig.awaitLog("exited (wait status 0x9); done", ready, 30 * std.time.ns_per_s);
    try rig.umountAfterKill();
    const recovered = try fsckClean(rig, switch (posture) {
        .foreground => "the storm kill (foreground)",
        .supervised => "the storm kill (supervised)",
    });
    const mark = try rig.logLen();
    const rec = try remountAfterKill(rig, recovered, posture);
    const ring_records = switch (posture) {
        .foreground => 0,
        .supervised => blk: {
            const text = try rig.readLog();
            defer gpa.free(text);
            const at = mark + (std.mem.indexOf(u8, text[mark..], " in a sealed memfd ") orelse return error.NoWriteCacheLine);
            break :blk numberAfter(text[at..], "recovered ") orelse return error.NoWriteCacheLine;
        },
    };
    var dir = try Io.Dir.cwd().openDir(io, rig.mp, .{});
    defer dir.close(io);
    var judge: StormJudge = .{ .rig = rig, .dir = dir, .image = image, .posture = posture, .lost = try stagedLostReads(rig) };
    try testing.expectEqual(@as(u64, 0), judge.lost);
    var present: usize = 0;
    var exact: u64 = 0;
    var holes: u64 = 0;
    var sizes: u64 = 0;
    for (0..storm_files) |i| {
        var nb: [32]u8 = undefined;
        const name = try std.fmt.bufPrint(&nb, "storm{d}", .{i});
        const c = (try judge.census(name, (i * storm_stride_mib) << 20, storm_mib << 20)) orelse continue;
        present += 1;
        exact += c.exact;
        holes += c.holes;
        sizes += c.size;
    }
    const resident = try judge.census("resident", storm_resident_off_mib << 20, storm_resident_mib << 20);
    // dd's close flushed the resident to the daemon, which acked it: a
    // supervised kill keeps it whole.
    if (posture == .supervised) try testing.expectEqual(@as(?u64, (storm_resident_mib << 20) / census_grain), if (resident) |c| c.exact else null);
    for (0..acked) |a| {
        var nb: [32]u8 = undefined;
        const name = try std.fmt.bufPrint(&nb, "acked{d}", .{a});
        const c = try pageCensus(gpa, io, dir, name, image, (8 * a) << 20, acked_mib << 20);
        try testing.expectEqual(acked_mib << 20, c.size);
        try testing.expectEqual(@as(u64, 0), c.holes);
    }
    try testing.expectEqual(@as(u64, 0), try stagedLostReads(rig));
    std.debug.print("smoke[kill]: storm killed at {d} MiB claimed ({t}): replayed {d} entries ({d} torn dropped), the remount recovered {d} ring record(s); {d} of 8 files present claiming {d} MiB: {d} pages exact, {d} holes, 0 torn; the resident {s}; staged_payload_lost_reads 0; {d} acked file(s) byte-exact; C8 0 drift, C2 0/0\n", .{ claimed >> 20, posture, rec.replayed, rec.torn, ring_records, present, sizes >> 20, exact, holes, if (resident) |c| (if (c.size == storm_resident_mib << 20) "whole" else if (c.size == 0) "empty" else "a prefix") else "absent", acked });
    {
        const out = try rig.onMount("rm -f storm* resident && echo ok");
        defer gpa.free(out);
    }
}

/// The storm census's per-file verdict: no posture loses a staged read
/// (the counter moved: the custody law broken), and after a FOREGROUND
/// kill no page under the durable size is a hole (the size never ahead of
/// its bytes, §AL.5); a supervised kill's pages are exact or holes.
const StormJudge = struct {
    rig: *Rig,
    dir: Io.Dir,
    image: Io.File,
    posture: MountPosture,
    lost: u64,

    /// The census of `name` (null: the file is absent), judged.
    fn census(self: *StormJudge, name: []const u8, src_off: u64, cap: u64) !?Census {
        const c = pageCensus(self.rig.gpa, self.rig.io, self.dir, name, self.image, src_off, cap) catch |e| switch (e) {
            error.FileNotFound => return null,
            else => return e,
        };
        const now = try stagedLostReads(self.rig);
        if (now != self.lost) {
            std.debug.print("\n--- {s} after the {t} kill: {d} staged read(s) lost over {d} B claimed, {d} pages exact ---\n", .{ name, self.posture, now - self.lost, c.size, c.exact });
            return error.StagedCustodyLost;
        }
        if (self.posture == .foreground and c.holes != 0) {
            std.debug.print("\n--- {s} after the foreground kill: {d} B durable, {d} pages exact, {d} zero pages under the size (the size ahead of its bytes) ---\n", .{ name, c.size, c.exact, c.holes });
            return error.SizeAheadOfBytes;
        }
        return c;
    }
};

/// The mount's `staged_payload_lost_reads`.
fn stagedLostReads(rig: *Rig) !u64 {
    const st = try rig.stats();
    defer rig.gpa.free(st);
    return numberAfter(st, "\"staged_payload_lost_reads\":") orelse error.NoLostReadsRow;
}

/// The staged-then-promoted file the dismount-residue row kills inside:
/// 4 MiB (one block) staged by fsync'd writes, then ONE write past the
/// block — the promotion to its own block, whose commit the seam kills
/// after (the ring record stays, the striped layout no longer names it).
const residue_stage_script = "dd if=\"$1/image\" of=$2 bs=1M count=4 status=none && echo staged-ok";
const residue_promote_script = "dd if=\"$1/image\" of=$2 bs=1M skip=4 seek=4 count=1 conv=notrunc status=none; echo promote-returned";

/// Mount with the kill seam (`--daemon --supervise`: the write cache is a
/// memfd the SUPERVISOR holds across the daemon's death and hands to the
/// member's next mount — a foreground mount's ring dies with it, charter
/// §6.1 "a mount without a supervisor has a power cut's exposure"), stage
/// `name` (no fsync: an fsync IS a promotion under the write cache's law —
/// the record must still be resident for the extending write to promote
/// it) and kill the daemon inside its promotion: the ring keeps the 4 MiB
/// record, the layout is striped.
fn killInsidePromotion(rig: *Rig, name: []const u8) !void {
    const gpa = rig.gpa;
    try rig.env.put("SQUEEZEFS_TEST_PROMOTE_KILL_AFTER_COMMIT", "1");
    defer rig.env.put("SQUEEZEFS_TEST_PROMOTE_KILL_AFTER_COMMIT", "0") catch {};
    const mark = try rig.logLen();
    {
        const r = try rig.squeezefs(&.{ "mount", "--daemon", "--supervise", "--log-file", rig.log_path, rig.meta_uri, rig.mp });
        defer rig.freeRun(r);
        if (!r.term.success()) std.debug.print("\ndaemon mount: {s}\n", .{r.stderr});
        try testing.expect(r.term.success());
    }
    const ready = try rig.awaitReady(mark);
    {
        const out = try rig.onMountArgv(residue_stage_script, &.{ "sh", "-e", "-c", residue_stage_script, "smoke", rig.work, name });
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "staged-ok") != null);
    }
    {
        // Tolerant: the daemon dies under this write (dd ends ENOTCONN).
        const r = try std.process.run(gpa, rig.io, .{ .argv = &.{ "sh", "-c", residue_promote_script, "smoke", rig.work, name }, .cwd = .{ .path = rig.mp }, .environ_map = &rig.env });
        defer rig.freeRun(r);
    }
    // The seam's SIGKILL: the supervisor reaps the daemon, replays the
    // tails and holds the ring (its record unreleased) for the successor.
    _ = try rig.awaitLog("exited (wait status 0x9); done", ready, 30 * std.time.ns_per_s);
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expect(std.mem.indexOf(u8, text[mark..], "TEST SEAM SQUEEZEFS_TEST_PROMOTE_KILL_AFTER_COMMIT") != null);
    }
    try rig.umountAfterKill();
}

/// The dismount pass's tally off a log segment: `(promoted, failed,
/// corpses, unnamed)` of its "dismount promotion:" line.
const DismountLine = struct { promoted: u64, failed: u64, corpses: u64, unnamed: u64 };

fn dismountLineOf(seg: []const u8) !DismountLine {
    const at = std.mem.indexOf(u8, seg, "dismount promotion: ") orelse return error.NoDismountPromotionLine;
    const line = seg[at..];
    const failed_at = std.mem.indexOf(u8, line, "promoted, ") orelse return error.NoDismountPromotionLine;
    return .{
        .promoted = numberAfter(line, "dismount promotion: ") orelse 0,
        .failed = numberAfter(line[failed_at..], "promoted, ") orelse 0,
        .corpses = numberAfter(line, "failed; ") orelse return error.NoDismountTally,
        .unnamed = numberAfter(line, "corpse record(s) and ") orelse return error.NoDismountTally,
    };
}

test "smoke: KILL -9 BETWEEN A PROMOTION'S COMMIT AND ITS RING RELEASE (the kill matrix's two-ring [C4]) — a 4 MiB staged file promoted to its own block, the daemon killed after the layout committed: (a) remount without fsck → rm → clean unmount destroys the corpse's record (0 FAILED) → fsck clean; (b) fsck --offline judges the device alone (the ring is the supervisor's custody) → the remount adopts the record its live file's layout no longer names → the file byte-exact → the clean unmount destroys it UNNAMED → the next mount recovers 0 → rm → fsck clean" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(true);
    try rig.createImage();
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    const image = try Io.Dir.cwd().openFile(io, rig.image, .{});
    defer image.close(io);
    try rig.spawnSupervised(&.{});
    const baseline = try rig.usedKib();
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());

    // (a) The corpse arm: the kill, the remount's own recovery adopts the
    //     record (no fsck between), the file is rm'd, the clean unmount's
    //     pass meets a record whose inode is gone.
    try killInsidePromotion(rig, "a");
    var mark = try rig.logLen();
    _ = try remountAfterKill(rig, null, .supervised);
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expectEqual(@as(u64, 1), numberAfter(text[mark..], "recovered ") orelse 0);
    }
    {
        const out = try rig.onMount("rm a && echo ok");
        defer gpa.free(out);
    }
    try rig.awaitUsedKib(baseline);
    mark = try rig.logLen();
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        const d = try dismountLineOf(text[mark..]);
        std.debug.print("\nsmoke[residue]: (a) the clean unmount after rm: {d} promoted, {d} FAILED, {d} corpse record(s), {d} unnamed record(s)\n", .{ d.promoted, d.failed, d.corpses, d.unnamed });
        try testing.expectEqual(DismountLine{ .promoted = 0, .failed = 0, .corpses = 1, .unnamed = 0 }, d);
    }
    _ = try fsckClean(rig, "the clean unmount after the corpse's rm");

    // (b) The unnamed arm: `fsck --offline` judges the device alone — it
    //     presents no member (no mount point, no write cache), so the ring
    //     stays the supervisor's custody, unseen — and the striped layout
    //     names the block: clean, nothing recovered. The remount adopts the
    //     record its live file's layout no longer names; the file is the
    //     layout's bytes; the clean unmount's pass destroys the record as
    //     UNNAMED; the next mount recovers 0.
    try killInsidePromotion(rig, "b");
    {
        rig.freeRunOk(try rig.sh(rig.work, "cp --sparse=always vol.img vol.prefsck.img"));
        const r = try rig.squeezefs(&.{ "fsck", "--offline", "--scrub", rig.meta_uri });
        defer rig.freeRun(r);
        if (!r.term.success() or std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") == null) {
            std.debug.print("\n--- fsck --offline after the kill inside the promotion ({f}) ---\n{s}\n--- stderr ---\n{s}\n", .{ r.term, r.stdout, r.stderr });
            rig.keepRefusedImage();
            return error.FsckNotClean;
        }
        try testing.expect(std.mem.indexOf(u8, r.stderr, "recovered ") == null);
        try testing.expect(std.mem.indexOf(u8, r.stderr, "dismount promotion: ") == null);
        std.debug.print("smoke[residue]: (b) fsck --offline after the kill: clean; the ring untouched (the supervisor's custody)\n", .{});
    }
    mark = try rig.logLen();
    // The fsck's guarded open replayed and checkpointed: this open is clean
    // by design (the explicit form); the ring record is read here.
    _ = try remountAfterKill(rig, .{ .replayed = 0, .torn = 0, .ring_records = 1, .ring_torn = 0 }, .supervised);
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expectEqual(@as(u64, 1), numberAfter(text[mark..], "recovered ") orelse 0);
        var dir = try Io.Dir.cwd().openDir(io, rig.mp, .{});
        defer dir.close(io);
        // The promotion's own block IS the file: the 4 MiB image, no hole.
        const c = try pageCensus(gpa, io, dir, "b", image, 0, 5 << 20);
        try testing.expectEqual(@as(u64, 4 << 20), c.size);
        try testing.expectEqual(@as(u64, 0), c.holes);
    }
    mark = try rig.logLen();
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        const d = try dismountLineOf(text[mark..]);
        std.debug.print("smoke[residue]: (b) the clean unmount: {d} promoted, {d} FAILED, {d} corpse record(s), {d} unnamed record(s)\n", .{ d.promoted, d.failed, d.corpses, d.unnamed });
        try testing.expectEqual(DismountLine{ .promoted = 0, .failed = 0, .corpses = 0, .unnamed = 1 }, d);
    }
    _ = try fsckClean(rig, "the clean unmount after the unnamed record");
    mark = try rig.logLen();
    try rig.spawnSupervised(&.{});
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expectEqual(@as(u64, 0), numberAfter(text[mark..], "recovered ") orelse 1);
    }
    {
        const out = try rig.onMount("rm b && echo ok");
        defer gpa.free(out);
    }
    try rig.awaitUsedKib(baseline);
    mark = try rig.logLen();
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    {
        const text = try rig.readLog();
        defer gpa.free(text);
        try testing.expectEqual(DismountLine{ .promoted = 0, .failed = 0, .corpses = 0, .unnamed = 0 }, try dismountLineOf(text[mark..]));
    }
    _ = try fsckClean(rig, "the clean unmount after the unnamed record's rm");
}

// ---- fsck / scrub: OUR oracle over a real set (rung 8) ----

/// `squeezefs fsck …` through the binary; the report's JSON, the exit code
/// and both streams (printed on a surprise).
fn fsckJson(rig: *Rig, extra: []const []const u8) !FsckOutcome {
    var argv: [12][]const u8 = undefined;
    var n: usize = 0;
    argv[n] = "fsck";
    n += 1;
    argv[n] = "--offline";
    n += 1;
    argv[n] = "--json";
    n += 1;
    for (extra) |a| {
        argv[n] = a;
        n += 1;
    }
    argv[n] = rig.meta_uri;
    n += 1;
    const r = try rig.squeezefs(argv[0..n]);
    defer rig.freeRun(r);
    const code: u8 = switch (r.term) {
        .exited => |c| c,
        else => 255,
    };
    const report = json_scan_report.Report.parse(rig.gpa, r.stdout) catch {
        std.debug.print("\n--- fsck ({f}) printed no report ---\n{s}\n--- stderr ---\n{s}\n", .{ r.term, r.stdout, r.stderr });
        return error.FsckNoReport;
    };
    return .{ .report = report, .code = code };
}

const json_scan_report = @import("../ops/fsck/finding.zig");

/// The fresh file of the `sync -f` row: one MiB and a 1000-byte sub-page
/// tail — a partial first block at every legal block size ≥ 2 MiB (the
/// default 4 MiB here), so the bytes sit parked in the accumulation table
/// until a drain; the tail ends off any page boundary.
const syncfs_fresh_bytes: u64 = (1 << 20) + 1000;
/// The fsync'd file the row overwrites in place: one default block.
const syncfs_base_bytes: u64 = 4 << 20;
/// The in-place overwrite at the base file's head: two pages, size-neutral
/// (its mtime is a parked stamp under the coalesced cadence, §L.6).
const syncfs_patch_bytes: u64 = 8192;

test "smoke: `sync -f` IS A DURABILITY POINT FOR THE DAEMON'S WRITE CUSTODY — format (no write cache: every write beyond inline striped) → mount → the test process holds `f` and `g` OPEN and closes neither (no RELEASE, no FLUSH drains them; it spawns nothing while it holds them): 1 MiB + 1000 B into the fresh `f` (a partial block parked in RAM), 8 KiB over the head of the fsync'd `g` (a size-neutral write: its mtime parked) → syncfs(2) on the mount returns → kill -9 the daemon → fsck --offline clean → remount → `f` is the image byte for byte, `g` carries the overwrite and the mtime the holder saw" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try rig.createImage();
    // The C8 oracle at every mount (the remount after the kill judges it).
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    // syncfs is the drain the row judges: the write-back timer (decision
    // 0003 §AJ) and the close posture's idle drain held ten minutes away.
    try rig.env.put("SQUEEZEFS_TEST_FUSE_OWED_IDLE_MS", "600000");
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    // The kernel forwards syncfs to a plain /dev/fuse server only once INIT
    // negotiated FUSE_HAS_SYNCFS (upstream 7.47; the venue's 7.2.6-sqz
    // through scripts/kernel/patches-7.2/0027): without it `sync -f` never
    // reaches the daemon and the row has nothing to judge.
    {
        const st = try rig.stats();
        defer gpa.free(st);
        if (numberAfter(st, "\"fuse_syncfs_armed\":") != 1) {
            const rel = try rig.shOk(rig.work, "uname -r");
            defer gpa.free(rel);
            try rig.umount();
            _ = try rig.waitChild();
            var detail: [192]u8 = undefined;
            return testkit.skip(@src(), .no_kernel_feature, std.fmt.bufPrint(&detail, "kernel {s}: FUSE_HAS_SYNCFS not offered — syncfs(2) never reaches a plain /dev/fuse server", .{std.mem.trimEnd(u8, rel, "\n")}) catch "a kernel without FUSE_HAS_SYNCFS");
        }
    }
    {
        var script: [256]u8 = undefined;
        const out = try rig.onMount(try std.fmt.bufPrint(&script, "dd if=\"$1/image\" of=g bs={d} count=1 conv=fsync status=none && echo base-ok", .{syncfs_base_bytes}));
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "base-ok") != null);
    }
    // The holder is THIS process: both fds stay open past the kill and no
    // fd of either file is ever closed before it — a close(2) of ANY fd (a
    // child's inherited copy too, closed at its exec even under CLOEXEC) is
    // a FLUSH, the no-open drain (decision 0003 §AF) — so nothing is
    // spawned while they are held and syncfs(2) is the only drain the
    // bytes meet.
    const head = try readImageRange(gpa, rig.image, 0, syncfs_fresh_bytes);
    defer gpa.free(head);
    const tail = try readImageRange(gpa, rig.image, (image_mib << 20) - syncfs_patch_bytes, syncfs_patch_bytes);
    defer gpa.free(tail);
    var path_buf: [256]u8 = undefined;
    const fd_f = try openRaw(try std.fmt.bufPrintSentinel(&path_buf, "{s}/f", .{rig.mp}, 0), .{ .ACCMODE = .WRONLY, .CREAT = true, .TRUNC = true, .CLOEXEC = true });
    defer _ = linux.close(fd_f);
    const fd_g = try openRaw(try std.fmt.bufPrintSentinel(&path_buf, "{s}/g", .{rig.mp}, 0), .{ .ACCMODE = .RDWR, .CLOEXEC = true });
    defer _ = linux.close(fd_g);
    try pwriteAll(fd_f, head, 0);
    try pwriteAll(fd_g, tail, 0);
    var g_path_buf: [256]u8 = undefined;
    const g_path = try std.fmt.bufPrintSentinel(&g_path_buf, "{s}/g", .{rig.mp}, 0);
    const seen_mtime = try mtimeOf(g_path);
    // `sync -f <mnt>` is syncfs(2) on an fd of the mount.
    try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.syncfs(fd_f)));
    // The daemon served the syncfs and its census found the parked block.
    {
        const st = try rig.stats();
        defer gpa.free(st);
        std.debug.print("\nsmoke[sync -f]: fuse_syncfs {d}, custody inos {d}, parked blocks flushed {d}\n", .{ numberAfter(st, "\"fuse_syncfs\":") orelse 0, numberAfter(st, "\"syncfs_custody_inos\":") orelse 0, numberAfter(st, "\"syncfs_parked_blocks\":") orelse 0 });
        try testing.expect((numberAfter(st, "\"fuse_syncfs\":") orelse 0) >= 1);
        try testing.expect((numberAfter(st, "\"syncfs_parked_blocks\":") orelse 0) >= 1);
    }
    try rig.kill();
    const recovered = try fsckClean(rig, "the kill after sync -f");
    _ = try remountAfterKill(rig, recovered, .foreground);
    var check: [768]u8 = undefined;
    const out = try rig.onMount(try std.fmt.bufPrint(&check, "if head -c {d} \"$1/image\" | cmp -s - f; then echo f-whole; else echo f-LOST; fi; if {{ tail -c {d} \"$1/image\"; head -c {d} \"$1/image\" | tail -c +{d}; }} | cmp -s - g; then echo g-whole; else echo g-LOST; fi", .{ syncfs_fresh_bytes, syncfs_patch_bytes, syncfs_base_bytes, syncfs_patch_bytes + 1 }));
    defer gpa.free(out);
    const after_mtime = try mtimeOf(g_path);
    std.debug.print("\nsmoke[sync -f]: after the kill and the remount: {s}; g's mtime {d}.{d:0>9} (the holder saw {d}.{d:0>9})\n", .{ std.mem.trimEnd(u8, out, "\n"), after_mtime.sec, after_mtime.nsec, seen_mtime.sec, seen_mtime.nsec });
    try testing.expect(std.mem.indexOf(u8, out, "f-whole") != null);
    try testing.expect(std.mem.indexOf(u8, out, "g-whole") != null);
    try testing.expectEqual(seen_mtime, after_mtime);
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// `open(2)` with mode 0644 for a create (the holder rows' fds, the image reads).
fn openRaw(path: [:0]const u8, flags: linux.O) !linux.fd_t {
    const rc = linux.open(path.ptr, flags, 0o644);
    if (linux.errno(rc) != .SUCCESS) {
        std.debug.print("\nopen {s}: {t}\n", .{ path, linux.errno(rc) });
        return error.OpenFailed;
    }
    return @intCast(rc);
}

/// A path's mtime by `statx` (no open, so no close and no FLUSH).
const Mtime = struct { sec: i64, nsec: u32 };

fn mtimeOf(path: [:0]const u8) !Mtime {
    var st: linux.Statx = undefined;
    if (linux.errno(linux.statx(linux.AT.FDCWD, path.ptr, 0, .{ .MTIME = true }, &st)) != .SUCCESS) return error.StatFailed;
    return .{ .sec = st.mtime.sec, .nsec = st.mtime.nsec };
}

/// The mount's `.stats` read by THIS process (no child: a row holding a
/// dirty fd spawns nothing — a child's exec closes its copy, a FLUSH).
fn statsDirect(rig: *Rig) ![]u8 {
    var pb: [256]u8 = undefined;
    const fd = try openRaw(try std.fmt.bufPrintSentinel(&pb, "{s}/.stats", .{rig.mp}, 0), .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
    defer _ = linux.close(fd);
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(rig.gpa);
    var buf: [64 << 10]u8 = undefined;
    while (true) {
        const n = linux.read(fd, &buf, buf.len);
        if (linux.errno(n) != .SUCCESS) return error.ReadFailed;
        if (n == 0) break;
        try out.appendSlice(rig.gpa, buf[0..n]);
    }
    return out.toOwnedSlice(rig.gpa);
}

/// `awaitStats` over `statsDirect`: every `(key, want)` holds in ONE read
/// or the deadline passed (owned; the last read either way).
fn awaitStatsDirect(rig: *Rig, pairs: []const struct { key: []const u8, want: u64 }, deadline_ns: u64) ![]u8 {
    const deadline = clock.monotonicNs() + deadline_ns;
    while (true) {
        const st = try statsDirect(rig);
        var ok = true;
        for (pairs) |p| ok = ok and (numberAfter(st, p.key) orelse std.math.maxInt(u64)) == p.want;
        if (ok or clock.monotonicNs() >= deadline) return st;
        rig.gpa.free(st);
        sleepMs(100);
    }
}

/// `len` bytes of the rig's image at `off` (owned).
fn readImageRange(gpa: std.mem.Allocator, path: [:0]const u8, off: u64, len: u64) ![]u8 {
    const fd = try openRaw(path, .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
    defer _ = linux.close(fd);
    const out = try gpa.alloc(u8, @intCast(len));
    errdefer gpa.free(out);
    var done: usize = 0;
    while (done < out.len) {
        const n = linux.pread(fd, out[done..].ptr, out.len - done, @intCast(off + done));
        if (linux.errno(n) != .SUCCESS or n == 0) return error.ReadFailed;
        done += n;
    }
    return out;
}

/// Every byte of `data` at `off` (a short write continues).
fn pwriteAll(fd: linux.fd_t, data: []const u8, off: u64) !void {
    var done: usize = 0;
    while (done < data.len) {
        const n = linux.pwrite(fd, data[done..].ptr, data.len - done, @intCast(off + done));
        if (linux.errno(n) != .SUCCESS) return error.WriteFailed;
        if (n == 0) return error.WriteFailed;
        done += n;
    }
}

/// The close drain rows' set-up (decision 0003 §AF): `g` exists and is read
/// (on a no-open mount the daemon latched the connection at ready, so no
/// CREATE-opened file — `g`, `f` — is ever released with a RELEASE), then
/// 1 MiB + 1000 B into the fresh `f` (`>`: a CREATE and its close) and the
/// same appended to `g` (`>>`: an open with no OPEN, its close): a partial
/// block of each parked in RAM until a drain.
const close_drain_script = "head -c 4096 \"$1/image\" > g && cat g > /dev/null && head -c {d} \"$1/image\" > f && head -c {d} \"$1/image\" >> g && echo written";
const close_drain_check = "if head -c {d} \"$1/image\" | cmp -s - f; then echo f-whole; else echo f-LOST; fi; if {{ head -c 4096 \"$1/image\"; head -c {d} \"$1/image\"; }} | cmp -s - g; then echo g-whole; else echo g-LOST; fi";

/// The no-open posture, pinned on every stratum (decision 0003 §BE.3): a
/// MainlinePool zero-copy mount serves opens under SQUEEZEFS_FUSE_ZC_OPEN's
/// default (mainline grants zero-copy per open file), so a §AF row judging
/// zero-message opens holds the lever at 0 — inert on the legacy rungs.
fn pinNoOpen(rig: *Rig) !void {
    try rig.env.put("SQUEEZEFS_FUSE_NO_OPEN", "1");
    try rig.env.put("SQUEEZEFS_FUSE_ZC_OPEN", "0");
}

/// One posture of the close drain row: write, close, (the control arm:
/// wait for its asynchronous RELEASE to drain the parked blocks), kill -9,
/// fsck, remount, both files whole.
fn closeDrainRow(no_open: bool) !void {
    const io = testing.io;
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try rig.createImage();
    if (no_open) try pinNoOpen(rig) else try rig.env.put("SQUEEZEFS_FUSE_NO_OPEN", "0");
    // The close posture: the A/B control arm of the write-back timer
    // (decision 0003 §AJ), kept tested.
    try rig.env.put("SQUEEZEFS_WRITEBACK_POSTURE", "close");
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    var script: [512]u8 = undefined;
    {
        const out = try rig.onMount(try std.fmt.bufPrint(&script, close_drain_script, .{ syncfs_fresh_bytes, syncfs_fresh_bytes }));
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "written") != null);
    }
    const st = if (no_open) try rig.stats() else try awaitExactly(rig, "\"parked_buffers\":", 0, 20 * std.time.ns_per_s);
    defer gpa.free(st);
    const enosys = numberAfter(st, "\"fuse_open_enosys\":") orelse 0;
    const drains = numberAfter(st, "\"fuse_flush_drains\":") orelse 0;
    const clean = numberAfter(st, "\"transport_flush_inline_serves\":") orelse 0;
    std.debug.print("\nsmoke[close drain, no_open={}]: OPENs answered ENOSYS {d}, FLUSH drains {d}, FLUSHes answered on the worker {d}, owed {d}, parked buffers {d}\n", .{ no_open, enosys, drains, clean, numberAfter(st, "\"fuse_owed_drain_inos\":") orelse 0, numberAfter(st, "\"parked_buffers\":") orelse 0 });
    try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"parked_buffers\":"));
    // The drain journals the size claims its landing covered (decision
    // 0003 §AL.5): the no-open FLUSH before the close returns, the control
    // arm's asynchronous RELEASE after its landing.
    {
        const sp = if (no_open) try rig.stats() else try awaitExactly(rig, "\"meta_kv_times_echo_pending\":", 0, 20 * std.time.ns_per_s);
        defer gpa.free(sp);
        try testing.expectEqual(@as(?u64, 0), numberAfter(sp, "\"meta_kv_times_echo_pending\":"));
    }
    if (no_open) {
        // The latch: the daemon's own open at ready — `cat g` sent none,
        // and no CREATE-opened file was released with a RELEASE.
        try testing.expectEqual(@as(u64, 1), enosys);
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_no_open_releases\":"));
        // `head` closing its stdout drained each partial block.
        try testing.expect(drains >= 2);
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_owed_drain_inos\":"));
    } else {
        try testing.expectEqual(@as(u64, 0), enosys);
        try testing.expectEqual(@as(u64, 0), drains);
    }
    try rig.kill();
    const recovered = try fsckClean(rig, "the kill after the close");
    _ = try remountAfterKill(rig, recovered, .foreground);
    const out = try rig.onMount(try std.fmt.bufPrint(&script, close_drain_check, .{ syncfs_fresh_bytes, syncfs_fresh_bytes }));
    defer gpa.free(out);
    std.debug.print("smoke[close drain, no_open={}]: after the kill and the remount: {s}\n", .{ no_open, std.mem.trimEnd(u8, out, "\n") });
    try testing.expect(std.mem.indexOf(u8, out, "f-whole") != null);
    try testing.expect(std.mem.indexOf(u8, out, "g-whole") != null);
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

test "smoke: A NO-OPEN CLOSE IS THE WRITE-BACK DRAIN (decision 0003 §AF) — format (no write cache: a partial block parks in RAM) → mount with SQUEEZEFS_FUSE_NO_OPEN=1 (the daemon latches the connection at ready: its own `.stats` open, the ONE OPEN answered ENOSYS) → `g` written and read → 1 MiB + 1000 B into a fresh `f` (a CREATE: no RELEASE will ever come) and appended to `g` (no OPEN at all) by plain redirections → kill -9 the moment the last close returned: nothing parked, nothing owed, no RELEASE, ≥ 2 FLUSH drains, ONE OPEN → fsck --offline clean → remount → both files whole" {
    if (venueMissing(testing.io)) |why| return testkit.skipWhy(@src(), why);
    try closeDrainRow(true);
}

test "smoke: THE CONTROL ARM'S CLOSE DRAIN (SQUEEZEFS_FUSE_NO_OPEN=0) — the same writes; the asynchronous RELEASE drains the parked blocks after close(2) returned (observed: parked 0, no OPEN answered ENOSYS, no FLUSH drain) → kill -9 → fsck --offline clean → remount → both files whole" {
    if (venueMissing(testing.io)) |why| return testkit.skipWhy(@src(), why);
    try closeDrainRow(false);
}

/// The unmount law's files (fstests generic/029's shape, the mapping left
/// out — the loss needs none; `$1` = the work dir). `t`: 5,120 B (past
/// inline_max) truncated DOWN into inline range and UP again, then its
/// tail `[2048, 5120)` rewritten — a size-neutral write past the image the
/// layout record names. `s`: a striped file (past the block) with ONE
/// size-neutral overwrite inside it, its custody parked under the
/// write-back timer. `v`: `t`'s dance then fdatasync (`sync -d`, the
/// rig sync rail's form) — the tail is owed from the ack on. The expected
/// images beside them in the work dir.
const unmount_owes_setup =
    \\x() { head -c "$1" /dev/zero | tr '\0' X; }
    \\y() { head -c "$1" /dev/zero | tr '\0' Y; }
    \\{ x 2048; y 3072; } > "$1/exp-t"
    \\{ x 2048; y 3072; x 4193280; } > "$1/exp-s"
    \\x 5120 > t && truncate -s 2048 t && truncate -s 5120 t && y 3072 | dd of=t bs=3072 seek=2048 oflag=seek_bytes conv=notrunc iflag=fullblock status=none
    \\x 4198400 > s && sync -d s && y 3072 | dd of=s bs=3072 seek=2048 oflag=seek_bytes conv=notrunc iflag=fullblock status=none
    \\x 5120 > v && truncate -s 2048 v && truncate -s 5120 v && y 3072 | dd of=v bs=3072 seek=2048 oflag=seek_bytes conv=notrunc iflag=fullblock status=none && sync -d v
    \\for f in t s v; do e=exp-$f; [ $f = v ] && e=exp-t; if cmp -s $f "$1/$e"; then echo $f-whole; else echo $f-LOST; fi; done
;
const unmount_owes_check = "for f in t s v; do e=exp-$f; [ $f = v ] && e=exp-t; if cmp -s $f \"$1/$e\"; then echo $f-whole; else echo $f-LOST; fi; done";

/// One posture of the unmount law's row: the files written, every byte
/// read back on the same mount, the ORDERLY unmount the moment the last
/// write returned (no fsync of `t` or `s`, no wait for the timer), the
/// remount: every byte there. Then the fsync'd dance killed -9 at once:
/// fsck clean, the remount reads the fsync'd tail.
fn unmountOwesRow(write_cache: bool) !void {
    const io = testing.io;
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(write_cache);
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    try rig.mountAsSet(&.{});
    _ = try rig.awaitReady(0);
    {
        const out = try rig.onMount(unmount_owes_setup);
        defer gpa.free(out);
        std.debug.print("\nsmoke[unmount owes, write_cache={}]: on the writing mount: {s}\n", .{ write_cache, std.mem.trim(u8, out, "\n") });
        // The fsync'd dance reads whole on its own mount: the promotion
        // kept the tail the record's size did not name.
        try testing.expect(std.mem.indexOf(u8, out, "v-whole") != null);
        try testing.expect(std.mem.indexOf(u8, out, "LOST") == null);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    var mark = try rig.logLen();
    try rig.mountAsSet(&.{});
    _ = try rig.awaitReady(mark);
    {
        const out = try rig.onMount(unmount_owes_check);
        defer gpa.free(out);
        std.debug.print("smoke[unmount owes, write_cache={}]: after the orderly unmount and the remount: {s}\n", .{ write_cache, std.mem.trim(u8, out, "\n") });
        try testing.expect(std.mem.indexOf(u8, out, "t-whole") != null);
        try testing.expect(std.mem.indexOf(u8, out, "s-whole") != null);
        try testing.expect(std.mem.indexOf(u8, out, "v-whole") != null);
    }
    // The kill arm: the fsync'd dance's tail is owed across a crash.
    {
        const out = try rig.onMount("rm -f t s v && " ++ unmount_owes_setup);
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "v-whole") != null);
    }
    try rig.kill();
    const recovered = try fsckClean(rig, "the kill after the fsync'd dance");
    mark = try rig.logLen();
    _ = try remountAfterKill(rig, recovered, rig.posture());
    {
        const out = try rig.onMount("if cmp -s v \"$1/exp-t\"; then echo v-whole; else echo v-LOST; fi");
        defer gpa.free(out);
        std.debug.print("smoke[unmount owes, write_cache={}]: after the kill and the remount: {s}\n", .{ write_cache, std.mem.trim(u8, out, "\n") });
        try testing.expect(std.mem.indexOf(u8, out, "v-whole") != null);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

test "smoke: AN ORDERLY UNMOUNT LANDS EVERY ACKED WRITE (fstests generic/029; charter §6.1 'Staged', decision 0003 §AJ) — WITH the write cache: `t` 5,120 B truncated down to 2,048 and up again, its tail rewritten (the staged arm's size-neutral write past the record's image); `s` a striped file with one overwrite inside it (custody parked under the write-back timer); `v` the dance then fsync — all three read whole on the writing mount → the orderly unmount the moment the last write returned → remount → every byte there; then the fsync'd dance killed -9 → fsck --offline clean → remount → its tail there" {
    if (venueMissing(testing.io)) |why| return testkit.skipWhy(@src(), why);
    try unmountOwesRow(true);
}

test "smoke: AN ORDERLY UNMOUNT LANDS EVERY ACKED WRITE — WITHOUT the write cache (SQUEEZEFS_WRITE_CACHE_PCT=0: every write past inline parks a partial block in RAM): the same files, the same unmount at once, the same remount — every byte there; the fsync'd dance killed -9 → fsck clean → remount → whole" {
    if (venueMissing(testing.io)) |why| return testkit.skipWhy(@src(), why);
    try unmountOwesRow(false);
}

/// The ordered law's kill row: a small file's size before its growth — a
/// resident image (below the inline bound), so the growth promotes it.
const ordered_small: u64 = 100;
/// The size the growth writes: ONE grain of the image's second grain at
/// byte 8,192, leaving the gap `[100, 8192)` across the promoted grain's
/// end — the poisoned block's tail is the gap's last grain.
const ordered_grown: u64 = 3 * layout.GRAIN;
/// The truncate step's size past the fsynced growth: a further grain of
/// the poisoned tail, now the truncate's own gap.
const ordered_truncated: u64 = 5 * layout.GRAIN;

/// Where each step of the ordered law's kill row kills the daemon.
const OrderedStep = enum {
    /// The moment the growing write returned: its custody and its claim in RAM.
    write,
    /// The write-back timer landed the custody; the claim journals at the
    /// drain right after its pass.
    landed,
    /// `conv=fsync`: the size and its bytes durable.
    fsync,
    /// An fsynced growth, then a truncate-up into the poisoned tail.
    truncate,
};

/// The growth of one step's file `y{k}` (`$1` = the work dir).
fn orderedScript(buf: []u8, step: OrderedStep, k: usize) ![]const u8 {
    const grow = "head -c {d} \"$1/image\" > y{d} && dd if=\"$1/image\" of=y{d} bs={d} skip=1 seek=2 count=1 conv=notrunc{s} status=none";
    const g: u64 = layout.GRAIN;
    return switch (step) {
        .write, .landed => std.fmt.bufPrint(buf, grow ++ " && echo grown", .{ ordered_small, k, k, g, "" }),
        .fsync => std.fmt.bufPrint(buf, grow ++ " && echo grown", .{ ordered_small, k, k, g, ",fsync" }),
        .truncate => std.fmt.bufPrint(buf, grow ++ " && truncate -s {d} y{d} && echo grown", .{ ordered_small, k, k, g, ",fsync", ordered_truncated, k }),
    };
}

/// One step's file after the kill and the remount: a size the law allows
/// (the last durable one) and every byte below it the file's own — the
/// image's head, the gap's zeros, the grown grain, the truncate's zeros.
/// Never the poison: another file's bytes.
fn orderedCheck(io: Io, dir: Io.Dir, image: Io.File, step: OrderedStep, k: usize) !u64 {
    var nb: [16]u8 = undefined;
    const name = try std.fmt.bufPrint(&nb, "y{d}", .{k});
    const f = try dir.openFile(io, name, .{});
    defer f.close(io);
    const size = (try f.stat(io)).size;
    const allowed: []const u64 = switch (step) {
        .write, .landed => &.{ ordered_small, ordered_grown },
        .fsync => &.{ordered_grown},
        .truncate => &.{ ordered_grown, ordered_truncated },
    };
    if (std.mem.indexOfScalar(u64, allowed, size) == null) {
        std.debug.print("\n--- ordered law, step {t}: y{d} recovered at {d} B, allowed {any} ---\n", .{ step, k, size, allowed });
        return error.SizeOutsideTheLaw;
    }
    var got: [ordered_truncated]u8 = undefined;
    var want: [ordered_truncated]u8 = @splat(0);
    const n: usize = @intCast(size);
    if (try f.readPositionalAll(io, got[0..n], 0) != n) return error.ShortRead;
    if (try image.readPositionalAll(io, want[0..ordered_small], 0) != ordered_small) return error.ShortRead;
    if (size >= ordered_grown) {
        const g = layout.GRAIN;
        if (try image.readPositionalAll(io, want[2 * g .. 3 * g], g) != g) return error.ShortRead;
    }
    if (!std.mem.eql(u8, got[0..n], want[0..n])) {
        const at = std.mem.indexOfDiff(u8, got[0..n], want[0..n]).?;
        std.debug.print("\n--- ordered law, step {t}: y{d} ({d} B) byte {d} reads 0x{x:0>2}, its own is 0x{x:0>2}{s} ---\n", .{ step, k, size, at, got[at], want[at], if (got[at] == 0xAA) " — the poisoned block's previous-owner bytes" else "" });
        return error.AnotherFilesBytes;
    }
    return size;
}

test "smoke: THE ORDERED LAW'S KILL ROW (decision 0003 §AL.5 with §AJ.4) — format (no write cache: a partial block parks in RAM), the write-back timer posture, every promotion's own block POISONED with 0xAA before its image grain lands (SQUEEZEFS_TEST_OWN_BLOCK_POISON: the bytes a recycled block's previous owner leaves where a block device elides its discard) → per step a 100 B file grows by one grain at byte 8,192 (the gap [100, 8192) crosses the poisoned tail) and the daemon is killed -9: the moment the write returned / once the timer landed it / after conv=fsync / after an fsynced growth and a truncate-up into the tail → fsck --offline clean → remount → the file at its last durable size (unsynced: 100 B or whole; fsynced: whole) and every byte below it its own, never the poison" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try rig.createImage();
    try rig.env.put("SQUEEZEFS_TEST_OWN_BLOCK_POISON", "1");
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    const image = try Io.Dir.cwd().openFile(io, rig.image, .{});
    defer image.close(io);
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    const steps = comptime std.enums.values(OrderedStep);
    var sizes: [steps.len]u64 = undefined;
    for (steps, 0..) |step, k| {
        var script: [512]u8 = undefined;
        {
            const out = try rig.onMount(try orderedScript(&script, step, k));
            defer gpa.free(out);
            try testing.expect(std.mem.indexOf(u8, out, "grown") != null);
        }
        const st = try rig.stats();
        defer gpa.free(st);
        // The growth promoted the file into a poisoned block.
        try testing.expect((numberAfter(st, "\"own_block_dmas\":") orelse 0) >= 1);
        if (step == .landed) {
            const landed = try awaitAtLeast(rig, "\"writeback_timer_drains\":", 1, 20 * std.time.ns_per_s);
            defer gpa.free(landed);
            try testing.expect((numberAfter(landed, "\"writeback_timer_drains\":") orelse 0) >= 1);
            const parked = try awaitExactly(rig, "\"parked_buffers\":", 0, 20 * std.time.ns_per_s);
            defer gpa.free(parked);
            try testing.expectEqual(@as(?u64, 0), numberAfter(parked, "\"parked_buffers\":"));
        }
        try rig.kill();
        const recovered = try fsckClean(rig, "the ordered law's kill");
        _ = try remountAfterKill(rig, recovered, .foreground);
        var dir = try Io.Dir.cwd().openDir(io, rig.mp, .{});
        defer dir.close(io);
        sizes[k] = try orderedCheck(io, dir, image, step, k);
    }
    std.debug.print("\nsmoke[ordered law]: recovered sizes after the kill — write {d} B, landed {d} B, fsync {d} B, truncate {d} B; every byte the file's own, never the poison\n", .{ sizes[0], sizes[1], sizes[2], sizes[3] });
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// The owed row's writer: an extending write that parks a partial block
/// (no write cache), the pattern the remount checks.
const owed_write_bytes: usize = (1 << 20) + 1000;

fn owedByte(i: usize) u8 {
    return @truncate(i *% 31 +% 7);
}

test "smoke: CUSTODY NO CLOSE COVERS IS DRAINED ONCE IDLE (decision 0003 §AF) — no-open, no write cache, the owed idle horizon at 0 (the seam), the connection latched at ready (no RELEASE would drain `m` either): a writer creates `m` and writes 1 MiB + 1000 B (a parked partial block) and holds its fd OPEN — no close, so no FLUSH follows the write: the class a mapping written back after its fd closed (`fuse_vma_close` at munmap) and an async write landing after its close share ⇒ the ino is owed → the reclaim cadence drains it (parked 0, owed 0, ONE idle drain, no FLUSH drain) → kill -9 with the fd still open → fsck --offline clean → remount → the bytes are there" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try pinNoOpen(rig);
    try rig.env.put("SQUEEZEFS_WRITEBACK_POSTURE", "close");
    try rig.env.put("SQUEEZEFS_TEST_FUSE_OWED_IDLE_MS", "0");
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    var path_buf: [256]u8 = undefined;
    const path = try std.fmt.bufPrintSentinel(&path_buf, "{s}/m", .{rig.mp}, 0);
    const pattern = try gpa.alloc(u8, owed_write_bytes);
    defer gpa.free(pattern);
    for (pattern, 0..) |*b, i| b.* = owedByte(i);
    const fd = try openRaw(path, .{ .ACCMODE = .WRONLY, .CREAT = true, .TRUNC = true, .CLOEXEC = true });
    // Held past the kill: never closed while the daemon lives.
    defer _ = linux.close(fd);
    try pwriteAll(fd, pattern, 0);
    {
        // Every word settled in one render: a render is no atomic cut, so
        // the render that first shows the drain's count can carry a word
        // read before the drain (`parked_buffers` 1 beside the count).
        const st = try awaitStatsDirect(rig, &.{
            .{ .key = "\"fuse_owed_idle_drains\":", .want = 1 },
            .{ .key = "\"fuse_owed_drain_inos\":", .want = 0 },
            .{ .key = "\"parked_buffers\":", .want = 0 },
            .{ .key = "\"parked_extent_bytes\":", .want = 0 },
            .{ .key = "\"overlay_open\":", .want = 0 },
            .{ .key = "\"fuse_flush_drains\":", .want = 0 },
        }, 30 * std.time.ns_per_s);
        defer gpa.free(st);
        std.debug.print("\nsmoke[owed idle drain]: idle drains {d}, owed {d}, parked buffers {d}, parked extent bytes {d}, open overlays {d}, FLUSH drains {d}\n", .{ numberAfter(st, "\"fuse_owed_idle_drains\":") orelse 0, numberAfter(st, "\"fuse_owed_drain_inos\":") orelse 0, numberAfter(st, "\"parked_buffers\":") orelse 0, numberAfter(st, "\"parked_extent_bytes\":") orelse 0, numberAfter(st, "\"overlay_open\":") orelse 0, numberAfter(st, "\"fuse_flush_drains\":") orelse 0 });
        try testing.expectEqual(@as(?u64, 1), numberAfter(st, "\"fuse_owed_idle_drains\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_owed_drain_inos\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"parked_buffers\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"parked_extent_bytes\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"overlay_open\":"));
        // No close drained it: the custody came after every FLUSH.
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_flush_drains\":"));
    }
    try rig.kill();
    const recovered = try fsckClean(rig, "the kill after the idle drain");
    _ = try remountAfterKill(rig, recovered, .foreground);
    {
        const rfd = try openRaw(path, .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
        defer _ = linux.close(rfd);
        const got = try gpa.alloc(u8, owed_write_bytes + 1);
        defer gpa.free(got);
        var done: usize = 0;
        while (done < got.len) {
            const n = linux.pread(rfd, got[done..].ptr, got.len - done, @intCast(done));
            if (linux.errno(n) != .SUCCESS) return error.ReadFailed;
            if (n == 0) break;
            done += n;
        }
        try testing.expectEqual(owed_write_bytes, done);
        for (got[0..done], 0..) |b, i| if (b != owedByte(i)) {
            std.debug.print("\nsmoke[owed idle drain]: byte {d} reads 0x{x} after the remount — the write was LOST\n", .{ i, b });
            return error.OwedWriteLost;
        };
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// The close-burst row: forked appenders sharing one fd.
const burst_children: usize = 200;

test "smoke: A CLOSE BURST COALESCES ITS DRAINS (decision 0003 §AF) — no-open, no write cache: `log` written past inline (its close drains), then a shell holds it open for append and 200 forked `/bin/echo` children write a line each through it — every child's exit closes its copy, a FLUSH with custody ⇒ ONE drains (the first), the rest defer to the reclaim cadence's next tick (drains ≤ 2 + the windows the burst spanned, drains + deferred ≥ 200; drained each, they re-uploaded a whole block per close: 57,000× amplification measured) → the deferred custody lands (owed 0, parked 0) → kill -9 → fsck --offline clean → remount → every line there" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try rig.createImage();
    try pinNoOpen(rig);
    try rig.env.put("SQUEEZEFS_WRITEBACK_POSTURE", "close");
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    var script: [512]u8 = undefined;
    const t0 = clock.monotonicNs();
    {
        const out = try rig.onMount(try std.fmt.bufPrint(&script, "head -c 8192 \"$1/image\" > log && exec 3>>log && i=0 && while [ $i -lt {d} ]; do /bin/echo \"line $i of the close burst\" >&3; i=$((i + 1)); done && echo appended", .{burst_children}));
        defer gpa.free(out);
        try testing.expect(std.mem.indexOf(u8, out, "appended") != null);
    }
    const burst_ns = clock.monotonicNs() - t0;
    {
        const st = try rig.stats();
        defer gpa.free(st);
        const drains = numberAfter(st, "\"fuse_flush_drains\":") orelse 0;
        const deferred = numberAfter(st, "\"fuse_flush_drains_deferred\":") orelse 0;
        // One drain per coalescing window the burst spanned (the window is
        // the reclaim tick), the prefill's and the last close's on top —
        // counted on the burst's own clock, so a loaded host only widens it.
        const bound = 2 + burst_ns / handler.watchdog.TICK_NS; // `mount.RECLAIM_CADENCE_NS`
        std.debug.print("\nsmoke[close burst]: {d} children in {d} ms: FLUSH drains {d} (bound {d}), deferred {d}, answered on the worker {d}\n", .{ burst_children, burst_ns / std.time.ns_per_ms, drains, bound, deferred, numberAfter(st, "\"transport_flush_inline_serves\":") orelse 0 });
        try testing.expect(drains >= 1 and drains <= bound);
        // Every child's write met its close: drained or deferred.
        try testing.expect(drains + deferred >= burst_children);
    }
    // The deferred custody lands — the cadence's next tick, or the last
    // close's own drain once a window passed. Both words at once: the
    // cadence harvests an owed ino BEFORE its drain lands, so owed reads 0
    // while the block is still parked for the drain's length.
    {
        const st = try awaitStats(rig, &.{ .{ .key = "\"fuse_owed_drain_inos\":", .want = 0 }, .{ .key = "\"parked_buffers\":", .want = 0 } }, 30 * std.time.ns_per_s);
        defer gpa.free(st);
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_owed_drain_inos\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"parked_buffers\":"));
    }
    try rig.kill();
    const recovered = try fsckClean(rig, "the kill after the close burst");
    _ = try remountAfterKill(rig, recovered, .foreground);
    {
        const out = try rig.onMount(try std.fmt.bufPrint(&script, "{{ head -c 8192 \"$1/image\"; i=0; while [ $i -lt {d} ]; do echo \"line $i of the close burst\"; i=$((i + 1)); done; }} | cmp -s - log && echo log-whole", .{burst_children}));
        defer gpa.free(out);
        std.debug.print("smoke[close burst]: after the kill and the remount: {s}\n", .{std.mem.trimEnd(u8, out, "\n")});
        try testing.expect(std.mem.indexOf(u8, out, "log-whole") != null);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// The write-back timer rows' files (decision 0003 §AJ): a partial block
/// each on a cache-less mount (parked in RAM until a drain), a
/// pattern per file so a swapped or torn body is caught.
const wb_file_bytes: usize = (1 << 20) + 1000;

fn wbByte(file: usize, i: usize) u8 {
    return @truncate(i *% 31 +% 7 +% file *% 13);
}

/// The rows' write(2) grain: the head and the tail of a file are one
/// write(2) each, neither past the kernel's `max_write` (1 MiB), so each is
/// ONE FUSE WRITE — the unit an acknowledgement covers (a longer write(2)
/// is split by the kernel into requests the daemon acks one by one).
const wb_head_bytes: usize = 1 << 20;

/// Create `path` (O_TRUNC), write file `file`'s pattern as its two writes,
/// close — from THIS process: no child, so every request is the row's own.
fn wbWrite(gpa: std.mem.Allocator, path: [:0]const u8, file: usize) !void {
    const body = try gpa.alloc(u8, wb_file_bytes);
    defer gpa.free(body);
    for (body, 0..) |*b, i| b.* = wbByte(file, i);
    const fd = try openRaw(path, .{ .ACCMODE = .WRONLY, .CREAT = true, .TRUNC = true, .CLOEXEC = true });
    defer _ = linux.close(fd);
    try pwriteAll(fd, body[0..wb_head_bytes], 0);
    try pwriteAll(fd, body[wb_head_bytes..], wb_head_bytes);
}

/// The crash law at write grain for an unsynced write (decision 0003 §AJ,
/// ext4's `data=ordered`, §AL): after a kill -9 each write(2) of a file is
/// its whole pattern (landed) or absent — zeros, or past the file's
/// recovered length (an unsynced extension may revert to the last durable
/// length, a write boundary) — never part one and part the other, never
/// another file's bytes.
const WbState = enum { present, absent };

/// A file's two writes judged one by one.
const WbFile = struct {
    head: WbState,
    tail: WbState,

    fn whole(self: WbFile) bool {
        return self.head == .present and self.tail == .present;
    }
};

fn wbRegion(path: [:0]const u8, got: []const u8, file: usize, from: usize) !WbState {
    var exact = true;
    var zeros = true;
    for (got, from..) |b, i| {
        exact = exact and b == wbByte(file, i);
        zeros = zeros and b == 0;
    }
    if (exact) return .present;
    if (zeros) return .absent;
    var n_exact: usize = 0;
    var n_zero: usize = 0;
    for (got, from..) |b, i| {
        if (b == wbByte(file, i)) n_exact += 1 else if (b == 0) n_zero += 1;
    }
    std.debug.print("\nsmoke[write-back timer]: {s}: the write at {d} ({d} B) is neither itself nor zeros after the remount — TORN: {d} B its own, {d} B zeros, {d} B foreign\n", .{ path, from, got.len, n_exact, n_zero, got.len - n_exact - n_zero });
    return error.TornWrite;
}

/// A histogram's field (`"count":`, `"sum_ns":`) in a `.stats` document:
/// the first after the histogram's key.
fn histFieldAfter(text: []const u8, key: []const u8, field: []const u8) ?u64 {
    const i = std.mem.indexOf(u8, text, key) orelse return null;
    return numberAfter(text[i..], field);
}

fn wbJudge(gpa: std.mem.Allocator, path: [:0]const u8, file: usize) !WbFile {
    const fd = try openRaw(path, .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
    defer _ = linux.close(fd);
    const got = try gpa.alloc(u8, wb_file_bytes + 1);
    defer gpa.free(got);
    var done: usize = 0;
    while (done < got.len) {
        const n = linux.pread(fd, got[done..].ptr, got.len - done, @intCast(done));
        if (linux.errno(n) != .SUCCESS) return error.ReadFailed;
        if (n == 0) break;
        done += n;
    }
    // The recovered length is a write boundary: none, the head, both.
    if (done != 0 and done != wb_head_bytes and done != wb_file_bytes) {
        std.debug.print("\nsmoke[write-back timer]: {s} reads {d} B after the remount — not a write boundary of its 0 / {d} / {d}\n", .{ path, done, wb_head_bytes, wb_file_bytes });
        return error.TornLength;
    }
    const head: WbState = if (done == 0) .absent else try wbRegion(path, got[0..wb_head_bytes], file, 0);
    const tail: WbState = if (done < wb_file_bytes) .absent else try wbRegion(path, got[wb_head_bytes..done], file, wb_head_bytes);
    return .{ .head = head, .tail = tail };
}

test "smoke: THE WRITE-BACK TIMER — CLOSE IS LOCAL, THE BOUND HOLDS (decision 0003 §AJ: close is no durability point; an acked unsynced write leaves daemon memory within T_wb) — format (no write cache: a partial block parks in RAM) → mount under SQUEEZEFS_WRITEBACK_POSTURE=timer (no-open; the daemon's own close at ready is the ONE FLUSH, answered ENOSYS: the kernel's `no_flush`) → 8 files created, written past inline and closed, each reopened and closed 4 times: no FLUSH reaches the daemon past the latch (ENOSYS still the one, no worker serve, no demotion, no drain), no RELEASE → `f` written and closed, never synced: the timer lands it (owed 0, parked 0, every residency ≥ the age: nothing landed before it came of age) → 16 more written and closed and kill -9 AT ONCE → fsck --offline clean → remount → `f` and the 8 whole; each write(2) of the 16 (1 MiB, then its 1000 B tail: one FUSE WRITE each) whole or absent (zeros, or past a length reverted to a write boundary), never torn, never another file's bytes" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try pinNoOpen(rig);
    try rig.env.put("SQUEEZEFS_WRITEBACK_POSTURE", "timer");
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    // The latch: the daemon's own close at ready (answered on a worker).
    var latch: struct { inline_serves: u64, enosys: u64, bound_ns: u64 } = undefined;
    {
        const st = try statsDirect(rig);
        defer gpa.free(st);
        latch = .{ .inline_serves = numberAfter(st, "\"transport_flush_inline_serves\":") orelse 0, .enosys = numberAfter(st, "\"fuse_flush_enosys\":") orelse 0, .bound_ns = numberAfter(st, "\"writeback_bound_ns\":") orelse 0 };
    }
    const bound_ns = latch.bound_ns;
    var pb: [256]u8 = undefined;
    // (a) Closes are local: creates, written closes, read closes.
    const census_files = 8;
    for (0..census_files) |i| {
        const p = try std.fmt.bufPrintSentinel(&pb, "{s}/c{d}", .{ rig.mp, i }, 0);
        try wbWrite(gpa, p, 100 + i);
        for (0..4) |_| _ = linux.close(try openRaw(p, .{ .ACCMODE = .RDONLY, .CLOEXEC = true }));
    }
    {
        const st = try statsDirect(rig);
        defer gpa.free(st);
        std.debug.print("\nsmoke[write-back timer]: T_wb's static part {d} ms; after {d} creates + {d} closes: FLUSH drained {d}, answered on the worker {d} (at ready {d}), demoted {d}, ENOSYS {d}, RELEASEs {d}\n", .{ bound_ns / std.time.ns_per_ms, census_files, census_files * 5, numberAfter(st, "\"fuse_flush_drains\":") orelse 0, numberAfter(st, "\"transport_flush_inline_serves\":") orelse 0, latch.inline_serves, numberAfter(st, "\"transport_flush_inline_demotes\":") orelse 0, numberAfter(st, "\"fuse_flush_enosys\":") orelse 0, numberAfter(st, "\"fuse_no_open_releases\":") orelse 0 });
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_flush_drains\":"));
        try testing.expectEqual(@as(?u64, latch.inline_serves), numberAfter(st, "\"transport_flush_inline_serves\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"transport_flush_inline_demotes\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_no_open_releases\":"));
        try testing.expectEqual(@as(?u64, 1), numberAfter(st, "\"fuse_flush_enosys\":"));
        try testing.expect(latch.enosys == 1 and latch.inline_serves <= 1);
        try testing.expect(bound_ns > 0);
    }
    // (b) Written and closed, never synced: the timer lands it.
    const f_path = try std.fmt.bufPrintSentinel(&pb, "{s}/f", .{rig.mp}, 0);
    var f_buf: [256]u8 = undefined;
    @memcpy(f_buf[0 .. f_path.len + 1], f_path[0 .. f_path.len + 1]);
    const f: [:0]const u8 = f_buf[0..f_path.len :0];
    try wbWrite(gpa, f, 7);
    const t_close = clock.monotonicNs();
    {
        const st = try awaitStats(rig, &.{ .{ .key = "\"fuse_owed_drain_inos\":", .want = 0 }, .{ .key = "\"parked_buffers\":", .want = 0 }, .{ .key = "\"parked_extent_bytes\":", .want = 0 }, .{ .key = "\"overlay_open\":", .want = 0 } }, 30 * std.time.ns_per_s);
        defer gpa.free(st);
        const seen_ms = (clock.monotonicNs() - t_close) / std.time.ns_per_ms;
        const drains = numberAfter(st, "\"writeback_timer_drains\":") orelse 0;
        const res_max = numberAfter(st, "\"writeback_residency_max_ns\":") orelse 0;
        const res_count = histFieldAfter(st, "\"writeback_residency_ns\":", "\"count\":") orelse 0;
        const res_sum = histFieldAfter(st, "\"writeback_residency_ns\":", "\"sum_ns\":") orelse 0;
        std.debug.print("smoke[write-back timer]: `f` landed by the timer, observed {d} ms after its close: timer drains {d}, residencies {d} (mean {d} ms, max {d} ms), FLUSH drains {d}, syncfs {d}\n", .{ seen_ms, drains, res_count, if (res_count == 0) 0 else res_sum / res_count / std.time.ns_per_ms, res_max / std.time.ns_per_ms, numberAfter(st, "\"fuse_flush_drains\":") orelse 0, numberAfter(st, "\"fuse_syncfs\":") orelse 0 });
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_owed_drain_inos\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"parked_buffers\":"));
        // The 8 census files and `f`: every one landed by the timer — no
        // close, no fsync, no syncfs drained any.
        try testing.expect(drains >= census_files + 1);
        try testing.expect(res_count >= census_files + 1);
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_flush_drains\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"fuse_syncfs\":"));
        // The age law: nothing landed before it came of age.
        try testing.expect(res_sum >= res_count * (numberAfter(st, "\"writeback_age_ns\":") orelse 0));
    }
    // Kill at once: 16 more, the youngest far inside the age.
    const late_files = 16;
    for (0..late_files) |i| try wbWrite(gpa, try std.fmt.bufPrintSentinel(&pb, "{s}/g{d}", .{ rig.mp, i }, 0), 200 + i);
    try rig.kill();
    const recovered = try fsckClean(rig, "the kill right after the closes");
    _ = try remountAfterKill(rig, recovered, .foreground);
    try testing.expect((try wbJudge(gpa, f, 7)).whole());
    for (0..census_files) |i| try testing.expect((try wbJudge(gpa, try std.fmt.bufPrintSentinel(&pb, "{s}/c{d}", .{ rig.mp, i }, 0), 100 + i)).whole());
    var present: usize = 0;
    var landed_writes: usize = 0;
    for (0..late_files) |i| {
        const j = try wbJudge(gpa, try std.fmt.bufPrintSentinel(&pb, "{s}/g{d}", .{ rig.mp, i }, 0), 200 + i);
        if (j.whole()) present += 1;
        landed_writes += @as(usize, @intFromBool(j.head == .present)) + @intFromBool(j.tail == .present);
    }
    std.debug.print("smoke[write-back timer]: after kill -9 at once and the remount: `f` and the {d} census files whole; of the {d} closed at the kill {d} whole — {d} of their {d} writes landed, the rest absent (zeros or past the recovered length), 0 torn, 0 foreign\n", .{ census_files, late_files, present, landed_writes, 2 * late_files });
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

test "smoke: UNDER THE WRITE-BACK TIMER fsync, fdatasync AND syncfs ARE STILL DURABILITY POINTS — the timer held ten minutes away (the seam), no write cache: `s1` written + fsync, `s2` + fdatasync, `s3` + syncfs(2), `s4` written and closed with no sync → kill -9 at once → fsck --offline clean → remount → s1, s2, s3 whole; s4's parked tail absent (zeros, or past a length reverted to the head): the unsynced write younger than T_wb the owner's ruling lets a crash lose, never torn" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try pinNoOpen(rig);
    try rig.env.put("SQUEEZEFS_WRITEBACK_POSTURE", "timer");
    try rig.env.put("SQUEEZEFS_TEST_FUSE_OWED_IDLE_MS", "600000");
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    var pb: [256]u8 = undefined;
    const body = try gpa.alloc(u8, wb_file_bytes);
    defer gpa.free(body);
    var syncfs_armed = true;
    {
        const st = try statsDirect(rig);
        defer gpa.free(st);
        syncfs_armed = numberAfter(st, "\"fuse_syncfs_armed\":") == 1;
    }
    for (1..5) |k| {
        for (body, 0..) |*b, i| b.* = wbByte(300 + k, i);
        const fd = try openRaw(try std.fmt.bufPrintSentinel(&pb, "{s}/s{d}", .{ rig.mp, k }, 0), .{ .ACCMODE = .WRONLY, .CREAT = true, .TRUNC = true, .CLOEXEC = true });
        defer _ = linux.close(fd);
        try pwriteAll(fd, body, 0);
        switch (k) {
            1 => try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fsync(fd))),
            2 => try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fdatasync(fd))),
            3 => try testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.syncfs(fd))),
            else => {},
        }
    }
    {
        const st = try statsDirect(rig);
        defer gpa.free(st);
        std.debug.print("\nsmoke[write-back timer, syncs]: before the kill: timer drains {d}, owed {d}, parked buffers {d}, syncfs {d} (armed {})\n", .{ numberAfter(st, "\"writeback_timer_drains\":") orelse 0, numberAfter(st, "\"fuse_owed_drain_inos\":") orelse 0, numberAfter(st, "\"parked_buffers\":") orelse 0, numberAfter(st, "\"fuse_syncfs\":") orelse 0, syncfs_armed });
        // The timer is held away: only the syncs drained, `s4` still parked
        // (and `s3` when the kernel never forwards syncfs).
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"writeback_timer_drains\":"));
        try testing.expectEqual(@as(?u64, if (syncfs_armed) 1 else 2), numberAfter(st, "\"parked_buffers\":"));
    }
    try rig.kill();
    const recovered = try fsckClean(rig, "the kill after the syncs");
    _ = try remountAfterKill(rig, recovered, .foreground);
    for (1..4) |k| {
        const j = try wbJudge(gpa, try std.fmt.bufPrintSentinel(&pb, "{s}/s{d}", .{ rig.mp, k }, 0), 300 + k);
        // Without FUSE_HAS_SYNCFS the kernel never forwards syncfs(2): `s3`
        // is then an unsynced file like `s4` (judged at write grain only).
        if (k != 3 or syncfs_armed) try testing.expect(j.whole());
    }
    // `s4`'s tail was parked (the timer held away): zeros at its acked
    // size. Its 1 MiB head is whichever its arm made it — the device
    // overlay's fresh-destination write publishes at its completion.
    const s4 = try wbJudge(gpa, try std.fmt.bufPrintSentinel(&pb, "{s}/s4", .{rig.mp}, 0), 304);
    try testing.expectEqual(WbState.absent, s4.tail);
    std.debug.print("smoke[write-back timer, syncs]: after kill -9 and the remount: s1 (fsync), s2 (fdatasync), s3 (syncfs) whole; s4 (no sync): head {t}, tail {t} (zeros or past the recovered length)\n", .{ s4.head, s4.tail });
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// The storm row's shape: writers × files each, against a parked cap of
/// `wb_storm_cap` buffers.
const wb_storm_writers: usize = 16;
const wb_storm_files: usize = 12;
const wb_storm_cap: u64 = 8;

test "smoke: THE WRITE-BACK TIMER UNDER A WRITER STORM — the memory bound (decision 0003 §AJ): no write cache, SQUEEZEFS_PARKED_BUFFERS=8 (the budget's parked-buffer component), 16 writers each create, write 1 MiB + 1000 B (two write(2)s) and close 12 files (a partial block each, every close local): at every sample the parked buffers stay ≤ 8 and their bytes ≤ 8 blocks — a writer past the cap parks at the gate or lands the coldest custody itself (gate waits + cold flushes ≥ 1), nothing grows without bound → the storm ends, the timer lands the rest (owed 0, parked 0) → kill -9 → fsck --offline clean → remount → all 192 files whole" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.formatSet(false);
    try rig.createImage();
    try pinNoOpen(rig);
    try rig.env.put("SQUEEZEFS_WRITEBACK_POSTURE", "timer");
    var cap_text: [8]u8 = undefined;
    try rig.env.put("SQUEEZEFS_PARKED_BUFFERS", try std.fmt.bufPrint(&cap_text, "{d}", .{wb_storm_cap}));
    try rig.env.put("SQUEEZEFS_BLOCK_REFS_VERIFY", "1");
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    // `formatSet` takes the format's default block.
    const block_bytes: u64 = @import("../data/transform.zig").DEFAULT_BLOCK_SIZE;
    var cmd_buf: [512]u8 = undefined;
    // Each file is two write(2)s, 1 MiB and its 1000 B tail (`dd` over a
    // pipe, full blocks): the head rides the device overlay, the tail parks.
    // `conv=notrunc`: uutils dd (0.10, kamrui's Ubuntu 26.04) ftruncates its
    // output to the bytes written AFTER the last write — a size-setting
    // SETATTR, which settles the file's custody, so no tail would park.
    const cmd = try std.fmt.bufPrint(&cmd_buf, "w=0; while [ $w -lt {d} ]; do ( i=0; while [ $i -lt {d} ]; do head -c {d} {s}/image | dd of={s}/w$w-$i bs=1M iflag=fullblock conv=notrunc status=none; i=$((i + 1)); done ) & w=$((w + 1)); done; wait", .{ wb_storm_writers, wb_storm_files, wb_file_bytes, rig.work, rig.mp });
    var storm = try std.process.spawn(io, .{ .argv = &.{ "sh", "-c", cmd }, .environ_map = &rig.env, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore, .pgid = 0 });
    var samples: usize = 0;
    var max_parked: u64 = 0;
    var max_bytes: u64 = 0;
    {
        // Sampled while the storm runs (its own process group: reaped on
        // every exit path).
        errdefer _ = linux.kill(-storm.id.?, .KILL);
        const deadline = clock.monotonicNs() + 300 * std.time.ns_per_s;
        while (clock.monotonicNs() < deadline) {
            const st = try rig.stats();
            defer gpa.free(st);
            samples += 1;
            max_parked = @max(max_parked, numberAfter(st, "\"parked_buffers\":") orelse 0);
            max_bytes = @max(max_bytes, numberAfter(st, "\"parked_full_buffer_bytes\":") orelse 0);
            var running = false;
            for (0..wb_storm_writers) |w| {
                var pb: [256:0]u8 = undefined;
                const p = try std.fmt.bufPrintSentinel(&pb, "{s}/w{d}-{d}", .{ rig.mp, w, wb_storm_files - 1 }, 0);
                running = running or fileSize(p) < wb_file_bytes;
            }
            if (!running) break;
        }
    }
    try testing.expect((try storm.wait(io)).success());
    {
        const st = try awaitStats(rig, &.{ .{ .key = "\"fuse_owed_drain_inos\":", .want = 0 }, .{ .key = "\"parked_buffers\":", .want = 0 } }, 60 * std.time.ns_per_s);
        defer gpa.free(st);
        const waits = numberAfter(st, "\"parked_gate_waits\":") orelse 0;
        const cold = numberAfter(st, "\"parked_gate_cold_flushes\":") orelse 0;
        const res_max = numberAfter(st, "\"writeback_residency_max_ns\":") orelse 0;
        std.debug.print("\nsmoke[write-back storm]: {d} writers × {d} files under a cap of {d}: {d} samples, parked ≤ {d} buffers / {d} KiB (bound {d} KiB); gate waits {d}, cold flushes {d}, timer drains {d} (kept {d}), residency max {d} ms\n", .{ wb_storm_writers, wb_storm_files, wb_storm_cap, samples, max_parked, max_bytes >> 10, (wb_storm_cap * block_bytes) >> 10, waits, cold, numberAfter(st, "\"writeback_timer_drains\":") orelse 0, numberAfter(st, "\"writeback_timer_kept\":") orelse 0, res_max / std.time.ns_per_ms });
        try testing.expect(samples >= 1);
        try testing.expect(max_parked <= wb_storm_cap);
        try testing.expect(max_bytes <= wb_storm_cap * block_bytes);
        try testing.expect(waits + cold >= 1);
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"parked_buffers\":"));
        try expectMustStayZero(st);
        // The registry holds every head in flight (decision 0003 §AP).
        try testing.expectEqual(@as(?u64, 0), numberAfter(st, "\"overlay_registry_declines\":"));
    }
    try rig.kill();
    const recovered = try fsckClean(rig, "the kill after the storm");
    _ = try remountAfterKill(rig, recovered, .foreground);
    var check_buf: [512]u8 = undefined;
    const out = try rig.onMount(try std.fmt.bufPrint(&check_buf, "bad=0; w=0; while [ $w -lt {d} ]; do i=0; while [ $i -lt {d} ]; do head -c {d} \"$1/image\" | cmp -s - w$w-$i || bad=$((bad + 1)); i=$((i + 1)); done; w=$((w + 1)); done; echo \"bad=$bad\"", .{ wb_storm_writers, wb_storm_files, wb_file_bytes }));
    defer gpa.free(out);
    std.debug.print("smoke[write-back storm]: after kill -9 and the remount: {s}\n", .{std.mem.trimEnd(u8, out, "\n")});
    try testing.expect(std.mem.indexOf(u8, out, "bad=0") != null);
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

/// The O_TRUNC rows' body under one open posture: `: >` empties a striped
/// and an inline file on one daemon, then across two (A's file emptied by
/// B, B's by A). Under no-open the truncate is the kernel's SETATTR(size
/// 0); under served opens the OPEN carries it — on a foreign-slot file
/// either path is the holder's (decision 0003 §AL.6), shipped.
fn oTruncRow(no_open: bool) !void {
    const io = testing.io;
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    if (no_open) try pinNoOpen(rig) else try rig.env.put("SQUEEZEFS_FUSE_NO_OPEN", "0");
    try rig.env.put("SQUEEZEFS_MW_BIND", "127.0.0.1:0");
    var t_owner_text: [8]u8 = undefined;
    try rig.env.put("SQUEEZEFS_TEST_MEMBERSHIP_T_OWNER_MS", try std.fmt.bufPrint(&t_owner_text, "{d}", .{smoke_t_owner_ms}));
    for ([_][]const u8{ "SQUEEZEFS_FUSE_ATTR_TTL_MS", "SQUEEZEFS_FUSE_ENTRY_TTL_MS", "SQUEEZEFS_FUSE_DIR_ENTRY_TTL_MS", "SQUEEZEFS_FUSE_NEGATIVE_TTL_MS" }) |k| try rig.env.put(k, "60000");
    try rig.formatSet(true);
    try rig.createImage();
    try rig.mountAsSet(&.{});
    _ = try rig.awaitReady(0);
    // One daemon: a striped file and an inline one, each emptied by `: >`.
    {
        const out = try rig.onMount("head -c 3000000 \"$1/image\" > big && echo hello > small && cat big small > /dev/null && : > big && : > small && stat -c %s big small && cat big small | wc -c && mkdir d && echo ok");
        defer gpa.free(out);
        try testing.expectEqualStrings("0\n0\n0\nok\n", out);
    }
    const b = try Peer.init(rig, "b");
    defer b.deinit();
    try b.spawnAsSet(&.{});
    _ = try b.awaitReady();
    // A's file, B's truncate (a cross-owner SETATTR).
    {
        const w = try rig.onMount("head -c 3000000 \"$1/image\" > d/a && stat -c %s d/a");
        defer gpa.free(w);
        try testing.expectEqualStrings("3000000\n", w);
        const seen = try b.onMount("stat -c %s d/a && head -c 16 d/a | wc -c");
        defer gpa.free(seen);
        try testing.expectEqualStrings("3000000\n16\n", seen);
        const t = try b.onMount(": > d/a && stat -c %s d/a && cat d/a | wc -c");
        defer gpa.free(t);
        try testing.expectEqualStrings("0\n0\n", t);
        // A's kernel learns it from its own notifier (0003 §AB.2 (2)):
        // bounded, a lost invalidation keeps the size for the 60 s TTL.
        const a = try rig.onMount("for i in $(seq 100); do [ \"$(stat -c %s d/a)\" = 0 ] && break; sleep 0.02; done; stat -c %s d/a && cat d/a | wc -c");
        defer gpa.free(a);
        try testing.expectEqualStrings("0\n0\n", a);
    }
    // B's file, A's truncate.
    {
        const w = try b.onMount("echo from-b > d/b && cat d/b");
        defer gpa.free(w);
        try testing.expectEqualStrings("from-b\n", w);
        const t = try rig.onMount("for i in $(seq 100); do [ -e d/b ] && break; sleep 0.02; done; cat d/b > /dev/null && : > d/b && stat -c %s d/b");
        defer gpa.free(t);
        try testing.expectEqualStrings("0\n", t);
        const seen = try b.onMount("for i in $(seq 100); do [ \"$(stat -c %s d/b)\" = 0 ] && break; sleep 0.02; done; stat -c %s d/b && cat d/b | wc -c");
        defer gpa.free(seen);
        try testing.expectEqualStrings("0\n0\n", seen);
    }
    {
        const ta = try rig.stats();
        defer gpa.free(ta);
        const tb = try b.stats();
        defer gpa.free(tb);
        const enosys_a = numberAfter(ta, "\"fuse_open_enosys\":") orelse 0;
        const enosys_b = numberAfter(tb, "\"fuse_open_enosys\":") orelse 0;
        std.debug.print("\nsmoke[O_TRUNC, no_open={}]: OPENs answered ENOSYS A {d} / B {d}; slot moves unresolved A {d} / B {d}\n", .{ no_open, enosys_a, enosys_b, numberAfter(ta, "\"slot_move_unresolved\":") orelse 0, numberAfter(tb, "\"slot_move_unresolved\":") orelse 0 });
        if (no_open) {
            try testing.expect(enosys_a >= 1 and enosys_b >= 1);
        } else {
            try testing.expectEqual(@as(u64, 0), enosys_a + enosys_b);
        }
        // No truncate met the move gate's deadline on either side.
        try testing.expectEqual(@as(?u64, 0), numberAfter(ta, "\"slot_move_unresolved\":"));
        try testing.expectEqual(@as(?u64, 0), numberAfter(tb, "\"slot_move_unresolved\":"));
    }
}

test "smoke: O_TRUNC UNDER NO-OPEN TRUNCATES (decision 0003 §AF: INIT drops FUSE_ATOMIC_O_TRUNC, so the open's truncate is a SETATTR(size 0) under the size setter's guard — with the flag kept, the kernel skips that SETATTR and no OPEN carries it) — every TTL class at 60 s: on A, `: > f` over a non-empty file empties it; B JOINS; A writes `d/a`, B empties it with `: >` (B's SETATTR ships to the holder) ⇒ both read size 0 and no byte; B writes `d/b`, A empties it ⇒ both read 0" {
    if (venueMissing(testing.io)) |why| return testkit.skipWhy(@src(), why);
    try oTruncRow(true);
}

test "smoke: O_TRUNC UNDER SERVED OPENS TRUNCATES (the control open arm, SQUEEZEFS_FUSE_NO_OPEN=0 — and mainline's default posture, where SQUEEZEFS_FUSE_ZC_OPEN=1 serves opens for zero-copy: INIT keeps FUSE_ATOMIC_O_TRUNC and the OPEN carries the truncate) — the same rows: on A, `: > f` empties a striped and an inline file; B JOINS; B's `: > d/a` over A's file is the holder's truncate (shipped like a SETATTR — never a local commit the move gate re-issues to its 48 s deadline and answers EIO: found live on 7.3), both read 0; A empties B's `d/b` ⇒ both read 0; no OPEN answered ENOSYS, no slot move unresolved" {
    if (venueMissing(testing.io)) |why| return testkit.skipWhy(@src(), why);
    try oTruncRow(false);
}

/// `.stats` opened, fstat'ed and read whole through the same fd: the bytes
/// and the size the kernel reported for that generation (owned).
const VirtualRead = struct { ino: u64, size: u64, bytes: []u8 };

fn readVirtualWhole(gpa: std.mem.Allocator, path: [:0]const u8) !VirtualRead {
    const fd = try openRaw(path, .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
    defer _ = linux.close(fd);
    var st: linux.Statx = undefined;
    if (linux.errno(linux.statx(fd, "", linux.AT.EMPTY_PATH, linux.STATX.BASIC_STATS, &st)) != .SUCCESS) return error.StatFailed;
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(gpa);
    var buf: [64 << 10]u8 = undefined;
    while (true) {
        const n = linux.read(fd, &buf, buf.len);
        if (linux.errno(n) != .SUCCESS) return error.ReadFailed;
        if (n == 0) break;
        try out.appendSlice(gpa, buf[0..n]);
    }
    return .{ .ino = st.ino, .size = st.size, .bytes = try out.toOwnedSlice(gpa) };
}

/// The idle row's budget (`SQUEEZEFS_MEM_BUDGET_MB`): the small budgets a
/// shared host's fleet share hands every daemon.
const idle_row_budget_mib: u64 = 64;

/// `/proc/<pid>/status`'s `<key>` (a `kB` line) in bytes.
fn procStatusBytes(pid: linux.pid_t, key: []const u8) !u64 {
    var pb: [64]u8 = undefined;
    var buf: [4096]u8 = undefined;
    const text = try Io.Dir.cwd().readFile(testing.io, try std.fmt.bufPrint(&pb, "/proc/{d}/status", .{pid}), &buf);
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |line| {
        if (!std.mem.startsWith(u8, line, key) or line.len <= key.len or line[key.len] != ':') continue;
        var f = std.mem.tokenizeAny(u8, line[key.len + 1 ..], " \t");
        return 1024 * try std.fmt.parseInt(u64, f.next() orelse return error.BadStatus, 10);
    }
    return error.BadStatus;
}

/// The daemon's USER threads: `/proc/<pid>/task`'s entries but the
/// kernel's io_uring workers (`iou-wrk-*`: no user stack, no TLS).
fn userThreads(pid: linux.pid_t) !u64 {
    var pb: [64]u8 = undefined;
    var dir = try Io.Dir.cwd().openDir(testing.io, try std.fmt.bufPrint(&pb, "/proc/{d}/task", .{pid}), .{ .iterate = true });
    defer dir.close(testing.io);
    var it = dir.iterate();
    var n: u64 = 0;
    while (try it.next(testing.io)) |e| {
        var cb: [64]u8 = undefined;
        const comm_path = try std.fmt.bufPrint(&cb, "{s}/comm", .{e.name});
        var comm_buf: [64]u8 = undefined;
        const comm = dir.readFile(testing.io, comm_path, &comm_buf) catch continue;
        if (!std.mem.startsWith(u8, comm, "iou-wrk")) n += 1;
    }
    return n;
}

test "smoke: AN IDLE DAEMON'S RESIDENT MEMORY FOLLOWS ITS BUDGET (the idle-RSS law, docs/evidence/rung-10-idle-rss.md) — format the set → mount under SQUEEZEFS_MEM_BUDGET_MB=64 → ready and two sampler ticks (every mount-time sizer ran, every bound re-derived) → the daemon's VmRSS ≤ 64 MiB + sizing.idleFloorBytes(possible CPUs, its user threads): the pinned payload pool's floor, std's per-thread signal stack and idle stack, the image (red on dev: 2,035 MB on 32 CPUs — the read cache's item tables, index and slab arrays sized by 25 % of the MACHINE's RAM and written at birth, 1 MiB of thread-local reply buffer in each of 146 threads, a 128 MiB pinned ranged slab)" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try rig.env.put("SQUEEZEFS_MEM_BUDGET_MB", std.fmt.comptimePrint("{d}", .{idle_row_budget_mib}));
    try rig.formatSet(true);
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    const deadline = clock.monotonicNs() + 30 * std.time.ns_per_s;
    while (true) {
        const st = try rig.onMount("cat .stats");
        defer gpa.free(st);
        if ((numberAfter(st, "\"mem_budget_ticks\":") orelse 0) >= 2) break;
        if (clock.monotonicNs() >= deadline) return error.Timeout;
        sleepMs(100);
    }
    const pid = rig.child_pid;
    const rss = try procStatusBytes(pid, "VmRSS");
    const threads = try userThreads(pid);
    const cpus = derive.facts().possible_cpus;
    const bound = mem_sizing.idleRssBound(idle_row_budget_mib * derive.MiB, cpus, threads);
    std.debug.print("\nsmoke: idle RSS {d} MiB (anon {d}, file {d}, shmem {d}) over {d} user threads on {d} possible CPUs; the bound {d} MiB = budget {d} + floor {d}\n", .{
        rss >> 20,
        (try procStatusBytes(pid, "RssAnon")) >> 20,
        (try procStatusBytes(pid, "RssFile")) >> 20,
        (try procStatusBytes(pid, "RssShmem")) >> 20,
        threads,
        cpus,
        bound >> 20,
        idle_row_budget_mib,
        mem_sizing.idleFloorBytes(cpus, threads) >> 20,
    });
    try testing.expect(rss <= bound);
    try rig.umount();
    _ = try rig.waitChild();
}

test "smoke: THE VIRTUAL INODES WITHOUT AN OPEN (decision 0003 §AF) — under no-open `.stats` is read through the page cache with no generation pin and no FOPEN_DIRECT_IO: 200 reads while a create storm moves every counter are each ONE whole JSON document whose length is exactly the st_size the same fd's fstat reported; two sequential opens read two generations (different inos, different bytes, each exact); a truncating open and a write are EACCES" {
    const io = testing.io;
    if (venueMissing(io)) |why| return testkit.skipWhy(@src(), why);
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    try pinNoOpen(rig);
    try rig.formatSet(false);
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    const mk = try rig.onMount("mkdir hot && echo ok");
    gpa.free(mk);
    var storm = try Storm.start(rig, rig.mp, "virtual", "v");
    defer storm.deinit(rig);
    var path_buf: [256]u8 = undefined;
    const path = try std.fmt.bufPrintSentinel(&path_buf, "{s}/.stats", .{rig.mp}, 0);
    var prev: ?VirtualRead = null;
    defer if (prev) |p| gpa.free(p.bytes);
    var generations: u64 = 0;
    for (0..200) |_| {
        const r = readVirtualWhole(gpa, path) catch |e| {
            // A dead daemon is named with its log, never a bare ENOTCONN.
            try rig.expectAlive("the .stats reads");
            return e;
        };
        errdefer gpa.free(r.bytes);
        try testing.expectEqual(r.size, @as(u64, r.bytes.len));
        // A torn or cut document fails the parse — a STRICT one: no key
        // repeats inside its object.
        expectStrictStats(gpa, r.bytes) catch |e| {
            std.debug.print("\n--- a torn .stats generation ({d} of {d} B): {t} ---\n{s}\n", .{ r.bytes.len, r.size, e, r.bytes[r.bytes.len -| 200..] });
            return e;
        };
        if (prev) |p| {
            if (p.ino != r.ino) generations += 1;
            gpa.free(p.bytes);
        }
        prev = r;
    }
    // Two sequential opens: two generations, each exact.
    const a = try readVirtualWhole(gpa, path);
    defer gpa.free(a.bytes);
    const b = try readVirtualWhole(gpa, path);
    defer gpa.free(b.bytes);
    try testing.expect(a.ino != b.ino);
    try testing.expect(!std.mem.eql(u8, a.bytes, b.bytes));
    try testing.expectEqual(a.size, @as(u64, a.bytes.len));
    try testing.expectEqual(b.size, @as(u64, b.bytes.len));
    const landed = try storm.finish(rig);
    std.debug.print("\nsmoke[virtual no-open]: 200 whole .stats documents across {d} generation changes while {d} creates landed\n", .{ generations, landed });
    try testing.expect(generations >= 199);
    try testing.expect(landed > 0);
    // 0400 under default_permissions refuses a non-root writer at open in
    // the kernel; root (this test) opens locally — no OPEN refuses it — and
    // every mutation is the daemon's EACCES: a truncating open's SETATTR, a
    // write.
    const rc = linux.open(path.ptr, .{ .ACCMODE = .WRONLY, .TRUNC = true, .CLOEXEC = true }, 0);
    if (linux.errno(rc) == .SUCCESS) _ = linux.close(@intCast(rc));
    try testing.expectEqual(linux.E.ACCES, linux.errno(rc));
    {
        const fd = try openRaw(path, .{ .ACCMODE = .WRONLY, .CLOEXEC = true });
        defer _ = linux.close(fd);
        try testing.expectEqual(linux.E.ACCES, linux.errno(linux.write(fd, "x", 1)));
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
}

// ---------------------------------------------------------------------------
// Inode flags (charter §4 "inode flags"; `fuse/handler/inode_flags.zig`).
// ---------------------------------------------------------------------------

/// A path under the mount's `t/` directory (the inode-flags row's tree).
const FlagPaths = struct {
    buf: [16][linux.PATH_MAX]u8 = undefined,
    n: usize = 0,
    mp: []const u8,

    fn of(self: *FlagPaths, name: []const u8) [:0]const u8 {
        const p = std.fmt.bufPrintSentinel(&self.buf[self.n], "{s}/t/{s}", .{ self.mp, name }, 0) catch unreachable;
        self.n = (self.n + 1) % self.buf.len;
        return p;
    }
};

/// The errno of a raw syscall's return (null = success).
fn errnoOf(rc: usize) ?linux.E {
    const e = linux.errno(rc);
    return if (e == .SUCCESS) null else e;
}

/// `want` or fail loud with what the op answered.
fn expectErrno(label: []const u8, want: ?linux.E, rc: usize) !void {
    const got = errnoOf(rc);
    if (got != want) {
        std.debug.print("\n--- {s}: expected {?t}, got {?t} ---\n", .{ label, want, got });
        return error.WrongErrno;
    }
}

/// `FS_IOC_GETFLAGS` of `path` (an O_RDONLY open; the kernel's private
/// open under the hood is the daemon's business).
fn getFlagsOf(path: [:0]const u8) !u32 {
    const fd = try openRaw(path, .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
    defer _ = linux.close(fd);
    var w: u32 = 0;
    try expectErrno("FS_IOC_GETFLAGS", null, linux.ioctl(fd, handler.inode_flags.FS_IOC_GETFLAGS, @intFromPtr(&w)));
    return w;
}

/// `FS_IOC_FSSETXATTR` of `path` with `xflags` (the second pair's set).
fn fsSetXattrOf(path: [:0]const u8, xflags: u32) !void {
    const fd = try openRaw(path, .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
    defer _ = linux.close(fd);
    var x = handler.inode_flags.Fsxattr.zero;
    x.fsx_xflags = xflags;
    try expectErrno("FS_IOC_FSSETXATTR", null, linux.ioctl(fd, handler.inode_flags.FS_IOC_FSSETXATTR, @intFromPtr(&x)));
}

/// `FS_IOC_FSGETXATTR` of `path`: its `fsx_xflags`.
fn fsGetXattrOf(path: [:0]const u8) !u32 {
    const fd = try openRaw(path, .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
    defer _ = linux.close(fd);
    var x = handler.inode_flags.Fsxattr.zero;
    try expectErrno("FS_IOC_FSGETXATTR", null, linux.ioctl(fd, handler.inode_flags.FS_IOC_FSGETXATTR, @intFromPtr(&x)));
    return x.fsx_xflags;
}

/// The mount's open posture, read off the law itself: with regular-file
/// OPENs served (mainline's zero-copy arm, `SQUEEZEFS_FUSE_ZC_OPEN=1`; the
/// control arm `SQUEEZEFS_FUSE_NO_OPEN=0`) a write-intent open of an
/// immutable file is the kernel's own `may_open` answer, EPERM at the
/// open; under zero-message opens the kernel asks no OPEN, the open
/// SUCCEEDS and the first write is where the law answers.
const OpenPosture = enum { served, zero_message };

fn openPostureOf(imm_p: [:0]const u8) !OpenPosture {
    const rc = linux.open(imm_p.ptr, .{ .ACCMODE = .RDWR, .CLOEXEC = true }, 0);
    if (errnoOf(rc)) |e| {
        try testing.expectEqual(linux.E.PERM, e);
        return .served;
    }
    _ = linux.close(@intCast(rc));
    return .zero_message;
}

/// A write-intent open the law refuses: EPERM at the open under served
/// opens; under zero-message opens the fd, whose first write answers.
fn openRefusedOrFd(posture: OpenPosture, label: []const u8, path: [:0]const u8, flags: linux.O) !?linux.fd_t {
    const rc = linux.open(path.ptr, flags, 0);
    switch (posture) {
        .served => {
            try expectErrno(label, .PERM, rc);
            return null;
        },
        .zero_message => {
            try expectErrno(label, null, rc);
            return @intCast(rc);
        },
    }
}

/// Every mutation of an IMMUTABLE regular file `imm` (its sibling `other`
/// a plain file for the rename-onto and link-from probes): EPERM each, as
/// `may_open`/`may_setattr`/`may_write_xattr`/`may_delete`/`vfs_link`
/// answer on ext4.
fn expectImmutableFileLaw(p: *FlagPaths, posture: OpenPosture, imm: []const u8, other: []const u8, fallocate_served: bool) !void {
    const imm_p = p.of(imm);
    if (try openRefusedOrFd(posture, "open(imm, O_RDWR)", imm_p, .{ .ACCMODE = .RDWR, .CLOEXEC = true })) |fd| {
        defer _ = linux.close(fd);
        try expectErrno("pwrite(imm, 0)", .PERM, linux.pwrite(fd, "X", 1, 0));
        try expectErrno("pwrite(imm, EOF)", .PERM, linux.pwrite(fd, "X", 1, @intCast(fileSize(imm_p))));
        try expectErrno("ftruncate(imm, 0)", .PERM, linux.ftruncate(fd, 0));
        try expectErrno("fchmod(imm)", .PERM, linux.fchmod(fd, 0o600));
        if (fallocate_served) try expectErrno("fallocate(imm)", .PERM, linux.fallocate(fd, 0, 0, 4096));
    }
    if (try openRefusedOrFd(posture, "open(imm, O_WRONLY|O_APPEND)", imm_p, .{ .ACCMODE = .WRONLY, .APPEND = true, .CLOEXEC = true })) |fd| {
        defer _ = linux.close(fd);
        try expectErrno("write(imm, O_APPEND)", .PERM, linux.write(fd, "X", 1));
    }
    try expectErrno("truncate(imm, 0)", .PERM, linux.syscall2(.truncate, @intFromPtr(imm_p.ptr), 0));
    try expectErrno("open(imm, O_WRONLY|O_TRUNC)", .PERM, linux.open(imm_p.ptr, .{ .ACCMODE = .WRONLY, .TRUNC = true, .CLOEXEC = true }, 0));
    try expectErrno("chmod(imm)", .PERM, linux.fchmodat(linux.AT.FDCWD, imm_p.ptr, 0o600));
    try expectErrno("chown(imm)", .PERM, linux.fchownat(linux.AT.FDCWD, imm_p.ptr, 1, 1, 0));
    try expectErrno("utimensat(imm, NULL)", .PERM, linux.utimensat(linux.AT.FDCWD, imm_p.ptr, null, 0));
    const epoch: [2]linux.timespec = .{ .{ .sec = 0, .nsec = 0 }, .{ .sec = 0, .nsec = 0 } };
    try expectErrno("utimensat(imm, epoch)", .PERM, linux.utimensat(linux.AT.FDCWD, imm_p.ptr, &epoch, 0));
    try expectErrno("setxattr(imm, user.new)", .PERM, linux.setxattr(imm_p.ptr, "user.new", "v", 1, 0));
    try expectErrno("setxattr(imm, user.k replace)", .PERM, linux.setxattr(imm_p.ptr, "user.k", "w", 1, 0));
    try expectErrno("removexattr(imm, user.k)", .PERM, linux.removexattr(imm_p.ptr, "user.k"));
    try expectErrno("unlink(imm)", .PERM, linux.unlink(imm_p.ptr));
    try expectErrno("rename(imm → gone)", .PERM, linux.rename(imm_p.ptr, p.of("gone").ptr));
    try expectErrno("rename(other → imm)", .PERM, linux.rename(p.of(other).ptr, imm_p.ptr));
    try expectErrno("link(imm, lnk)", .PERM, linux.link(imm_p.ptr, p.of("lnk").ptr));
    // The reads and the attribute reads pass.
    var v: [8]u8 = undefined;
    try expectErrno("getxattr(imm, user.k)", null, linux.getxattr(imm_p.ptr, "user.k", &v, v.len));
    {
        const fd = try openRaw(imm_p, .{ .ACCMODE = .RDONLY, .CLOEXEC = true });
        defer _ = linux.close(fd);
        var b: [8]u8 = undefined;
        try expectErrno("read(imm)", null, linux.read(fd, &b, b.len));
    }
    try testing.expectEqual(handler.inode_flags.FS_IMMUTABLE_FL, try getFlagsOf(imm_p));
    try testing.expectEqual(handler.inode_flags.FS_XFLAG_IMMUTABLE, try fsGetXattrOf(imm_p));
}

/// Every mutation inside an IMMUTABLE directory `idir` (holding `child`):
/// no entry made, none removed, the directory itself unmovable.
fn expectImmutableDirLaw(p: *FlagPaths, idir: []const u8) !void {
    var child_buf: [64]u8 = undefined;
    const child = try std.fmt.bufPrint(&child_buf, "{s}/child", .{idir});
    var new_buf: [64]u8 = undefined;
    const new = try std.fmt.bufPrint(&new_buf, "{s}/new", .{idir});
    try expectErrno("creat(idir/new)", .PERM, linux.open(p.of(new).ptr, .{ .ACCMODE = .WRONLY, .CREAT = true, .CLOEXEC = true }, 0o644));
    try expectErrno("mkdir(idir/new)", .PERM, linux.mkdir(p.of(new).ptr, 0o755));
    try expectErrno("mknod(idir/new)", .PERM, linux.mknodat(linux.AT.FDCWD, p.of(new).ptr, linux.S.IFIFO | 0o600, 0));
    try expectErrno("symlink(idir/new)", .PERM, linux.symlink("other", p.of(new).ptr));
    try expectErrno("link(other, idir/new)", .PERM, linux.link(p.of("other").ptr, p.of(new).ptr));
    try expectErrno("unlink(idir/child)", .PERM, linux.unlink(p.of(child).ptr));
    try expectErrno("rename(idir/child → idir/new)", .PERM, linux.rename(p.of(child).ptr, p.of(new).ptr));
    try expectErrno("rename(other → idir/new)", .PERM, linux.rename(p.of("other").ptr, p.of(new).ptr));
    try expectErrno("rename(idir/child → out)", .PERM, linux.rename(p.of(child).ptr, p.of("out").ptr));
    try expectErrno("rename(idir → moved)", .PERM, linux.rename(p.of(idir).ptr, p.of("moved").ptr));
    try expectErrno("rmdir(idir)", .PERM, linux.rmdir(p.of(idir).ptr));
    try expectErrno("chmod(idir)", .PERM, linux.fchmodat(linux.AT.FDCWD, p.of(idir).ptr, 0o700));
    try expectErrno("setxattr(idir)", .PERM, linux.setxattr(p.of(idir).ptr, "user.d", "v", 1, 0));
    // Listing and stat pass; the child is still readable.
    var st: linux.Statx = undefined;
    try expectErrno("statx(idir/child)", null, linux.statx(linux.AT.FDCWD, p.of(child).ptr, 0, .{ .SIZE = true }, &st));
    try testing.expectEqual(handler.inode_flags.FS_IMMUTABLE_FL, try getFlagsOf(p.of(idir)));
}

/// An APPEND-ONLY regular file `app`: appends through `O_APPEND` land,
/// everything else answers EPERM; `utimes(NULL)` passes (the kernel's
/// `may_setattr`: `ATTR_TOUCH` on an append-only inode is admitted).
fn expectAppendFileLaw(p: *FlagPaths, posture: OpenPosture, app: []const u8, fallocate_served: bool) !void {
    const app_p = p.of(app);
    const size0 = fileSize(app_p);
    {
        const fd = try openRaw(app_p, .{ .ACCMODE = .WRONLY, .APPEND = true, .CLOEXEC = true });
        defer _ = linux.close(fd);
        try expectErrno("write(app, O_APPEND)", null, linux.write(fd, "tail\n", 5));
        // Linux: a pwrite on an O_APPEND fd appends whatever its offset.
        try expectErrno("pwrite(app, 0, O_APPEND)", null, linux.pwrite(fd, "more\n", 5, 0));
        try expectErrno("ftruncate(app)", .PERM, linux.ftruncate(fd, 0));
        try expectErrno("fchmod(app)", .PERM, linux.fchmod(fd, 0o600));
        if (fallocate_served) {
            // Preallocation alone is admitted on an append-only file.
            try expectErrno("fallocate(app, KEEP_SIZE)", null, linux.fallocate(fd, 0x01, 0, 4096));
            try expectErrno("fallocate(app, PUNCH_HOLE)", .PERM, linux.fallocate(fd, 0x02 | 0x01, 0, 4096));
        }
    }
    try testing.expectEqual(size0 + 10, fileSize(app_p));
    // No O_APPEND: `may_open`'s EPERM at a served open; under zero-message
    // opens the write is where the law answers — at EOF too.
    if (try openRefusedOrFd(posture, "open(app, O_WRONLY)", app_p, .{ .ACCMODE = .WRONLY, .CLOEXEC = true })) |fd| {
        defer _ = linux.close(fd);
        try expectErrno("pwrite(app, 0)", .PERM, linux.pwrite(fd, "X", 1, 0));
        try expectErrno("pwrite(app, EOF)", .PERM, linux.pwrite(fd, "X", 1, @intCast(fileSize(app_p))));
    }
    try expectErrno("truncate(app, 0)", .PERM, linux.syscall2(.truncate, @intFromPtr(app_p.ptr), 0));
    try expectErrno("open(app, O_WRONLY|O_APPEND|O_TRUNC)", .PERM, linux.open(app_p.ptr, .{ .ACCMODE = .WRONLY, .APPEND = true, .TRUNC = true, .CLOEXEC = true }, 0));
    try expectErrno("chmod(app)", .PERM, linux.fchmodat(linux.AT.FDCWD, app_p.ptr, 0o600));
    try expectErrno("chown(app)", .PERM, linux.fchownat(linux.AT.FDCWD, app_p.ptr, 1, 1, 0));
    const epoch: [2]linux.timespec = .{ .{ .sec = 0, .nsec = 0 }, .{ .sec = 0, .nsec = 0 } };
    try expectErrno("utimensat(app, epoch)", .PERM, linux.utimensat(linux.AT.FDCWD, app_p.ptr, &epoch, 0));
    try expectErrno("utimensat(app, NULL)", null, linux.utimensat(linux.AT.FDCWD, app_p.ptr, null, 0));
    try expectErrno("setxattr(app)", .PERM, linux.setxattr(app_p.ptr, "user.new", "v", 1, 0));
    try expectErrno("removexattr(app, user.k)", .PERM, linux.removexattr(app_p.ptr, "user.k"));
    try expectErrno("unlink(app)", .PERM, linux.unlink(app_p.ptr));
    try expectErrno("rename(app → gone)", .PERM, linux.rename(app_p.ptr, p.of("gone").ptr));
    try expectErrno("rename(other → app)", .PERM, linux.rename(p.of("other").ptr, app_p.ptr));
    try expectErrno("link(app, lnk)", .PERM, linux.link(app_p.ptr, p.of("lnk").ptr));
    try testing.expectEqual(handler.inode_flags.FS_APPEND_FL, try getFlagsOf(app_p));
    try testing.expectEqual(handler.inode_flags.FS_XFLAG_APPEND, try fsGetXattrOf(app_p));
}

/// An APPEND-ONLY directory `adir` (holding `child`): entries are made,
/// none removed or renamed out (`may_delete`: `IS_APPEND(dir)`).
fn expectAppendDirLaw(p: *FlagPaths, adir: []const u8) !void {
    var child_buf: [64]u8 = undefined;
    const child = try std.fmt.bufPrint(&child_buf, "{s}/child", .{adir});
    var new_buf: [64]u8 = undefined;
    const new = try std.fmt.bufPrint(&new_buf, "{s}/new", .{adir});
    var new2_buf: [64]u8 = undefined;
    const new2 = try std.fmt.bufPrint(&new2_buf, "{s}/new2", .{adir});
    {
        const rc = linux.open(p.of(new).ptr, .{ .ACCMODE = .WRONLY, .CREAT = true, .CLOEXEC = true }, 0o644);
        try expectErrno("creat(adir/new)", null, rc);
        _ = linux.close(@intCast(rc));
    }
    try expectErrno("mkdir(adir/newdir)", null, linux.mkdir(p.of("adir/newdir").ptr, 0o755));
    try expectErrno("unlink(adir/child)", .PERM, linux.unlink(p.of(child).ptr));
    try expectErrno("unlink(adir/new)", .PERM, linux.unlink(p.of(new).ptr));
    try expectErrno("rmdir(adir/newdir)", .PERM, linux.rmdir(p.of("adir/newdir").ptr));
    try expectErrno("rename(adir/new → adir/new2)", .PERM, linux.rename(p.of(new).ptr, p.of(new2).ptr));
    try expectErrno("rename(adir/new → out)", .PERM, linux.rename(p.of(new).ptr, p.of("out").ptr));
    // A rename INTO it that replaces an entry removes one: refused; onto
    // a fresh name it is a create: admitted.
    try expectErrno("rename(victim → adir/child)", .PERM, linux.rename(p.of("victim").ptr, p.of(child).ptr));
    try expectErrno("rename(victim → adir/new2)", null, linux.rename(p.of("victim").ptr, p.of(new2).ptr));
    try expectErrno("rmdir(adir)", .PERM, linux.rmdir(p.of(adir).ptr));
    try expectErrno("chmod(adir)", .PERM, linux.fchmodat(linux.AT.FDCWD, p.of(adir).ptr, 0o700));
    try testing.expectEqual(handler.inode_flags.FS_APPEND_FL, try getFlagsOf(p.of(adir)));
}

/// The inode-flags row in one open posture: the venue's own (mainline's
/// zero-copy arm serves regular-file opens) or zero-message opens pinned
/// (`SQUEEZEFS_FUSE_NO_OPEN=1`: the kernel asks no OPEN and every refusal
/// is the first mutating request's).
fn inodeFlagsRow(no_open: bool) !void {
    const io = testing.io;
    const gpa = testing.allocator;
    const rig = try Rig.init(gpa, io);
    defer rig.deinit();
    if (no_open) try pinNoOpen(rig);
    try rig.formatSet(true);
    try rig.createImage();
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(0);
    var p: FlagPaths = .{ .mp = rig.mp };
    // The tree: an inline immutable file, a striped one (past the inline
    // bound), an immutable directory with a child, an append-only file and
    // directory, and plain siblings for the rename/link probes; a user
    // xattr on each flagged file BEFORE the flag (the removexattr probe).
    {
        const out = try rig.onMount("mkdir t && cd t && echo hello > imm && head -c 3000000 \"$1/image\" > imm_big && head -c 9000000 \"$1/image\" > imm_striped && echo hello > app && head -c 9000000 \"$1/image\" > app_striped && mkdir idir adir && echo c > idir/child && echo c > adir/child && echo other > other && echo victim > victim && echo plain > plain && stat -c %s imm imm_big imm_striped app app_striped");
        defer gpa.free(out);
        try testing.expectEqualStrings("6\n3000000\n9000000\n6\n9000000\n", out);
    }
    for ([_][]const u8{ "imm", "imm_big", "imm_striped", "app", "app_striped" }) |f| try expectErrno("setxattr(user.k) before the flag", null, linux.setxattr(p.of(f).ptr, "user.k", "v", 1, 0));
    // Is FALLOCATE served by this build (a plain file's preallocation)?
    // Absent, the kernel answers EOPNOTSUPP itself and the law has no
    // fallocate row to judge.
    const fallocate_served = blk: {
        const fd = try openRaw(p.of("plain"), .{ .ACCMODE = .RDWR, .CLOEXEC = true });
        defer _ = linux.close(fd);
        break :blk errnoOf(linux.fallocate(fd, 0x01, 0, 4096)) == null;
    };
    std.debug.print("\nsmoke[flags]: fallocate {s} on this build\n", .{if (fallocate_served) "served" else "absent (EOPNOTSUPP from the kernel)"});
    // chattr/lsattr: the first ioctl pair, as e2fsprogs drives it.
    {
        const out = try rig.onMount("cd t && chattr +i imm imm_big imm_striped idir && chattr +a app app_striped adir && lsattr -d imm imm_big imm_striped idir app app_striped adir | awk '{print $1}' | tr -d -- '-' | tr '\\n' ' '");
        defer gpa.free(out);
        try testing.expectEqualStrings("i i i i a a a ", out);
    }
    // Three write arms: inline (`imm`), the staged resident whose fast
    // path reads no record (`imm_big`: its cached point is staled by the
    // flag's own commit and never refilled), the striped passthrough file
    // whose Shared-class admission reads no record (`imm_striped`: the
    // probe declines off the view's flags).
    const posture = try openPostureOf(p.of("imm"));
    std.debug.print("smoke[flags]: regular-file opens {s} on this mount\n", .{if (posture == .served) "SERVED (the open answers may_open's EPERM)" else "zero-message (the first write answers)"});
    try expectImmutableFileLaw(&p, posture, "imm", "other", fallocate_served);
    try expectImmutableFileLaw(&p, posture, "imm_big", "other", fallocate_served);
    try expectImmutableFileLaw(&p, posture, "imm_striped", "other", fallocate_served);
    try expectImmutableDirLaw(&p, "idir");
    try expectAppendFileLaw(&p, posture, "app", fallocate_served);
    try expectAppendFileLaw(&p, posture, "app_striped", fallocate_served);
    try expectAppendDirLaw(&p, "adir");
    // The plain sibling is untouched by any of it.
    try testing.expectEqual(@as(u32, 0), try getFlagsOf(p.of("plain")));
    // A flag the record cannot hold is EOPNOTSUPP, never silently dropped
    // (a flag change by a user without CAP_LINUX_IMMUTABLE is the KERNEL's
    // EPERM before any request reaches the daemon: `fileattr_set_prepare`).
    {
        const out = try rig.onMount("cd t && (chattr +d plain 2>&1 || true) | grep -c 'Operation not supported' && lsattr -d plain | awk '{print $1}' | tr -d -- '-'");
        defer gpa.free(out);
        try testing.expectEqualStrings("1\n\n", out);
    }
    // The second pair: xfs_io's FS_IOC_FSSETXATTR sets APPEND on `other`,
    // GETFLAGS and lsattr agree, FSSETXATTR clears it.
    try fsSetXattrOf(p.of("other"), handler.inode_flags.FS_XFLAG_APPEND);
    try testing.expectEqual(handler.inode_flags.FS_APPEND_FL, try getFlagsOf(p.of("other")));
    {
        const out = try rig.onMount("cd t && lsattr -d other | awk '{print $1}' | tr -d -- '-'");
        defer gpa.free(out);
        try testing.expectEqualStrings("a\n", out);
        if (try openRefusedOrFd(posture, "open(other, O_WRONLY) while append-only", p.of("other"), .{ .ACCMODE = .WRONLY, .CLOEXEC = true })) |fd| {
            defer _ = linux.close(fd);
            try expectErrno("pwrite(other, 0) while append-only", .PERM, linux.pwrite(fd, "X", 1, 0));
        }
    }
    try fsSetXattrOf(p.of("other"), 0);
    try testing.expectEqual(@as(u32, 0), try getFlagsOf(p.of("other")));
    // `chattr -i` restores: a write lands, the xattr goes; then +i again
    // for the remount.
    {
        const out = try rig.onMount("cd t && chattr -i imm && echo appended >> imm && setfattr -x user.k imm && cat imm && chattr +i imm && lsattr -d imm | awk '{print $1}' | tr -d -- '-'");
        defer gpa.free(out);
        try testing.expectEqualStrings("hello\nappended\ni\n", out);
    }
    // The flags are the record's: umount, fsck clean, remount, the same.
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    {
        const r = try rig.squeezefs(&.{ "fsck", "--offline", "--scrub", rig.meta_uri });
        defer rig.freeRun(r);
        if (!r.term.success() or std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") == null) {
            std.debug.print("\n--- fsck --offline --scrub with the flags set ({f}) ---\n{s}\n--- stderr ---\n{s}\n", .{ r.term, r.stdout, r.stderr });
            return error.FsckNotClean;
        }
    }
    const mark = try rig.logLen();
    try rig.spawnMount(&.{});
    _ = try rig.awaitReady(mark);
    {
        const out = try rig.onMount("cd t && lsattr -d imm imm_big imm_striped idir app app_striped adir other plain | awk '{print $1}' | tr -d -- '-' | tr '\\n' ' '");
        defer gpa.free(out);
        try testing.expectEqualStrings("i i i i a a a   ", out);
    }
    try expectErrno("unlink(imm) after the remount", .PERM, linux.unlink(p.of("imm").ptr));
    try expectErrno("unlink(idir/child) after the remount", .PERM, linux.unlink(p.of("idir/child").ptr));
    if (try openRefusedOrFd(posture, "open(app, O_WRONLY) after the remount", p.of("app"), .{ .ACCMODE = .WRONLY, .CLOEXEC = true })) |fd| {
        defer _ = linux.close(fd);
        try expectErrno("pwrite(app, 0) after the remount", .PERM, linux.pwrite(fd, "X", 1, 0));
    }
    try expectImmutableFileLaw(&p, posture, "imm_big", "other", fallocate_served);
    try expectImmutableFileLaw(&p, posture, "imm_striped", "other", fallocate_served);
    try expectAppendFileLaw(&p, posture, "app_striped", fallocate_served);
    // Cleared, everything goes.
    {
        const out = try rig.onMount("cd t && chattr -i imm imm_big imm_striped idir && chattr -a app app_striped adir && cd .. && rm -rf t && ls | wc -l");
        defer gpa.free(out);
        try testing.expectEqualStrings("0\n", out);
    }
    try rig.umount();
    try testing.expectEqual(std.process.Child.Term{ .exited = 0 }, try rig.waitChild());
    {
        const r = try rig.squeezefs(&.{ "fsck", "--offline", "--scrub", rig.meta_uri });
        defer rig.freeRun(r);
        if (!r.term.success() or std.mem.indexOf(u8, r.stdout, "findings: 0 (clean)") == null) {
            std.debug.print("\n--- fsck --offline --scrub after the flags were cleared ({f}) ---\n{s}\n--- stderr ---\n{s}\n", .{ r.term, r.stdout, r.stderr });
            return error.FsckNotClean;
        }
    }
}

