    b.env = &env_fixed;
    var b_mark = try b.logLen();
    try b.spawnAsSet(&.{});
    _ = try b.awaitLog("ready: ", b_mark, ready_wait_ns);
    _ = try b.awaitLog("enrolled at the coordinator as a fleet READ worker", b_mark, 30 * std.time.ns_per_s);
